INSERT INTO lp_resources (slug, kind, perspective, audience, urgency, evidence_level, emoji, title, summary, body, sections, reading_minutes, min_day, max_day, countries, sex, tags, is_featured, review_status, sort_order) VALUES
  ('in-first-foods-6-months', 'article', 'scientific', 'shared', 'important', 'guideline', '🥣', '{"en":"Starting first foods at 6 months","bn":"৬ মাসে প্রথম খাবার শুরু"}'::jsonb, '{"en":"From about 6 months, breast milk alone is no longer enough. Start soft, thick home foods while you keep breastfeeding.","bn":"প্রায় ৬ মাস থেকে শুধু বুকের দুধে আর চলে না। বুকের দুধ চালিয়ে যান, সাথে নরম ও ঘন ঘরের খাবার শুরু করুন।"}'::jsonb, '{"en":"## Why at 6 months\nFor the first 6 months, breast milk gives your baby everything they need. From about 6 months (180 days), your baby needs more energy, iron and other nutrients than breast milk alone can give. Breast milk stays very important: first foods are added to it, not given instead of it.\n\n## Signs your baby is ready\n- Holds the head steady and sits with a little support\n- Watches you eat and reaches for food\n- Opens the mouth when a spoon comes near\n- Moves food to the back of the mouth instead of pushing it all out\n\nStarting well before 6 months is not advised: the gut is not ready and the baby may drink less breast milk. Starting much later can slow growth.\n\n## The first days\nBegin with 2–3 teaspoons of a soft, thick food once or twice a day. Good first foods from a Bangladeshi kitchen are soft rice mashed with lentils and vegetables (khichuri), mashed potato or pumpkin, mashed ripe banana or papaya, well-cooked egg and boneless mashed fish. Add a few drops of oil for energy. The food should be thick enough to stay on the spoon. Watery suji or thin rice water fills the small stomach but gives little nourishment.\n\nIncrease the amount slowly. Aim for 2–3 meals a day during 6–8 months. Within the first weeks, offer foods from different groups, including animal foods such as egg, fish, chicken or liver.\n\n## Keep it calm\nSit your baby upright on your lap or in a safe seat. Let them see, smell and touch the food. Many babies push food out at first; this is learning, not refusal. Offer the same food again on other days. It can take many tries before a baby accepts a new taste.\n\n## What to leave out\n- Honey before 1 year\n- Added salt and sugar\n- Tea, coffee, soft drinks and packaged juice\n- Chips, chanachur, sweet biscuits and sweets\n- Whole nuts and hard pieces that can choke\n\n## Share the job\nOne parent can cook while the other feeds, then swap. If grandparents or a helper also feed the baby, share these tips with them so that everyone feeds the same way.","bn":"## কেন ৬ মাসে\nপ্রথম ৬ মাস শিশুর যা দরকার, সবই বুকের দুধে থাকে। প্রায় ৬ মাস (১৮০ দিন) বয়স থেকে শিশুর শক্তি, আয়রন ও অন্যান্য পুষ্টির চাহিদা এতটা বাড়ে যে শুধু বুকের দুধে তা আর পূরণ হয় না। তবে বুকের দুধ তখনো খুব জরুরি। বাড়তি খাবার দেওয়া হয় বুকের দুধের পাশাপাশি, বদলে নয়।\n\n## শিশু প্রস্তুত কিনা বুঝবেন যেভাবে\n- মাথা শক্ত করে রাখতে পারে, একটু ধরে বসালে বসতে পারে\n- আপনি খেলে তাকিয়ে থাকে, খাবারের দিকে হাত বাড়ায়\n- চামচ কাছে আনলে মুখ খোলে\n- খাবার পুরোটা ঠেলে বের না করে গলার দিকে নিতে পারে\n\n৬ মাসের অনেক আগে শুরু করা ঠিক নয়: পেট তখনো তৈরি থাকে না, আর শিশু বুকের দুধ কম খায়। আবার অনেক দেরিতে শুরু করলে বৃদ্ধি পিছিয়ে যেতে পারে।\n\n## প্রথম কয়েক দিন\nদিনে এক-দুইবার ২–৩ চা-চামচ নরম, ঘন খাবার দিয়ে শুরু করুন। আমাদের রান্নাঘরেই ভালো প্রথম খাবার আছে: চাল-ডাল-সবজির নরম খিচুড়ি, চটকানো আলু বা মিষ্টিকুমড়া, পাকা কলা বা পেঁপে চটকানো, ভালোভাবে সেদ্ধ ডিম, কাঁটা বাছা মাছ চটকানো। শক্তি বাড়াতে কয়েক ফোঁটা তেল দিন। খাবার এমন ঘন হবে যেন চামচে আটকে থাকে। পাতলা সুজি বা ভাতের মাড় ছোট্ট পেট ভরিয়ে দেয়, কিন্তু পুষ্টি দেয় খুব কম।\n\nধীরে ধীরে পরিমাণ বাড়ান। ৬–৮ মাসে দিনে ২–৩ বার খাবারের লক্ষ্য রাখুন। প্রথম কয়েক সপ্তাহের মধ্যেই নানা রকম খাবার দিন, ডিম, মাছ, মুরগি বা কলিজার মতো প্রাণিজ খাবারসহ।\n\n## শান্তভাবে খাওয়ান\nশিশুকে কোলে বা নিরাপদ আসনে সোজা করে বসান। খাবার দেখতে, গন্ধ নিতে, ছুঁয়ে দেখতে দিন। শুরুতে অনেক শিশু খাবার জিভ দিয়ে বের করে দেয়; এটা শেখার অংশ, অনীহা নয়। একই খাবার অন্য দিনে আবার দিন। নতুন স্বাদ মেনে নিতে অনেকবার চেষ্টা লাগতে পারে।\n\n## যা দেবেন না\n- ১ বছরের আগে মধু\n- বাড়তি লবণ ও চিনি\n- চা, কফি, কোমল পানীয়, প্যাকেটের জুস\n- চিপস, চানাচুর, মিষ্টি বিস্কুট ও মিষ্টি\n- আস্ত বাদাম বা শক্ত টুকরো, যা গলায় আটকাতে পারে\n\n## কাজ ভাগ করে নিন\nএকজন রান্না করুন, অন্যজন খাওয়ান, পরের দিন উল্টো। দাদা-দাদি, নানা-নানি বা সহকারী কেউ খাওয়ালে তাঁদেরও এগুলো জানিয়ে দিন, যাতে সবাই একইভাবে খাওয়ান।"}'::jsonb, '{"seek_help":{"en":["Your baby chokes or gags often on soft foods","Your baby is not gaining weight on the growth card","A rash, swelling or vomiting each time after a certain food","Your baby was born early or has a health condition: ask when to start"],"bn":["নরম খাবারেও বারবার গলায় আটকায় বা ওয়াক ওঠে","বৃদ্ধি কার্ডে ওজন বাড়ছে না","নির্দিষ্ট কোনো খাবারের পর প্রতিবার র‍্যাশ, ফোলা বা বমি","শিশু সময়ের আগে জন্মেছে বা কোনো অসুখ আছে: কবে শুরু করবেন জিজ্ঞেস করুন"]}}'::jsonb, 4, 183, 274, '{}'::text[], 'any', ARRAY['first foods', 'complementary feeding', 'weaning', 'solids', '6 months', 'khichuri']::text[], false, 'in_review'::lp_review_status, 4001),
  ('in-how-much-how-often', 'article', 'scientific', 'shared', 'important', 'guideline', '🍽️', '{"en":"How much and how often: 6 to 23 months","bn":"কতটুকু ও কতবার: ৬ থেকে ২৩ মাস"}'::jsonb, '{"en":"Meals, amounts and textures grow with your child. A simple guide by age, based on WHO feeding advice.","bn":"বয়সের সাথে খাবারের বার, পরিমাণ ও ঘনত্ব বাড়ে। বিশ্ব স্বাস্থ্য সংস্থার পরামর্শ অনুযায়ী বয়সভিত্তিক সহজ নির্দেশনা।"}'::jsonb, '{"en":"## The basic pattern\nWHO advises that a breastfed child gets meals 2–3 times a day at 6–8 months, and 3–4 times a day from 9 to 23 months, with 1–2 healthy snacks if the child is hungry. Breastfeeding continues whenever the child wants, day and night.\n\n## A rough guide to amounts\nThese starting points are used in many feeding programmes. Your child''s appetite will change from day to day. Use an ordinary 250 ml cup or bowl to judge.\n\n- **6–8 months:** start with 2–3 spoonfuls per meal and slowly build up to about half a cup. Texture: thick and well mashed.\n- **9–11 months:** about half a cup per meal. Texture: finely chopped or mashed, plus soft finger foods the baby can pick up.\n- **12–23 months:** about three-quarters to one full cup per meal. Texture: family food, cut small and soft.\n\n## If your child is not breastfed\nA child who is not breastfed needs more meals, often 4–5 a day plus 1–2 snacks, and milk from another source. Ask your health worker what milk and how much is right for your child.\n\n## Thick is better than thin\nSmall stomachs fill quickly. Thin suji, watery porridge or plain rice water fill the stomach without giving enough energy. Make food thick enough to stay on the spoon. A little oil, mashed egg, fish or lentils raises the value of every meal.\n\n## Snacks that help\nGood snacks are pieces of ripe banana, papaya or mango, a boiled egg, soft roti pieces or homemade suji with milk. Chips, chanachur, sweet biscuits and soft drinks fill the child up but give very little nutrition.\n\n## During and after illness\nWhen your child is unwell, breastfeed more often and offer small amounts of soft foods they like. After the illness, give one extra meal a day for about two weeks to help them catch up.\n\n## Watch your child, not only the bowl\nSome days your child will eat less, some days more. Stop when they turn away, close their mouth or push the food away. What matters is steady growth over weeks, so take the growth card to every check-up.","bn":"## মূল নিয়ম\nবিশ্ব স্বাস্থ্য সংস্থা বলে, বুকের দুধ খাওয়া শিশুকে ৬–৮ মাসে দিনে ২–৩ বার এবং ৯ থেকে ২৩ মাসে দিনে ৩–৪ বার খাবার দিতে হবে। খিদে থাকলে মাঝে ১–২ বার হালকা পুষ্টিকর নাশতা দিন। পাশাপাশি দিনে-রাতে শিশু যখনই চায়, বুকের দুধ চলবে।\n\n## পরিমাণের মোটামুটি হিসাব\nএগুলো অনেক পুষ্টি কর্মসূচিতে ব্যবহৃত শুরুর হিসাব। শিশুর খিদে দিন দিন বদলাবে। মাপার জন্য সাধারণ ২৫০ মিলি-র একটি কাপ বা বাটি ধরুন।\n\n- **৬–৮ মাস:** প্রতিবার ২–৩ চামচ দিয়ে শুরু করে ধীরে ধীরে আধা কাপ পর্যন্ত। ঘনত্ব: ঘন ও ভালোভাবে চটকানো।\n- **৯–১১ মাস:** প্রতিবার প্রায় আধা কাপ। ঘনত্ব: মিহি করে কাটা বা চটকানো, সাথে নরম টুকরো যা শিশু নিজে হাতে তুলে খেতে পারে।\n- **১২–২৩ মাস:** প্রতিবার প্রায় পৌনে এক কাপ থেকে এক কাপ। ঘনত্ব: পরিবারের খাবার, ছোট ও নরম করে কাটা।\n\n## শিশু বুকের দুধ না খেলে\nযে শিশু বুকের দুধ খায় না, তার আরও বেশিবার খাবার লাগে, সাধারণত দিনে ৪–৫ বার, সাথে ১–২ বার নাশতা এবং অন্য উৎস থেকে দুধ। কোন দুধ, কতটুকু দেবেন, স্বাস্থ্যকর্মীর কাছ থেকে জেনে নিন।\n\n## পাতলা নয়, ঘন\nছোট পেট দ্রুত ভরে যায়। পাতলা সুজি, পানির মতো জাউ বা শুধু ভাতের মাড় পেট ভরায়, কিন্তু যথেষ্ট শক্তি দেয় না। খাবার এমন ঘন রাখুন যেন চামচে আটকে থাকে। একটু তেল, চটকানো ডিম, মাছ বা ডাল দিলে প্রতিটি খাবারের পুষ্টি বাড়ে।\n\n## উপকারী নাশতা\nপাকা কলা, পেঁপে বা আমের টুকরো, সেদ্ধ ডিম, নরম রুটির টুকরো, ঘরে বানানো দুধ-সুজি ভালো নাশতা। চিপস, চানাচুর, মিষ্টি বিস্কুট ও কোমল পানীয় পেট ভরায় ঠিকই, কিন্তু পুষ্টি প্রায় দেয় না।\n\n## অসুখের সময় ও পরে\nশিশু অসুস্থ হলে বেশি বেশি বুকের দুধ দিন, আর পছন্দের নরম খাবার অল্প অল্প করে দিন। অসুখ সেরে গেলে প্রায় দুই সপ্তাহ দিনে একবার বাড়তি খাবার দিন, যাতে ঘাটতি পূরণ হয়।\n\n## বাটি নয়, শিশুকে দেখুন\nকোনো দিন শিশু কম খাবে, কোনো দিন বেশি। মুখ ফিরিয়ে নিলে, মুখ বন্ধ করলে বা খাবার ঠেলে দিলে থামুন। আসল কথা হলো কয়েক সপ্তাহ ধরে নিয়মিত বৃদ্ধি, তাই প্রতিটি চেকআপে বৃদ্ধি কার্ড সাথে নিন।"}'::jsonb, '{"seek_help":{"en":["Weight is flat or falling on the growth card","Your child seems tired, pale or often ill","Your child eats very little for more than a few days","You are worried about how much your child eats"],"bn":["বৃদ্ধি কার্ডে ওজন থেমে আছে বা কমছে","শিশুকে ক্লান্ত, ফ্যাকাশে বা প্রায়ই অসুস্থ মনে হয়","কয়েক দিনের বেশি খুব কম খাচ্ছে","শিশু কতটুকু খায় তা নিয়ে আপনি চিন্তিত"]}}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['meal frequency', 'portion', 'amount', 'texture', 'snacks', 'feeding schedule']::text[], false, 'in_review'::lp_review_status, 4002),
  ('in-food-variety-iron-egg', 'article', 'scientific', 'shared', 'important', 'guideline', '🥚', '{"en":"Food variety, iron and the everyday egg","bn":"নানা রকম খাবার, আয়রন আর প্রতিদিনের ডিম"}'::jsonb, '{"en":"Young children need many food groups every day, and an animal food such as egg, fish or meat daily for iron and growth.","bn":"ছোট শিশুর প্রতিদিন নানা রকম খাবার লাগে, আর আয়রন ও বৃদ্ধির জন্য প্রতিদিন একটি প্রাণিজ খাবার, যেমন ডিম, মাছ বা মাংস।"}'::jsonb, '{"en":"## Why variety matters\nBetween 6 and 24 months a child grows fast, but the stomach is small. Every spoonful has to count. Rice alone fills the stomach but cannot give enough iron, zinc, vitamin A or protein. Health programmes count eight food groups, and a good day for a young child includes at least five of them:\n\n1. Breast milk\n2. Rice, roti, potato and other grains or roots\n3. Lentils, beans, nuts and seeds (ground or as paste)\n4. Milk, yoghurt and cheese\n5. Fish, meat, chicken and liver\n6. Eggs\n7. Yellow and orange fruits and dark green leafy vegetables (ripe mango, papaya, pumpkin, carrot, lal shak, pui shak, kochu shak)\n8. Other fruits and vegetables\n\n## Iron: the hidden need\nFrom about 6 months, the iron a baby was born with runs low, and breast milk has only a little. Too little iron can cause anaemia, which makes children tired and can slow learning. WHO advises meat, fish or eggs every day.\n\nThe best iron sources are liver, red meat, chicken and fish. Small fish such as mola eaten with soft bones ground fine also give calcium and vitamin A. Plant iron from lentils and leafy greens is absorbed better when the same meal has a vitamin C food such as guava, orange, lemon or tomato. Tea taken with meals lowers iron absorption, and children under 2 should not be given tea at all.\n\n## The everyday egg\nAn egg is small, cheap, easy to cook and packed with protein, fat and vitamins. From 6 months you can give the whole egg, white and yolk, as long as it is fully cooked. One egg a day is a simple habit that makes a real difference. There is no need to wait to give egg or fish; giving these foods early and regularly is fine for most babies.\n\n## A little oil\nA teaspoon of oil in khichuri or mashed vegetables adds energy and helps the body use vitamin A.\n\n## When money is tight\nEggs, small local fish, lentils, seasonal leafy greens and fruits like papaya and banana are often the best value. Your community clinic or a nutrition worker can help you plan meals on your budget.","bn":"## কেন নানা রকম খাবার\n৬ থেকে ২৪ মাসে শিশু খুব দ্রুত বাড়ে, অথচ পেট ছোট। তাই প্রতিটি চামচ খাবার কাজের হতে হবে। শুধু ভাত পেট ভরায়, কিন্তু যথেষ্ট আয়রন, জিংক, ভিটামিন এ বা আমিষ দিতে পারে না। পুষ্টি কর্মসূচিতে খাবারকে আটটি দলে ভাগ করা হয়। ছোট শিশুর একটি ভালো দিনে এর অন্তত পাঁচটি দল থাকে:\n\n১. বুকের দুধ\n২. ভাত, রুটি, আলু ও অন্যান্য শস্য বা কন্দ\n৩. ডাল, শিম জাতীয় দানা, বাদাম ও বীজ (গুঁড়া বা পেস্ট করে)\n৪. দুধ, দই ও পনির\n৫. মাছ, মাংস, মুরগি ও কলিজা\n৬. ডিম\n৭. হলুদ ও কমলা রঙের ফল এবং গাঢ় সবুজ শাক (পাকা আম, পেঁপে, মিষ্টিকুমড়া, গাজর, লাল শাক, পুঁই শাক, কচু শাক)\n৮. অন্যান্য ফল ও সবজি\n\n## আয়রন: চোখে না পড়া চাহিদা\nজন্মের সময় শিশুর শরীরে যে আয়রন জমা থাকে, ৬ মাসের দিকে তা ফুরিয়ে আসে, আর বুকের দুধে আয়রন থাকে অল্প। আয়রনের ঘাটতিতে রক্তস্বল্পতা (anaemia) হয়, শিশু ক্লান্ত থাকে, শেখাও পিছিয়ে যেতে পারে। বিশ্ব স্বাস্থ্য সংস্থা প্রতিদিন মাছ, মাংস বা ডিম দিতে বলে।\n\nআয়রনের সবচেয়ে ভালো উৎস কলিজা, লাল মাংস, মুরগি ও মাছ। মলার মতো ছোট মাছ নরম কাঁটাসহ মিহি করে বেটে দিলে ক্যালসিয়াম ও ভিটামিন এ-ও মেলে। ডাল ও শাকের আয়রন শরীরে ভালো ঢোকে, যদি একই খাবারে পেয়ারা, কমলা, লেবু বা টমেটোর মতো ভিটামিন সি থাকে। খাবারের সাথে চা খেলে আয়রন কম শোষিত হয়, আর ২ বছরের কম শিশুকে চা একদম দেবেন না।\n\n## প্রতিদিনের ডিম\nডিম ছোট, সস্তা, রান্না সহজ, আর আমিষ, চর্বি ও ভিটামিনে ভরা। ৬ মাস থেকেই পুরো ডিম, সাদা অংশ ও কুসুম দুটোই দিতে পারেন, শুধু ভালোভাবে সেদ্ধ হতে হবে। দিনে একটি ডিম সহজ একটি অভ্যাস, কিন্তু উপকার অনেক। ডিম বা মাছ দেরিতে শুরু করার দরকার নেই; বেশিরভাগ শিশুর জন্য আগে থেকে নিয়মিত দেওয়াই ভালো।\n\n## একটু তেল\nখিচুড়ি বা সবজি চটকানোর সাথে এক চা-চামচ তেল শক্তি বাড়ায় এবং ভিটামিন এ কাজে লাগাতে সাহায্য করে।\n\n## টাকা কম থাকলে\nডিম, দেশি ছোট মাছ, ডাল, মৌসুমি শাক আর পেঁপে-কলার মতো ফল কম খরচে বেশি পুষ্টি দেয়। আপনার বাজেটে খাবারের পরিকল্পনা করতে কমিউনিটি ক্লিনিক বা পুষ্টিকর্মীর সাহায্য নিন।"}'::jsonb, '{"seek_help":{"en":["Your child looks pale inside the eyelids, lips or palms","Your child is unusually tired or breathless with play","Lips or face swell, or there is wheezing after a new food: get help at once"],"bn":["চোখের পাতার ভেতর, ঠোঁট বা হাতের তালু ফ্যাকাশে দেখায়","খেলতে গিয়ে অস্বাভাবিক ক্লান্ত হয় বা হাঁপায়","নতুন খাবারের পর ঠোঁট বা মুখ ফুলে যায় বা শ্বাসে শাঁ শাঁ শব্দ: এখনই সাহায্য নিন"]}}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['iron', 'egg', 'fish', 'animal source foods', 'dietary diversity', 'anaemia', 'vitamin a']::text[], false, 'in_review'::lp_review_status, 4003),
  ('in-responsive-feeding', 'article', 'scientific', 'shared', 'important', 'guideline', '🤲', '{"en":"Responsive feeding: encourage, never force","bn":"সাড়া দিয়ে খাওয়ানো: উৎসাহ দিন, জোর নয়"}'::jsonb, '{"en":"Watch your child''s hunger and fullness signs, feed slowly and kindly, and let them learn to eat. Force-feeding makes eating harder.","bn":"শিশুর খিদে ও পেট ভরার ইশারা বুঝুন, ধীরে ও মমতা নিয়ে খাওয়ান, নিজে খেতে শিখতে দিন। জোর করে খাওয়ালে খাওয়া আরও কঠিন হয়।"}'::jsonb, '{"en":"## What it means\nResponsive feeding means you notice what your child is telling you and answer it. You decide what food is offered, when and where. Your child decides how much to eat. WHO advises feeding slowly and patiently, encouraging but not forcing, and talking with your child during meals.\n\n## Hunger and fullness signs\nHungry: leans forward, opens the mouth, reaches for food, gets excited when food appears.\n\nFull: turns the head away, closes the mouth, pushes the spoon or bowl, plays with food, cries when the spoon comes.\n\nWhen you see the full signs, stop. Offer again at the next meal.\n\n## Why force does not work\nIn many homes children are fed while held down, with the nose pinched, or while crying. This can push food into the airway and cause choking or chest infection. It also teaches the child that meals are a fight, and many such children eat even less over time. Threats, scolding and long chases around the house have the same effect.\n\n## What helps\n- Sit together at a regular time, with the child upright and facing you\n- Turn off the TV and phone so the child can notice the food and you\n- Talk, smile and name the food: “This is egg, yellow egg”\n- Give a spoon or soft pieces to hold; let them try, even if it is messy\n- If a food is refused, offer it again another day, mixed with a liked food\n- Keep meals to about 20–30 minutes, then calmly finish\n- Eat the same healthy foods yourself; children copy what they see\n\n## Many hands, one way\nGrandparents, aunts and helpers often feed young children. Agree as a family on the same calm approach. A father who feeds one meal a day gives the mother rest and builds his own bond with the child.\n\n## A note on appetite\nAppetite goes up and down with growth spurts, teething and illness. One small meal is not a problem. If your child keeps growing well on the card and is active, they are most likely eating enough.","bn":"## এর মানে কী\nসাড়া দিয়ে খাওয়ানো মানে শিশু কী বোঝাতে চাইছে তা খেয়াল করা এবং সেই অনুযায়ী চলা। কী খাবার, কখন ও কোথায় দেবেন, তা ঠিক করবেন আপনি। কতটুকু খাবে, তা ঠিক করবে শিশু। বিশ্ব স্বাস্থ্য সংস্থা বলে, ধীরে ও ধৈর্য নিয়ে খাওয়ান, উৎসাহ দিন কিন্তু জোর করবেন না, আর খাওয়ার সময় শিশুর সাথে কথা বলুন।\n\n## খিদে ও পেট ভরার ইশারা\nখিদে পেলে: সামনে ঝুঁকে আসে, মুখ খোলে, খাবারের দিকে হাত বাড়ায়, খাবার দেখে খুশি হয়।\n\nপেট ভরলে: মুখ ঘুরিয়ে নেয়, মুখ বন্ধ করে, চামচ বা বাটি ঠেলে দেয়, খাবার নিয়ে খেলে, চামচ দেখলেই কাঁদে।\n\nপেট ভরার ইশারা দেখলে থামুন। পরের বেলায় আবার দিন।\n\n## জোর করলে কেন কাজ হয় না\nঅনেক বাড়িতে শিশুকে চেপে ধরে, নাক টিপে বা কাঁদতে কাঁদতে খাওয়ানো হয়। এতে খাবার শ্বাসনালিতে ঢুকে গলায় আটকাতে বা বুকে সংক্রমণ হতে পারে। শিশু শেখে খাওয়া মানে লড়াই, আর অনেক শিশু সময়ের সাথে আরও কম খায়। ভয় দেখানো, বকা দেওয়া বা সারা বাড়ি পেছন পেছন ঘোরাও একই ফল আনে।\n\n## যা কাজে দেয়\n- নির্দিষ্ট সময়ে একসাথে বসুন, শিশু সোজা হয়ে আপনার দিকে মুখ করে বসবে\n- টিভি ও ফোন বন্ধ রাখুন, যাতে শিশু খাবার ও আপনাকে খেয়াল করে\n- কথা বলুন, হাসুন, খাবারের নাম বলুন: “এটা ডিম, হলুদ ডিম”\n- হাতে একটা চামচ বা নরম টুকরো দিন; নোংরা হলেও নিজে চেষ্টা করতে দিন\n- কোনো খাবার না খেলে অন্য দিন পছন্দের খাবারের সাথে মিশিয়ে আবার দিন\n- খাওয়ার সময় মোটামুটি ২০–৩০ মিনিট রাখুন, তারপর শান্তভাবে শেষ করুন\n- নিজেরাও একই স্বাস্থ্যকর খাবার খান; শিশু যা দেখে তা-ই শেখে\n\n## হাত অনেক, নিয়ম এক\nদাদি-নানি, খালা-ফুপু বা সহকারী অনেক সময় শিশুকে খাওয়ান। পরিবারে সবাই মিলে একই শান্ত পদ্ধতিতে একমত হোন। বাবা দিনে এক বেলা খাওয়ালে মা একটু বিশ্রাম পান, আর বাবার সাথে শিশুর বন্ধনও গড়ে ওঠে।\n\n## খিদে নিয়ে একটি কথা\nবৃদ্ধির ধাপ, দাঁত ওঠা বা অসুখের সময় খিদে কমে-বাড়ে। এক বেলা কম খাওয়া সমস্যা নয়। কার্ডে বৃদ্ধি ঠিক থাকলে এবং শিশু চঞ্চল থাকলে, খুব সম্ভবত সে যথেষ্টই খাচ্ছে।"}'::jsonb, '{"avoid":{"en":["Pinching the nose or pouring food or milk into a crying child''s mouth","Feeding while the child lies flat","Rewarding with sweets or punishing for not eating"],"bn":["নাক টিপে বা কান্নারত শিশুর মুখে খাবার বা দুধ ঢেলে দেওয়া","শিশুকে শুইয়ে খাওয়ানো","খেলে মিষ্টি পুরস্কার, না খেলে শাস্তি"]},"seek_help":{"en":["Your child coughs or chokes during most meals","Weight is falling on the growth card","Meals have become very stressful for the family"],"bn":["বেশিরভাগ বেলায় খাওয়ার সময় কাশি আসে বা গলায় আটকায়","বৃদ্ধি কার্ডে ওজন কমছে","খাওয়ার সময়টা পরিবারের জন্য খুব চাপের হয়ে গেছে"]}}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['responsive feeding', 'force feeding', 'picky eating', 'self feeding', 'mealtime']::text[], false, 'in_review'::lp_review_status, 4004),
  ('in-breastfeeding-to-two', 'article', 'scientific', 'shared', 'important', 'guideline', '🤱', '{"en":"Keep breastfeeding to 2 years","bn":"২ বছর পর্যন্ত বুকের দুধ চালিয়ে যান"}'::jsonb, '{"en":"Breast milk stays a valuable food alongside family meals. WHO advises continuing breastfeeding to 2 years of age or beyond.","bn":"পরিবারের খাবারের পাশাপাশি বুকের দুধ মূল্যবান খাবার হিসেবেই থাকে। বিশ্ব স্বাস্থ্য সংস্থা ২ বছর বা তার বেশি সময় বুকের দুধ চালিয়ে যেতে বলে।"}'::jsonb, '{"en":"## Why it still matters\nAfter 6 months, breast milk is no longer enough on its own, but it is still one of the most valuable foods your child gets. WHO notes that breast milk can provide half or more of a child''s energy needs between 6 and 12 months, and about one third between 12 and 24 months. It also gives protein, vitamins and protection against infections such as diarrhoea and pneumonia. When a child is sick and refuses food, breast milk is often the one thing they still take.\n\n## Food first or breast first?\nAt 6–8 months many mothers breastfeed first and offer food soon after. As your child grows, offer food first at mealtimes and breastfeed between meals and at night. Either way, keep breastfeeding whenever your child wants.\n\n## For working mothers\nGoing back to work does not have to end breastfeeding.\n- Breastfeed just before you leave and as soon as you return\n- Express milk at work if you can, and store it clean and cool\n- Feed more at night and on days off\n- Whoever cares for the child can give expressed milk by cup, not bottle\n\nAsk your employer about a private place and time to express. Bangladeshi law provides maternity leave for many working women; check what applies to you.\n\n## Look after the mother\nBreastfeeding mothers need good food, plenty of water and rest. A mother who eats rice, lentils, fish or egg, vegetables and fruit every day does not need special diets. Family can help by taking over cooking, cleaning and night-time settling now and then.\n\n## Common worries\n- **“My milk is not enough any more.”** Supply follows demand. The more often the child feeds, the more milk there is. Growing weight on the card is the best sign.\n- **“The child only wants breast milk.”** See our guide on this; it is common and usually improves with patience.\n- **“Breastfeeding is spoiling the child.”** There is no evidence for this. Closeness at this age builds security, not weakness.\n\n## The father''s part\nFathers can protect breastfeeding: bring water and food while the mother feeds, answer relatives who doubt her milk, and take over burping, bathing and play so she can rest.","bn":"## এখনো কেন জরুরি\n৬ মাসের পর শুধু বুকের দুধে চলে না, কিন্তু শিশুর খাবারের মধ্যে এটি তখনো সবচেয়ে মূল্যবানগুলোর একটি। বিশ্ব স্বাস্থ্য সংস্থা জানায়, ৬ থেকে ১২ মাসে শিশুর শক্তির চাহিদার অর্ধেক বা তার বেশি এবং ১২ থেকে ২৪ মাসে প্রায় এক-তৃতীয়াংশ বুকের দুধ থেকে আসতে পারে। এতে আমিষ, ভিটামিন আর ডায়রিয়া ও নিউমোনিয়ার মতো সংক্রমণ থেকে সুরক্ষাও মেলে। অসুস্থ শিশু যখন কিছুই খেতে চায় না, তখনো সাধারণত বুকের দুধটা খায়।\n\n## আগে খাবার, না আগে বুকের দুধ?\n৬–৮ মাসে অনেক মা আগে বুকের দুধ দিয়ে একটু পরে খাবার দেন। শিশু বড় হলে খাবারের সময় আগে খাবার দিন, আর মাঝের সময়ে ও রাতে বুকের দুধ দিন। যেভাবেই হোক, শিশু চাইলেই বুকের দুধ দিন।\n\n## কর্মজীবী মায়েদের জন্য\nকাজে ফিরলেই বুকের দুধ বন্ধ করতে হবে, এমন নয়।\n- বের হওয়ার ঠিক আগে এবং ফিরেই বুকের দুধ দিন\n- সম্ভব হলে কর্মস্থলে দুধ চেপে বের করে পরিষ্কার পাত্রে ঠান্ডা জায়গায় রাখুন\n- রাতে ও ছুটির দিনে বেশি বেশি দিন\n- যিনি শিশুকে দেখেন, তিনি চেপে রাখা দুধ ফিডারে নয়, কাপে খাওয়াবেন\n\nদুধ বের করার জন্য আলাদা জায়গা ও সময় নিয়ে কর্মস্থলে কথা বলুন। বাংলাদেশের আইনে অনেক কর্মজীবী নারীর মাতৃত্বকালীন ছুটির ব্যবস্থা আছে; আপনার ক্ষেত্রে কী প্রযোজ্য, জেনে নিন।\n\n## মায়ের যত্ন\nবুকের দুধ খাওয়ানো মায়ের ভালো খাবার, যথেষ্ট পানি ও বিশ্রাম দরকার। প্রতিদিন ভাত, ডাল, মাছ বা ডিম, সবজি ও ফল খেলে বিশেষ কোনো খাদ্যতালিকা লাগে না। পরিবারের অন্যরা মাঝে মাঝে রান্না, ঘরের কাজ আর রাতে শিশুকে শান্ত করার দায়িত্ব নিলে মা অনেকটা স্বস্তি পান।\n\n## সাধারণ দুশ্চিন্তা\n- **“আমার দুধ আর যথেষ্ট না।”** দুধ তৈরি হয় চাহিদা অনুযায়ী। শিশু যত বেশি টানবে, তত বেশি দুধ আসবে। কার্ডে ওজন বাড়ছে কিনা, সেটাই সবচেয়ে ভালো প্রমাণ।\n- **“শুধু বুকের দুধই খেতে চায়।”** এ নিয়ে আমাদের আলাদা নির্দেশনা দেখুন; এটা খুব সাধারণ এবং ধৈর্য ধরলে সাধারণত ঠিক হয়ে যায়।\n- **“বুকের দুধে শিশু আহ্লাদি হয়ে যাবে।”** এর কোনো প্রমাণ নেই। এ বয়সে কাছে থাকা শিশুকে নিরাপত্তা দেয়, দুর্বল করে না।\n\n## বাবার ভূমিকা\nবাবা বুকের দুধ খাওয়ানোকে আগলে রাখতে পারেন: মা যখন খাওয়াচ্ছেন, পানি ও খাবার এনে দিন; কোনো আত্মীয় মায়ের দুধ নিয়ে সন্দেহ করলে পাশে দাঁড়ান; ঢেকুর তোলানো, গোসল করানো ও খেলার দায়িত্ব নিন, যাতে মা বিশ্রাম পান।"}'::jsonb, '{"seek_help":{"en":["Painful, red, hot area in the breast with fever","Your child''s weight is not increasing","You feel low, exhausted or unable to cope"],"bn":["স্তনে ব্যথা, লাল ও গরম জায়গা, সাথে জ্বর","শিশুর ওজন বাড়ছে না","মন খারাপ, অতিরিক্ত ক্লান্তি বা আর পারছেন না মনে হচ্ছে"]}}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['breastfeeding', 'two years', 'working mother', 'expressing milk', 'toddler breastfeeding']::text[], false, 'in_review'::lp_review_status, 4005),
  ('in-food-hygiene-choking', 'article', 'scientific', 'shared', 'important', 'guideline', '🧼', '{"en":"Clean food and choking prevention","bn":"পরিষ্কার খাবার ও গলায় আটকানো প্রতিরোধ"}'::jsonb, '{"en":"Most diarrhoea in young children starts with dirty hands, pots and old food. Most choking starts with the wrong size of food. Both are preventable.","bn":"ছোট শিশুর বেশিরভাগ ডায়রিয়া শুরু হয় নোংরা হাত, পাত্র ও বাসি খাবার থেকে। বেশিরভাগ গলায় আটকানো ঘটে ভুল আকারের খাবারে। দুটোই প্রতিরোধ করা যায়।"}'::jsonb, '{"en":"## Clean hands, clean food\nOnce a baby starts eating, germs from hands, pots and water can cause diarrhoea. WHO advises good hygiene and safe food handling for every meal.\n\n- Wash your hands with soap and water before cooking, before feeding, and after toilet or changing nappies\n- Wash your child''s hands before they eat\n- Use a clean bowl, cup and spoon; wash them with soap and dry in the sun or on a rack\n- Use safe water: boiled, filtered or from a safe tubewell\n- Cook egg, fish and meat until fully done\n- Serve food soon after cooking. Throw away cooked food left out for more than about 2 hours, and do not feed leftovers from the child''s plate later\n- Cover food from flies and dust\n- Use a cup, not a feeding bottle; bottles are hard to clean and spread germs\n\n## Why young children choke\nChildren under 2 have small airways and are still learning to chew. They choke most on foods that are round, hard, slippery or sticky.\n\nHigher-risk foods:\n- Whole litchi, longan, grapes, boroi and other round fruits with seeds\n- Whole nuts, peanuts and chanachur\n- Fish with bones; chicken with small bones\n- Hard raw carrot or apple pieces\n- Popcorn, hard sweets and chewing gum\n\n## Make food safer\n- Remove all seeds and bones; check fish twice with your fingers\n- Cut round foods into small, thin pieces; give nuts only ground or as paste\n- Cook hard vegetables until soft; grate raw fruit\n- Always sit your child upright to eat, and stay with them\n- No eating while walking, running, laughing hard or lying down\n\n## Gagging or choking?\nGagging is noisy: the child coughs, splutters and goes red, then brings the food forward. It is a normal safety reflex; stay calm and let them cough.\n\nChoking is silent or nearly silent: the child cannot cry, cough or breathe, and may turn blue. This is an emergency.\n\n## If a child is choking\nShout for help and call 999. For a baby under 1 year: lay them face down along your forearm with the head lower, and give up to 5 firm back blows between the shoulder blades. If that does not work, turn them face up and give up to 5 chest thrusts with two fingers in the middle of the chest. For a child over 1 year, give back blows, then abdominal thrusts. Repeat until the object comes out or help arrives. Do not sweep blindly inside the mouth. Learning infant first aid in a short course is one of the best things parents and grandparents can do.","bn":"## পরিষ্কার হাত, পরিষ্কার খাবার\nশিশু খাবার খেতে শুরু করলে হাত, পাত্র ও পানির জীবাণু থেকে ডায়রিয়া হতে পারে। বিশ্ব স্বাস্থ্য সংস্থা প্রতিটি খাবারে পরিচ্ছন্নতা ও নিরাপদ খাবার ব্যবস্থাপনার কথা বলে।\n\n- রান্নার আগে, খাওয়ানোর আগে, আর টয়লেটের পরে বা ন্যাপি বদলানোর পরে সাবান-পানিতে হাত ধুয়ে নিন\n- খাওয়ার আগে শিশুর হাতও ধুয়ে দিন\n- পরিষ্কার বাটি, কাপ ও চামচ ব্যবহার করুন; সাবান দিয়ে ধুয়ে রোদে বা র‍্যাকে শুকান\n- নিরাপদ পানি দিন: ফোটানো, ফিল্টার করা বা নিরাপদ নলকূপের\n- ডিম, মাছ ও মাংস পুরোপুরি সেদ্ধ করুন\n- রান্নার পর তাড়াতাড়ি খাওয়ান। প্রায় ২ ঘণ্টার বেশি বাইরে পড়ে থাকা রান্না খাবার ফেলে দিন, আর শিশুর প্লেটের এঁটো পরে আবার খাওয়াবেন না\n- মাছি ও ধুলা থেকে খাবার ঢেকে রাখুন\n- ফিডার নয়, কাপ ব্যবহার করুন; ফিডার পরিষ্কার করা কঠিন, জীবাণু ছড়ায়\n\n## ছোট শিশুর গলায় কেন আটকায়\n২ বছরের কম শিশুর শ্বাসনালি সরু, চিবানোও এখনো শিখছে। গোল, শক্ত, পিচ্ছিল বা আঠালো খাবারে বেশি আটকায়।\n\nবেশি ঝুঁকির খাবার:\n- আস্ত লিচু, কাঠলিচু (আঁশফল), আঙুর, বরই ও বিচিওয়ালা গোল ফল\n- আস্ত বাদাম, চিনাবাদাম ও চানাচুর\n- কাঁটাওয়ালা মাছ; ছোট হাড়ওয়ালা মুরগি\n- কাঁচা গাজর বা আপেলের শক্ত টুকরো\n- পপকর্ন, শক্ত চকলেট-লজেন্স ও চুইংগাম\n\n## খাবার নিরাপদ করুন\n- সব বিচি ও কাঁটা ফেলে দিন; মাছ আঙুল দিয়ে দুইবার দেখে নিন\n- গোল খাবার ছোট ও পাতলা করে কাটুন; বাদাম দিলে গুঁড়া বা পেস্ট করে\n- শক্ত সবজি নরম করে সেদ্ধ করুন; কাঁচা ফল কুরিয়ে দিন\n- সবসময় সোজা করে বসিয়ে খাওয়ান, আর পাশে থাকুন\n- হাঁটতে-দৌড়াতে, জোরে হাসতে হাসতে বা শুয়ে শুয়ে খাওয়া নয়\n\n## ওয়াক ওঠা, নাকি গলায় আটকানো?\nওয়াক উঠলে শব্দ হয়: শিশু কাশে, খকখক করে, মুখ লাল হয়, তারপর খাবার সামনে নিয়ে আসে। এটা স্বাভাবিক সুরক্ষার প্রতিক্রিয়া; শান্ত থাকুন, কাশতে দিন।\n\nগলায় আটকালে প্রায় কোনো শব্দ হয় না: শিশু কাঁদতে, কাশতে বা শ্বাস নিতে পারে না, নীল হয়ে যেতে পারে। এটা জরুরি অবস্থা।\n\n## গলায় খাবার আটকালে\nচিৎকার করে কাউকে ডাকুন, ৯৯৯-এ ফোন করুন। ১ বছরের কম শিশু হলে: আপনার বাহুর ওপর উপুড় করে শোয়ান, মাথা একটু নিচে রাখুন, দুই কাঁধের মাঝখানে হাতের তালু দিয়ে জোরে ৫ বার পর্যন্ত চাপড় দিন। কাজ না হলে চিত করে বুকের মাঝখানে দুই আঙুলে ৫ বার পর্যন্ত চাপ দিন। ১ বছরের বেশি হলে পিঠে চাপড়ের পর পেটে চাপ দিন। জিনিসটা বের না হওয়া বা সাহায্য না আসা পর্যন্ত চালিয়ে যান। না দেখে মুখের ভেতরে আঙুল ঢুকিয়ে খুঁজবেন না। মা-বাবা ও দাদা-দাদিরা একটি ছোট প্রাথমিক চিকিৎসা প্রশিক্ষণ নিয়ে রাখলে খুব কাজে দেয়।"}'::jsonb, '{"seek_help":{"en":["Your child choked and is now coughing, wheezing or breathing noisily","Diarrhoea with blood, or a child who will not drink","Vomiting or high fever after eating food that may have been spoiled"],"bn":["গলায় আটকানোর পর এখন কাশছে, শাঁ শাঁ শব্দ বা শব্দ করে শ্বাস নিচ্ছে","রক্তসহ ডায়রিয়া, বা শিশু কিছুই পান করছে না","নষ্ট হতে পারে এমন খাবার খাওয়ার পর বমি বা বেশি জ্বর"]}}'::jsonb, 5, 183, 730, '{}'::text[], 'any', ARRAY['food hygiene', 'choking', 'handwashing', 'food storage', 'first aid', 'litchi', 'fish bones']::text[], false, 'in_review'::lp_review_status, 4006),
  ('in-recipe-soft-khichuri', 'activity', 'scientific', 'shared', 'routine', 'consensus', '🍲', '{"en":"Recipe: soft khichuri with lentils and vegetables","bn":"রেসিপি: ডাল-সবজির নরম খিচুড়ি"}'::jsonb, '{"en":"A thick, filling first food from your own kitchen: rice, red lentils, a vegetable and a little oil, mashed to suit your baby''s age.","bn":"নিজের রান্নাঘর থেকেই ঘন, পেট ভরানো প্রথম খাবার: চাল, মসুর ডাল, একটি সবজি আর একটু তেল, শিশুর বয়স মতো চটকে দিন।"}'::jsonb, '{"en":"## Texture by age\n- **6–8 months:** cook very soft and mash well, or press through a sieve. Thick enough to stay on the spoon.\n- **9–11 months:** mash lightly so small soft lumps remain. Add finely chopped egg, fish or chicken.\n- **12–23 months:** the family khichuri is fine if it is soft and mildly spiced. Take out your child''s portion before adding chilli and extra salt.","bn":"## বয়স অনুযায়ী ঘনত্ব\n- **৬–৮ মাস:** খুব নরম করে রেঁধে ভালোভাবে চটকান, বা ছাঁকনিতে চেপে নিন। এত ঘন যেন চামচে আটকে থাকে।\n- **৯–১১ মাস:** হালকা চটকান, ছোট ছোট নরম দানা থাকুক। মিহি করে কাটা ডিম, মাছ বা মুরগি মেশান।\n- **১২–২৩ মাস:** পরিবারের খিচুড়িই চলবে, যদি নরম আর কম মশলার হয়। মরিচ ও বাড়তি লবণ দেওয়ার আগে শিশুর অংশ তুলে রাখুন।"}'::jsonb, '{"why":{"en":"Rice gives energy, lentils add protein and iron, vegetables add vitamins, and oil adds the extra energy a small stomach needs. It is cheap, familiar and easy to change from day to day.","bn":"চাল শক্তি দেয়, ডাল দেয় আমিষ ও আয়রন, সবজি দেয় ভিটামিন, আর তেল ছোট পেটের বাড়তি শক্তির চাহিদা মেটায়। খরচ কম, সবার চেনা, আর প্রতিদিন একটু বদলে নেওয়া সহজ।"},"items":{"en":["2 tablespoons rice","1 tablespoon red lentils (masoor dal)","A handful of one vegetable: pumpkin, carrot, potato, papaya or leafy greens such as lal shak or palong shak","1 teaspoon soybean or mustard oil","A pinch of turmeric; a little onion if you like","About 1½ cups of safe water","Optional: half an egg, a little boneless fish, chicken or liver"],"bn":["২ টেবিল-চামচ চাল","১ টেবিল-চামচ মসুর ডাল","এক মুঠো যেকোনো একটি সবজি: মিষ্টিকুমড়া, গাজর, আলু, পেঁপে, অথবা লাল শাক বা পালং শাক","১ চা-চামচ সয়াবিন বা সরিষার তেল","এক চিমটি হলুদ; চাইলে সামান্য পেঁয়াজ","প্রায় দেড় কাপ নিরাপদ পানি","চাইলে: আধা ডিম, কাঁটা ছাড়া একটু মাছ, মুরগি বা কলিজা"]},"steps":{"en":["Wash your hands, the pot and the rice and lentils","Put rice, lentils, chopped vegetable, turmeric and water in a pot","Cook on low heat, stirring now and then, until everything is very soft (about 25–30 minutes); add water if it dries","If adding egg, fish, chicken or liver, cook it in the pot until fully done","Stir in the oil at the end","Mash to the right texture for your child''s age and let it cool to warm","Check that it is only warm, then feed slowly, talking to your baby","Throw away what is left in the bowl; keep the rest covered and use it within about 2 hours"],"bn":["হাত, হাঁড়ি আর চাল-ডাল ভালো করে ধুয়ে নিন","হাঁড়িতে চাল, ডাল, কাটা সবজি, হলুদ ও পানি দিন","অল্প আঁচে মাঝে মাঝে নেড়ে সব খুব নরম না হওয়া পর্যন্ত রাঁধুন (প্রায় ২৫–৩০ মিনিট); শুকিয়ে গেলে পানি দিন","ডিম, মাছ, মুরগি বা কলিজা দিলে হাঁড়িতেই পুরোপুরি সেদ্ধ করুন","শেষে তেল মিশিয়ে দিন","শিশুর বয়স মতো চটকে কুসুম গরম হওয়া পর্যন্ত ঠান্ডা করুন","শুধু কুসুম গরম আছে কিনা দেখে নিয়ে শিশুর সাথে কথা বলতে বলতে ধীরে খাওয়ান","বাটিতে বেঁচে যাওয়া খাবার ফেলে দিন; বাকিটা ঢেকে রেখে প্রায় ২ ঘণ্টার মধ্যে খাওয়ান"]},"avoid":{"en":["Added salt before 1 year, and spicy chilli","Making it watery to finish faster","Keeping cooked khichuri at room temperature until the next meal"],"bn":["১ বছরের আগে বাড়তি লবণ, আর ঝাল মরিচ","তাড়াতাড়ি খাওয়ানোর জন্য পাতলা করে ফেলা","রান্না খিচুড়ি ঘরের তাপমাত্রায় পরের বেলা পর্যন্ত রেখে দেওয়া"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['recipe', 'khichuri', 'lentil', 'vegetables', 'first foods', 'porridge']::text[], false, 'in_review'::lp_review_status, 4007),
  ('in-recipe-mashed-fish', 'activity', 'scientific', 'shared', 'routine', 'consensus', '🐟', '{"en":"Recipe: mashed fish with rice or potato","bn":"রেসিপি: ভাত বা আলুর সাথে মাছ চটকানো"}'::jsonb, '{"en":"Fish is one of Bangladesh''s best baby foods. Cook it well, remove every bone, and mash it with rice or potato.","bn":"মাছ আমাদের দেশের সবচেয়ে ভালো শিশুখাদ্যগুলোর একটি। ভালো করে রাঁধুন, প্রতিটি কাঁটা বেছে ফেলুন, তারপর ভাত বা আলুর সাথে চটকে দিন।"}'::jsonb, '{"en":"## Texture by age\n- **6–8 months:** fish mashed very smooth into soft rice or potato.\n- **9–11 months:** small soft flakes mixed into rice or khichuri.\n- **12–23 months:** soft pieces of the family fish curry, boneless and with little chilli.\n\n## About small fish\nSmall fish such as mola are rich in vitamin A and calcium. If you use them, cook well and grind into a very fine paste so no hard bone remains. If you are not sure, choose a larger fish where you can remove the bones by hand.","bn":"## বয়স অনুযায়ী ঘনত্ব\n- **৬–৮ মাস:** নরম ভাত বা আলুর সাথে মাছ খুব মিহি করে চটকানো।\n- **৯–১১ মাস:** ভাত বা খিচুড়ির সাথে ছোট ছোট নরম টুকরো।\n- **১২–২৩ মাস:** পরিবারের মাছের তরকারির নরম টুকরো, কাঁটা ছাড়া ও কম ঝালে।\n\n## ছোট মাছ নিয়ে\nমলার মতো ছোট মাছে প্রচুর ভিটামিন এ ও ক্যালসিয়াম থাকে। দিলে ভালো করে রেঁধে খুব মিহি করে বেটে নিন, যেন কোনো শক্ত কাঁটা না থাকে। নিশ্চিত না হলে বড় মাছ নিন, যার কাঁটা হাতে বেছে ফেলা যায়।"}'::jsonb, '{"why":{"en":"Fish gives high-quality protein, iron, zinc and healthy fats for the growing brain. WHO advises an animal food such as fish, meat or egg every day for children from 6 months.","bn":"মাছ বাড়ন্ত মস্তিষ্কের জন্য ভালো মানের আমিষ, আয়রন, জিংক ও উপকারী চর্বি দেয়। বিশ্ব স্বাস্থ্য সংস্থা ৬ মাস থেকে প্রতিদিন মাছ, মাংস বা ডিমের মতো একটি প্রাণিজ খাবার দিতে বলে।"},"items":{"en":["A small piece of fresh fish: rui, katla, tilapia, pangas or another local fish","2–3 tablespoons soft cooked rice, or one small boiled potato","A few drops of oil","A pinch of turmeric","A clean plate and spoon"],"bn":["এক টুকরো তাজা মাছ: রুই, কাতলা, তেলাপিয়া, পাঙাশ বা অন্য দেশি মাছ","২–৩ টেবিল-চামচ নরম ভাত, বা একটি ছোট সেদ্ধ আলু","কয়েক ফোঁটা তেল","এক চিমটি হলুদ","পরিষ্কার প্লেট ও চামচ"]},"steps":{"en":["Wash hands and the fish well","Steam or boil the fish with turmeric until it is white and flakes easily, with no pink inside","Let it cool a little, then break it open on a plate","Remove every bone; run your fingers through the flesh a second time","Mash the fish with rice or potato and a few drops of oil","Add a little cooking water or breast milk if it is too dry, keeping it thick","Feed slowly and watch your child while they eat"],"bn":["হাত ও মাছ ভালো করে ধুয়ে নিন","হলুদ দিয়ে মাছ ভাপে বা পানিতে সেদ্ধ করুন, যতক্ষণ না সাদা হয়ে সহজে ভেঙে যায় এবং ভেতরে গোলাপি না থাকে","একটু ঠান্ডা হলে প্লেটে ভেঙে নিন","প্রতিটি কাঁটা বেছে ফেলুন; আরেকবার আঙুল চালিয়ে দেখে নিন","ভাত বা আলু আর কয়েক ফোঁটা তেলের সাথে চটকান","খুব শুকনো হলে একটু সেদ্ধ-পানি বা বুকের দুধ মেশান, তবে ঘন রাখুন","ধীরে খাওয়ান, খাওয়ার সময় চোখ রাখুন"]},"avoid":{"en":["Any bone left in the mash","Dried or salted fish (shutki) for babies under 1 year, because of the high salt","Fish that smells off or has been kept warm for hours"],"bn":["চটকানো মাছে কোনো কাঁটা থেকে যাওয়া","১ বছরের কম শিশুকে শুঁটকি, কারণ এতে লবণ খুব বেশি","গন্ধ হয়ে যাওয়া বা ঘণ্টার পর ঘণ্টা গরম রাখা মাছ"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['recipe', 'fish', 'mola', 'rui', 'protein', 'iron', 'first foods']::text[], false, 'in_review'::lp_review_status, 4008),
  ('in-recipe-egg', 'activity', 'scientific', 'shared', 'routine', 'consensus', '🍳', '{"en":"Recipe: egg three ways","bn":"রেসিপি: তিনভাবে ডিম"}'::jsonb, '{"en":"Mashed boiled egg, egg stirred into khichuri, and soft omelette strips for little fingers. Always fully cooked.","bn":"সেদ্ধ ডিম চটকানো, খিচুড়িতে ডিম মেশানো, আর ছোট্ট আঙুলের জন্য নরম ডিমভাজির টুকরো। সবসময় পুরোপুরি সেদ্ধ।"}'::jsonb, '{"en":"## Texture by age\n- **6–8 months:** hard-boiled egg mashed smooth with a little breast milk or water, or stirred into khichuri.\n- **9–11 months:** chopped boiled egg or thin strips of soft omelette your baby can pick up.\n- **12–23 months:** egg as the family eats it, with less salt and chilli.\n\n## The first few times\nGive egg at home on a day you can watch your child. A few spots around the mouth can be from rubbing. If your child gets hives, vomits, or the lips or face swell after egg, stop and see a doctor. Swelling with breathing trouble is an emergency.","bn":"## বয়স অনুযায়ী ঘনত্ব\n- **৬–৮ মাস:** শক্ত করে সেদ্ধ ডিম একটু বুকের দুধ বা পানি দিয়ে মিহি করে চটকানো, বা খিচুড়িতে মেশানো।\n- **৯–১১ মাস:** কুচি করা সেদ্ধ ডিম, বা নরম ডিমভাজির সরু টুকরো, যা শিশু নিজে তুলে খেতে পারে।\n- **১২–২৩ মাস:** পরিবারের মতো ডিম, তবে লবণ ও ঝাল কম।\n\n## প্রথম কয়েকবার\nযেদিন বাড়িতে থেকে শিশুকে খেয়াল রাখতে পারবেন, সেদিন ডিম দিন। মুখের চারপাশে দু-একটা লাল দাগ ঘষা লেগেও হতে পারে। কিন্তু ডিম খাওয়ার পর চাকা চাকা র‍্যাশ, বমি, বা ঠোঁট-মুখ ফুলে গেলে ডিম বন্ধ করে ডাক্তার দেখান। ফোলার সাথে শ্বাসকষ্ট হলে সেটা জরুরি অবস্থা।"}'::jsonb, '{"why":{"en":"Egg is one of the most nourishing, affordable foods for a young child: protein, healthy fat, vitamins and some iron, ready in ten minutes. One egg a day is an easy habit to keep.","bn":"ছোট শিশুর জন্য ডিম সবচেয়ে পুষ্টিকর ও সাশ্রয়ী খাবারগুলোর একটি: আমিষ, উপকারী চর্বি, ভিটামিন ও কিছু আয়রন, দশ মিনিটেই তৈরি। দিনে একটি ডিম সহজেই ধরে রাখা যায় এমন অভ্যাস।"},"items":{"en":["1 fresh egg (hen or duck)","A small pot of water","A few drops of oil for the omelette","A little breast milk, water or khichuri to mix","A clean bowl and spoon"],"bn":["১টি তাজা ডিম (মুরগি বা হাঁসের)","ছোট একটি হাঁড়িতে পানি","ডিমভাজির জন্য কয়েক ফোঁটা তেল","মেশানোর জন্য একটু বুকের দুধ, পানি বা খিচুড়ি","পরিষ্কার বাটি ও চামচ"]},"steps":{"en":["Wash the egg shell and your hands before cracking or boiling","Boiled: cook the egg in boiling water for about 10 minutes until the yolk is firm, cool, peel and mash with a little breast milk or water","In khichuri: break the egg into the pot near the end and stir until it is completely set","Omelette: beat the egg, cook on low heat in a few drops of oil until firm on both sides, cool and cut into finger-length strips","Start with a small amount and build up to a whole egg","Stay with your child while they eat"],"bn":["ভাঙা বা সেদ্ধ করার আগে ডিমের খোসা ও হাত ধুয়ে নিন","সেদ্ধ: ফুটন্ত পানিতে প্রায় ১০ মিনিট রাখুন যতক্ষণ না কুসুম শক্ত হয়; ঠান্ডা করে খোসা ছাড়িয়ে একটু বুকের দুধ বা পানি দিয়ে চটকান","খিচুড়িতে: রান্নার শেষ দিকে হাঁড়িতে ডিম ভেঙে দিয়ে পুরোপুরি জমে না যাওয়া পর্যন্ত নাড়ুন","ডিমভাজি: ডিম ফেটিয়ে কয়েক ফোঁটা তেলে অল্প আঁচে দুই পিঠ শক্ত হওয়া পর্যন্ত ভাজুন, ঠান্ডা করে আঙুলের মতো লম্বা টুকরো করুন","অল্প দিয়ে শুরু করে ধীরে ধীরে পুরো একটি ডিম পর্যন্ত যান","খাওয়ার সময় শিশুর পাশে থাকুন"]},"avoid":{"en":["Runny yolk or half-boiled egg","Cracked or dirty eggs","Adding salt for babies under 1 year"],"bn":["তরল কুসুম বা আধা সেদ্ধ ডিম","ফাটা বা নোংরা ডিম","১ বছরের কম শিশুর ডিমে লবণ দেওয়া"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['recipe', 'egg', 'boiled egg', 'omelette', 'finger food', 'protein']::text[], false, 'in_review'::lp_review_status, 4009),
  ('in-recipe-fruit-mash', 'activity', 'scientific', 'shared', 'routine', 'consensus', '🥭', '{"en":"Recipe: seasonal fruit mash","bn":"রেসিপি: মৌসুমি ফলের ভর্তা"}'::jsonb, '{"en":"Ripe banana, papaya, mango or sapodilla, scraped or mashed with a spoon. No sugar, no honey, no juice.","bn":"পাকা কলা, পেঁপে, আম বা সফেদা, চামচে কুরিয়ে বা চটকে। চিনি নয়, মধু নয়, জুস নয়।"}'::jsonb, '{"en":"## Texture by age\n- **6–8 months:** scraped or mashed smooth with a spoon.\n- **9–11 months:** mashed with soft lumps, or soft finger-length pieces of banana or papaya to hold.\n- **12–23 months:** small soft pieces of most seasonal fruits, seeds removed.\n\n## Fruits by season\nBanana and papaya are available most of the year. In summer, ripe mango and jackfruit flesh (seed removed, cut small) are good. In winter, try orange segments with the skin and seeds removed, or stewed apple. Litchi, longan and boroi should only be given peeled, seeded and cut into small pieces.","bn":"## বয়স অনুযায়ী ঘনত্ব\n- **৬–৮ মাস:** চামচে কুরিয়ে বা মিহি করে চটকানো।\n- **৯–১১ মাস:** ছোট নরম দানাসহ চটকানো, বা কলা-পেঁপের আঙুলের মতো নরম টুকরো হাতে ধরার জন্য।\n- **১২–২৩ মাস:** বেশিরভাগ মৌসুমি ফলের ছোট নরম টুকরো, বিচি ছাড়িয়ে।\n\n## মৌসুম অনুযায়ী ফল\nকলা ও পেঁপে প্রায় সারা বছর পাওয়া যায়। গরমে পাকা আম আর কাঁঠালের কোষ (বিচি ফেলে ছোট করে কেটে) ভালো। শীতে খোসা ও বিচি ছাড়ানো কমলার কোয়া বা সেদ্ধ আপেল দিতে পারেন। লিচু, আঁশফল ও বরই শুধু খোসা-বিচি ছাড়িয়ে ছোট টুকরো করে দেবেন।"}'::jsonb, '{"why":{"en":"Fruits give vitamins, especially vitamin A from yellow and orange fruits and vitamin C, which helps the body take up iron from other foods in the same meal. Whole fruit is better than juice, which has fibre removed and is easy to overdrink.","bn":"ফল ভিটামিন দেয়, বিশেষ করে হলুদ-কমলা ফল থেকে ভিটামিন এ, আর ভিটামিন সি, যা একই বেলার অন্য খাবার থেকে আয়রন শোষণে সাহায্য করে। জুসের চেয়ে আস্ত ফল ভালো; জুসে আঁশ থাকে না, আর বেশি খেয়ে ফেলা সহজ।"},"items":{"en":["One ripe seasonal fruit: banana, papaya, mango or sapodilla","A clean knife, spoon and bowl","Safe water to wash the fruit"],"bn":["একটি পাকা মৌসুমি ফল: কলা, পেঁপে, আম বা সফেদা","পরিষ্কার ছুরি, চামচ ও বাটি","ফল ধোয়ার জন্য নিরাপদ পানি"]},"steps":{"en":["Wash your hands and the fruit with safe water","Peel the fruit and remove all seeds","Scrape or mash with a spoon to suit your child''s age","Serve straight away; cut fruit spoils quickly","Offer it as a snack between meals or after a meal","Let older babies hold a soft piece while you watch"],"bn":["হাত ও ফল নিরাপদ পানিতে ধুয়ে নিন","খোসা ছাড়িয়ে সব বিচি ফেলে দিন","শিশুর বয়স মতো চামচে কুরিয়ে বা চটকে নিন","সাথে সাথে খাওয়ান; কাটা ফল তাড়াতাড়ি নষ্ট হয়","দুই বেলার মাঝে নাশতা হিসেবে বা খাওয়ার পরে দিন","একটু বড় শিশুকে নরম টুকরো হাতে ধরতে দিন, আপনি পাশে থাকুন"]},"avoid":{"en":["Sugar, honey (before 1 year) or condensed milk on fruit","Packaged juice or fruit drinks","Whole round fruits with seeds such as litchi or boroi"],"bn":["ফলে চিনি, মধু (১ বছরের আগে) বা কনডেন্সড মিল্ক","প্যাকেটের জুস বা ফলের পানীয়","লিচু বা বরইয়ের মতো বিচিসহ আস্ত গোল ফল"]}}'::jsonb, 2, 183, 730, '{}'::text[], 'any', ARRAY['recipe', 'fruit', 'banana', 'papaya', 'mango', 'snack', 'finger food']::text[], false, 'in_review'::lp_review_status, 4010),
  ('in-teething-first-teeth', 'article', 'scientific', 'shared', 'routine', 'guideline', '🦷', '{"en":"Teething and caring for first teeth","bn":"দাঁত ওঠা ও প্রথম দাঁতের যত্ন"}'::jsonb, '{"en":"First teeth usually come around 6 months, but timing varies a lot. Soothe sore gums simply, and brush from the very first tooth.","bn":"প্রথম দাঁত সাধারণত ৬ মাসের দিকে ওঠে, তবে সময় শিশুভেদে অনেক আলাদা। মাড়ির ব্যথা সহজ উপায়ে কমান, আর প্রথম দাঁত থেকেই ব্রাশ শুরু করুন।"}'::jsonb, '{"en":"## When teeth come\nMany babies get their first tooth around 6 months, usually a lower front tooth. Some start earlier, and some have no teeth until after their first birthday. Both are usually normal. Most children have all 20 baby teeth by about 2½ to 3 years.\n\n## Signs of teething\n- More drool and wet chin\n- Chewing on hands and toys\n- Red or swollen gums\n- Fussy, clingy, or waking more at night for a few days\n\nTeething does not cause high fever, diarrhoea or a chest infection. If your child has these, look for another cause and get them checked. Blaming teeth can delay care for a real illness.\n\n## Simple ways to soothe\n- Rub the gum gently with your clean finger\n- Offer a clean, cool (not frozen) teething ring or a cold, wet, clean cloth to chew\n- Older babies can chew on a cool piece of soft fruit while you watch\n- Extra cuddles and patience\n\nIf your child is in a lot of pain, ask a health worker before giving any medicine.\n\n## Cleaning from the first tooth\nTooth decay can start as soon as a tooth appears. WHO and dental bodies advise cleaning teeth twice a day with fluoride toothpaste.\n- Use a small, soft children''s toothbrush\n- Use only a smear of fluoride toothpaste, about the size of a grain of rice\n- Brush all sides of each tooth, morning and before sleep\n- Do not rinse with lots of water; just wipe away the extra foam\n- Lift the lip once a month and look for white chalky lines or brown spots near the gum\n\n## Sugar and teeth\nSweet food and drinks feed the germs that cause decay. Avoid sweet biscuits, candy, soft drinks and juice, and never dip anything in sugar or honey to calm a baby. Do not put your child to sleep with a bottle of milk or sweet drink. Give water between meals.\n\n## A shared routine\nToothbrushing is a lovely job for a father or grandparent: sing a short song while you brush, and let your child hold a second brush. Soon it becomes part of the day, like washing hands.","bn":"## দাঁত ওঠার সময়\nঅনেক শিশুর প্রথম দাঁত ওঠে ৬ মাসের দিকে, সাধারণত নিচের সামনের দাঁত। কারো আগে ওঠে, আবার কারো প্রথম জন্মদিনের পরে। দুটোই সাধারণত স্বাভাবিক। প্রায় আড়াই থেকে ৩ বছরের মধ্যে বেশিরভাগ শিশুর ২০টি দুধদাঁত উঠে যায়।\n\n## দাঁত ওঠার লক্ষণ\n- বেশি লালা ঝরা, থুতনি ভেজা থাকা\n- হাত ও খেলনা কামড়ানো\n- মাড়ি লাল বা ফোলা\n- কয়েক দিন খিটখিটে থাকা, কোলে থাকতে চাওয়া, রাতে বেশি জাগা\n\nদাঁত ওঠার কারণে বেশি জ্বর, ডায়রিয়া বা বুকে সংক্রমণ হয় না। এমন হলে অন্য কারণ খুঁজুন, শিশুকে দেখান। সব দোষ দাঁতের ঘাড়ে চাপালে আসল অসুখের চিকিৎসা দেরি হয়ে যেতে পারে।\n\n## আরাম দেওয়ার সহজ উপায়\n- পরিষ্কার আঙুল দিয়ে মাড়িতে আলতো করে ঘষে দিন\n- পরিষ্কার, ঠান্ডা (বরফ-জমা নয়) টিদার বা ভেজা পরিষ্কার কাপড় চিবাতে দিন\n- একটু বড় শিশুকে নরম ঠান্ডা ফলের টুকরো চিবাতে দিন, আপনি পাশে থাকুন\n- বেশি বেশি আদর আর ধৈর্য\n\nশিশুর খুব কষ্ট হলে কোনো ওষুধ দেওয়ার আগে স্বাস্থ্যকর্মীর পরামর্শ নিন।\n\n## প্রথম দাঁত থেকেই পরিষ্কার\nদাঁত দেখা দেওয়ার সাথে সাথেই ক্ষয় শুরু হতে পারে। বিশ্ব স্বাস্থ্য সংস্থা ও দন্তবিশেষজ্ঞরা দিনে দুইবার ফ্লোরাইড টুথপেস্ট দিয়ে দাঁত পরিষ্কারের কথা বলেন।\n- শিশুদের ছোট, নরম টুথব্রাশ ব্যবহার করুন\n- ফ্লোরাইড টুথপেস্ট দিন একটি চালের দানার সমান, শুধু একটু ছোঁয়া\n- সকালে ও ঘুমের আগে প্রতিটি দাঁতের সব দিক ব্রাশ করুন\n- বেশি পানি দিয়ে কুলি করাবেন না; বাড়তি ফেনা মুছে দিলেই হবে\n- মাসে একবার ঠোঁট তুলে দেখুন, মাড়ির কাছে সাদা চকের মতো দাগ বা বাদামি দাগ আছে কিনা\n\n## চিনি ও দাঁত\nমিষ্টি খাবার ও পানীয় দাঁতের ক্ষয়ের জীবাণুকে খাওয়ায়। মিষ্টি বিস্কুট, চকলেট-লজেন্স, কোমল পানীয় ও জুস এড়িয়ে চলুন, আর শিশুকে শান্ত করতে কোনো কিছু চিনি বা মধুতে ডুবিয়ে দেবেন না। দুধ বা মিষ্টি পানীয়ের ফিডার মুখে দিয়ে ঘুম পাড়াবেন না। দুই বেলার মাঝে পানি দিন।\n\n## সবাই মিলে অভ্যাস\nদাঁত ব্রাশ করানো বাবা বা দাদা-দাদির জন্য দারুণ একটি কাজ: ব্রাশ করতে করতে ছোট একটা গান গান, আর শিশুর হাতে আরেকটা ব্রাশ ধরতে দিন। শিগগিরই এটা হাত ধোয়ার মতোই দিনের অংশ হয়ে যাবে।"}'::jsonb, '{"avoid":{"en":["Numbing gels or teething medicines unless a health worker advises them","Teething necklaces, beads or cords around the neck, which can choke or strangle","Rubbing alcohol, honey or sugar on the gums"],"bn":["স্বাস্থ্যকর্মী না বললে মাড়ি অবশ করার জেল বা দাঁত ওঠার ওষুধ","দাঁত ওঠার মালা, পুঁতি বা গলায় সুতা, যা গলায় আটকাতে বা ফাঁস লাগাতে পারে","মাড়িতে অ্যালকোহল, মধু বা চিনি ঘষা"]},"seek_help":{"en":["Fever of 38°C or more, diarrhoea or cough: these are not from teething","No teeth at all by about 18 months","White or brown spots, holes or a swollen gum with pus"],"bn":["৩৮°সে বা তার বেশি জ্বর, ডায়রিয়া বা কাশি: এগুলো দাঁত ওঠার কারণে নয়","প্রায় ১৮ মাসেও একটিও দাঁত ওঠেনি","দাঁতে সাদা বা বাদামি দাগ, গর্ত, বা পুঁজসহ ফোলা মাড়ি"]}}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['teething', 'first tooth', 'toothbrush', 'fluoride toothpaste', 'tooth decay', 'sugar']::text[], false, 'in_review'::lp_review_status, 4011),
  ('in-sleep-6-24-months', 'article', 'scientific', 'shared', 'routine', 'guideline', '🌙', '{"en":"Sleep from 6 to 24 months","bn":"৬ থেকে ২৪ মাসের ঘুম"}'::jsonb, '{"en":"How much sleep young children need, a simple bedtime routine, and how to keep sleep safe in a Bangladeshi home.","bn":"ছোট শিশুর কতটুকু ঘুম দরকার, সহজ একটি ঘুমের রুটিন, আর আমাদের ঘরে ঘুম নিরাপদ রাখার উপায়।"}'::jsonb, '{"en":"## How much sleep\nWHO advises, including naps:\n- **Under 1 year (from 4 months):** about 12–16 hours in 24 hours\n- **1–2 years:** about 11–14 hours in 24 hours\n\nAt 6–12 months most babies take 2–3 naps. Between about 12 and 18 months many move to one longer afternoon nap. Every child is different; a child who is mostly cheerful and growing well is usually getting enough.\n\n## Why routine helps\nThe body clock likes regular times. Try to keep wake-up, naps and bedtime at roughly the same time each day, even on holidays and during guests'' visits.\n\nA short bedtime routine of 20–30 minutes tells your child that sleep is coming:\n1. Wash face, hands and feet, or a quick bath\n2. Clean nappy and night clothes\n3. Feed, then brush teeth\n4. A song, a dua or a short book with lights low\n5. Into bed sleepy but awake, with the same goodnight words each night\n\n## Night waking is common\nMany children still wake at night in the second year. Teething, illness, a new skill like standing, and fear of separation around 8–18 months all disturb sleep. Keep night care calm and boring: low light, few words, settle back. If you breastfeed at night, that is fine; brush teeth before the last sleep.\n\n## Safe sleep\n- Until 1 year, put your baby down on the back for every sleep\n- Use a firm, flat surface; no pillows, soft toys or heavy quilts near the face\n- Many families share a bed. If you do, keep the baby away from the edge and the wall gap, away from pillows, and never sleep with the baby if you smoke, have taken sleep medicine or are extremely tired\n- Never sleep with a baby on a sofa or chair\n- Use a mosquito net, tucked in firmly and not loose near the baby''s face\n- Keep the room smoke-free and not too hot; light cotton clothing is enough in summer\n\n## Screens and sleep\nTV and phones before bed make it harder to fall asleep. Switch them off at least an hour before bedtime.\n\n## Share the nights\nNights are long for both parents. Take turns: one parent settles the early waking, the other the late one, or the father takes the weekend mornings so the mother can rest.","bn":"## কতটুকু ঘুম\nবিশ্ব স্বাস্থ্য সংস্থার পরামর্শ, দিনের ঘুমসহ:\n- **১ বছরের কম (৪ মাস থেকে):** ২৪ ঘণ্টায় মোটামুটি ১২–১৬ ঘণ্টা\n- **১–২ বছর:** ২৪ ঘণ্টায় মোটামুটি ১১–১৪ ঘণ্টা\n\n৬–১২ মাসে বেশিরভাগ শিশু দিনে ২–৩ বার ঘুমায়। ১২ থেকে ১৮ মাসের মধ্যে অনেকে দুপুরের একটি লম্বা ঘুমে চলে আসে। প্রত্যেক শিশু আলাদা; যে শিশু বেশিরভাগ সময় হাসিখুশি আর ঠিকমতো বাড়ছে, সে সাধারণত যথেষ্ট ঘুমাচ্ছে।\n\n## রুটিন কেন কাজে দেয়\nশরীরের ঘড়ি নিয়মিত সময় পছন্দ করে। ঘুম থেকে ওঠা, দিনের ঘুম আর রাতের ঘুম প্রতিদিন মোটামুটি একই সময়ে রাখার চেষ্টা করুন, ছুটির দিনে বা মেহমান এলেও।\n\n২০–৩০ মিনিটের ছোট একটি ঘুমের রুটিন শিশুকে বুঝিয়ে দেয় যে এখন ঘুমের সময়:\n১. মুখ-হাত-পা ধোয়া, বা ঝটপট গোসল\n২. পরিষ্কার ন্যাপি ও রাতের কাপড়\n৩. খাওয়ানো, তারপর দাঁত ব্রাশ\n৪. আলো কমিয়ে একটি গান, দোয়া বা ছোট বই\n৫. ঘুম ঘুম অবস্থায় কিন্তু জেগে থাকতেই বিছানায়, প্রতি রাতে একই শুভরাত্রির কথা\n\n## রাতে জাগা খুব সাধারণ\nদ্বিতীয় বছরেও অনেক শিশু রাতে জাগে। দাঁত ওঠা, অসুখ, দাঁড়ানোর মতো নতুন দক্ষতা, আর ৮–১৮ মাসের দিকে মা-বাবাকে ছেড়ে থাকার ভয়, সবই ঘুম ভাঙায়। রাতের যত্ন শান্ত ও একঘেয়ে রাখুন: কম আলো, কম কথা, আবার ঘুম পাড়ানো। রাতে বুকের দুধ দিলে সমস্যা নেই; শেষ ঘুমের আগে দাঁত ব্রাশ করিয়ে দিন।\n\n## নিরাপদ ঘুম\n- ১ বছর পর্যন্ত প্রতিবার ঘুমের সময় শিশুকে চিত করে শোয়ান\n- শক্ত, সমান বিছানা; মুখের কাছে বালিশ, নরম খেলনা বা ভারী কাঁথা নয়\n- অনেক পরিবার একসাথে এক বিছানায় ঘুমায়। তাহলে শিশুকে খাটের কিনারা, দেয়ালের ফাঁক আর বালিশ থেকে দূরে রাখুন; আপনি ধূমপান করলে, ঘুমের ওষুধ খেলে বা খুব বেশি ক্লান্ত থাকলে শিশুকে নিয়ে ঘুমাবেন না\n- সোফা বা চেয়ারে শিশুকে নিয়ে কখনো ঘুমাবেন না\n- মশারি টানান, শক্ত করে গুঁজে দিন, যেন শিশুর মুখের কাছে ঢিলে হয়ে না ঝোলে\n- ঘর ধোঁয়ামুক্ত রাখুন, বেশি গরম যেন না হয়; গরমে হালকা সুতির কাপড়ই যথেষ্ট\n\n## স্ক্রিন ও ঘুম\nঘুমের আগে টিভি ও ফোন দেখলে ঘুম আসতে দেরি হয়। ঘুমের অন্তত এক ঘণ্টা আগে বন্ধ করে দিন।\n\n## রাত ভাগ করে নিন\nরাত দুজনের জন্যই লম্বা। পালা করে নিন: রাতের প্রথম দিকের জাগা একজন সামলান, শেষ রাতেরটা অন্যজন; অথবা ছুটির দিনের সকালটা বাবা নিন, যাতে মা একটু ঘুমাতে পারেন।"}'::jsonb, '{"seek_help":{"en":["Loud snoring with pauses in breathing","Your child is very hard to wake or unusually sleepy","Sleep problems are leaving a parent exhausted or low"],"bn":["জোরে নাক ডাকা, মাঝে মাঝে শ্বাস থেমে যাওয়া","শিশুকে জাগানো খুব কঠিন বা অস্বাভাবিক ঘুমকাতুরে","ঘুমের সমস্যায় মা বা বাবা একেবারে ক্লান্ত বা মনমরা"]}}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['sleep', 'naps', 'bedtime routine', 'night waking', 'safe sleep', 'mosquito net']::text[], false, 'in_review'::lp_review_status, 4012),
  ('in-development-6-12-months', 'article', 'scientific', 'shared', 'educational', 'guideline', '🧸', '{"en":"Development from 6 to 12 months","bn":"৬ থেকে ১২ মাসের বিকাশ"}'::jsonb, '{"en":"Sitting, babbling, pulling up and the first “bye-bye”: what most babies do by 9 and 12 months, and how you can help.","bn":"বসা, আধো বুলি, ধরে দাঁড়ানো আর প্রথম “টা-টা”: ৯ ও ১২ মাসে বেশিরভাগ শিশু যা করে, আর আপনি কীভাবে সাহায্য করবেন।"}'::jsonb, '{"en":"## A year of big changes\nIn these six months your baby goes from sitting with help to standing beside furniture. The brain is growing faster than at almost any other time, and it grows through everyday moments with caring adults: talking, playing, feeding and comforting.\n\n## By about 9 months, most babies\n- Are shy, clingy or fearful with strangers\n- Look when you call their name\n- Make sounds like “mamamama” and “babababa”\n- Look for a toy that falls out of sight\n- Sit without support\n\n## By about 12 months, most babies\n- Wave bye-bye and play games like clapping\n- Call a parent “mama”, “baba” or another special name\n- Understand “no” and pause briefly\n- Pick up small things between thumb and finger\n- Pull up to stand and walk holding on to furniture\n\nThese are what most children do by that age, not a race. Children born early may reach them a little later; count from their due date at first and ask your health worker.\n\n## How you can help\n- Talk all day about what you are doing: cooking, bathing, dressing\n- Answer your baby''s sounds as if it is a conversation, then wait for a reply\n- Play peek-a-boo and hide a toy under a cloth\n- Give safe things to hold, bang, drop and put in and out of a pot\n- Give floor time on a clean mat so they can roll, crawl and pull up\n- Read picture books and name what you see\n- Comfort quickly when they cry; a secure baby explores more\n\n## Stranger shyness is a good sign\nAround 8–10 months many babies cry when a new person holds them, or when the mother leaves the room. This shows your baby knows who their own people are. Let them warm up slowly from your lap.\n\n## Act early\nYou know your child best. If something worries you, ask early; help works best when it starts young.","bn":"## বড় পরিবর্তনের বছর\nএই ছয় মাসে শিশু ধরে বসা থেকে আসবাব ধরে দাঁড়ানো পর্যন্ত চলে যায়। এ সময় মস্তিষ্ক প্রায় অন্য যেকোনো সময়ের চেয়ে দ্রুত বাড়ে, আর বাড়ে আদরের মানুষদের সাথে প্রতিদিনের মুহূর্ত দিয়ে: কথা বলা, খেলা, খাওয়ানো আর সান্ত্বনা দেওয়া।\n\n## প্রায় ৯ মাসে বেশিরভাগ শিশু\n- অচেনা মানুষ দেখলে লজ্জা পায়, আঁকড়ে ধরে বা ভয় পায়\n- নাম ধরে ডাকলে তাকায়\n- “মামামামা”, “বাবাবাবা” ধরনের শব্দ করে\n- চোখের আড়ালে পড়ে যাওয়া খেলনা খোঁজে\n- কোনো সাহায্য ছাড়া বসে থাকতে পারে\n\n## প্রায় ১২ মাসে বেশিরভাগ শিশু\n- টা-টা দেয়, হাততালির মতো খেলা খেলে\n- মা-বাবাকে “মা”, “বাবা” বা নিজের কোনো বিশেষ নামে ডাকে\n- “না” বুঝে একটু থেমে যায়\n- বুড়ো আঙুল আর তর্জনী দিয়ে ছোট জিনিস তোলে\n- কিছু ধরে উঠে দাঁড়ায়, আসবাব ধরে ধরে হাঁটে\n\nএগুলো ওই বয়সে বেশিরভাগ শিশু যা করে, কোনো প্রতিযোগিতা নয়। সময়ের আগে জন্মানো শিশু একটু পরে পারতে পারে; শুরুতে প্রসবের সম্ভাব্য তারিখ থেকে হিসাব করুন, আর স্বাস্থ্যকর্মীকে জিজ্ঞেস করুন।\n\n## আপনি যেভাবে সাহায্য করবেন\n- সারাদিন যা করছেন তা মুখে বলুন: রান্না, গোসল, কাপড় পরানো\n- শিশুর আওয়াজের উত্তর দিন যেন গল্প চলছে, তারপর ওর উত্তরের জন্য অপেক্ষা করুন\n- লুকোচুরি খেলুন, কাপড়ের নিচে খেলনা লুকান\n- নিরাপদ জিনিস দিন ধরতে, ঠুকতে, ফেলতে, হাঁড়িতে ভরতে আর বের করতে\n- পরিষ্কার মাদুরে মেঝেতে সময় দিন, যাতে গড়াতে, হামাগুড়ি দিতে আর ধরে দাঁড়াতে পারে\n- ছবির বই পড়ুন, যা দেখছেন তার নাম বলুন\n- কাঁদলে তাড়াতাড়ি সান্ত্বনা দিন; নিশ্চিন্ত শিশু বেশি খুঁজে দেখে\n\n## অচেনা মানুষে লজ্জা ভালো লক্ষণ\n৮–১০ মাসের দিকে নতুন কেউ কোলে নিলে বা মা ঘর থেকে বের হলে অনেক শিশু কাঁদে। এর মানে শিশু চিনতে শিখেছে কারা তার আপন মানুষ। আপনার কোল থেকেই ধীরে ধীরে মানিয়ে নিতে দিন।\n\n## আগেভাগে খোঁজ নিন\nআপনার সন্তানকে আপনিই সবচেয়ে ভালো চেনেন। কিছু নিয়ে চিন্তা হলে আগেই জিজ্ঞেস করুন; সাহায্য যত ছোট বয়সে শুরু হয়, তত ভালো কাজ করে।"}'::jsonb, '{"seek_help":{"en":["Your baby loses a skill they used to have","Does not react to loud sounds or turn to voices","Does not babble, or does not look at faces and smile with you","Cannot sit even with support by about 9 months","Body feels very stiff or very floppy, or uses one side much more than the other"],"bn":["আগে পারত এমন কোনো দক্ষতা হারিয়ে ফেলছে","জোরে শব্দে চমকায় না বা কণ্ঠের দিকে ফেরে না","আধো বুলি বলে না, বা মুখের দিকে তাকিয়ে আপনার সাথে হাসে না","প্রায় ৯ মাসেও ধরে বসালেও বসতে পারে না","শরীর খুব শক্ত বা খুব নরম-নেতানো লাগে, বা শরীরের এক পাশ অন্য পাশের চেয়ে অনেক বেশি ব্যবহার করে"]}}'::jsonb, 4, 183, 365, '{}'::text[], 'any', ARRAY['development', 'milestones', 'sitting', 'crawling', 'babbling', 'stranger anxiety']::text[], false, 'in_review'::lp_review_status, 4013),
  ('in-development-12-24-months', 'article', 'scientific', 'shared', 'educational', 'guideline', '🚶', '{"en":"Development from 12 to 24 months","bn":"১২ থেকে ২৪ মাসের বিকাশ"}'::jsonb, '{"en":"Walking, pointing, first words and big feelings: what most toddlers do by 15, 18 and 24 months, and how to support them.","bn":"হাঁটা, আঙুল দিয়ে দেখানো, প্রথম শব্দ আর বড় বড় অনুভূতি: ১৫, ১৮ ও ২৪ মাসে বেশিরভাগ শিশু যা করে, আর কীভাবে পাশে থাকবেন।"}'::jsonb, '{"en":"## From baby to toddler\nIn the second year your child starts walking, talking and wanting to do things alone. They understand much more than they can say. They also feel big feelings they cannot yet control, which is why tantrums begin.\n\n## By about 15 months, most children\n- Show you an object they like\n- Try to say one or two words besides “mama” or “baba”\n- Point to ask for something or to get help\n- Take a few steps on their own\n- Use fingers to feed themselves\n\n## By about 18 months, most children\n- Point to show you something interesting\n- Try to say three or more words\n- Follow a one-step instruction without gestures, such as “Give it to me”\n- Walk without holding on\n- Try a spoon and drink from an open cup\n\n## By about 24 months, most children\n- Notice when others are hurt or upset\n- Say two words together, like “more milk” or “baba come”\n- Point to at least two body parts when asked\n- Kick a ball and run\n- Eat with a spoon\n\n## How you can help\n- Name everything: body parts, family members, foods, animals on a walk\n- Let your child help: put clothes in a basket, carry a spoon to the table\n- Give simple choices: “banana or papaya?”\n- Play pretend: feed a doll, cook in a toy pot, talk on a toy phone\n- Plenty of active play every day, indoors and outside\n- Keep screens away; real talk and play teach far more\n- Praise effort: “You tried so hard to climb that step!”\n\n## Every child has their own pace\nSome children walk early and talk later, others the opposite. Boys and girls, first and later children, and children in homes with two languages can all differ a little. Watch the overall direction: is your child learning new things month by month?\n\n## Act early\nIf something worries you, talk to a health worker or doctor. Early support for speech, hearing or movement makes a real difference, and asking early never harms.","bn":"## শিশু থেকে হাঁটি হাঁটি পা পা\nদ্বিতীয় বছরে শিশু হাঁটতে, কথা বলতে আর সব নিজে নিজে করতে চায়। যতটা বলতে পারে, বোঝে তার চেয়ে অনেক বেশি। আবার এমন বড় বড় অনুভূতি হয় যা সে এখনো সামলাতে পারে না, তাই জেদ আর কান্নাকাটিও শুরু হয়।\n\n## প্রায় ১৫ মাসে বেশিরভাগ শিশু\n- পছন্দের জিনিস এনে আপনাকে দেখায়\n- “মা” বা “বাবা” ছাড়াও এক-দুটি শব্দ বলার চেষ্টা করে\n- কিছু চাইতে বা সাহায্য পেতে আঙুল দিয়ে দেখায়\n- নিজে নিজে কয়েক পা হাঁটে\n- আঙুল দিয়ে নিজে খাবার তুলে খায়\n\n## প্রায় ১৮ মাসে বেশিরভাগ শিশু\n- মজার কিছু দেখাতে আঙুল তোলে\n- তিন বা তার বেশি শব্দ বলার চেষ্টা করে\n- ইশারা ছাড়াই এক ধাপের কথা মানে, যেমন “আমাকে দাও”\n- কিছু না ধরে হাঁটে\n- চামচ দিয়ে খাওয়ার চেষ্টা করে, খোলা কাপে পান করে\n\n## প্রায় ২৪ মাসে বেশিরভাগ শিশু\n- কেউ ব্যথা পেলে বা মন খারাপ করলে খেয়াল করে\n- দুটি শব্দ একসাথে বলে, যেমন “আরো দুধ” বা “বাবা আসো”\n- জিজ্ঞেস করলে শরীরের অন্তত দুটি অঙ্গ দেখায়\n- বলে লাথি দেয়, দৌড়ায়\n- চামচ দিয়ে খায়\n\n## আপনি যেভাবে সাহায্য করবেন\n- সবকিছুর নাম বলুন: শরীরের অঙ্গ, পরিবারের মানুষ, খাবার, হাঁটতে গিয়ে দেখা পশুপাখি\n- কাজে সাহায্য করতে দিন: কাপড় ঝুড়িতে রাখা, চামচ টেবিলে নেওয়া\n- সহজ পছন্দ দিন: “কলা খাবে, না পেঁপে?”\n- ভান-খেলা খেলুন: পুতুলকে খাওয়ানো, খেলনা হাঁড়িতে রান্না, খেলনা ফোনে কথা\n- প্রতিদিন ঘরে-বাইরে প্রচুর ছোটাছুটির খেলা\n- স্ক্রিন দূরে রাখুন; সত্যিকারের কথা আর খেলা অনেক বেশি শেখায়\n- চেষ্টার প্রশংসা করুন: “সিঁড়িটা ওঠার জন্য কত চেষ্টা করলে!”\n\n## প্রত্যেক শিশুর নিজের গতি\nকেউ আগে হাঁটে, পরে কথা বলে; কেউ উল্টো। ছেলে-মেয়ে, প্রথম বা পরের সন্তান, দুই ভাষার পরিবারের শিশু, সবার মধ্যে একটু আধটু পার্থক্য থাকে। মূল দিকটা দেখুন: মাসে মাসে শিশু নতুন কিছু শিখছে তো?\n\n## আগেভাগে খোঁজ নিন\nকিছু নিয়ে দুশ্চিন্তা হলে স্বাস্থ্যকর্মী বা ডাক্তারের সাথে কথা বলুন। কথা, শোনা বা চলাফেরায় আগেভাগে সাহায্য পেলে সত্যিই বড় পরিবর্তন আসে, আর আগে জিজ্ঞেস করায় কোনো ক্ষতি নেই।"}'::jsonb, '{"seek_help":{"en":["Loses words or skills they used to have","No single words by about 16 months, or no two-word phrases by 24 months","Does not point, wave or show you things by about 18 months","Not walking by 18 months","Does not seem to hear, or does not respond to their name"],"bn":["আগে বলত এমন শব্দ বা পারত এমন দক্ষতা হারিয়ে ফেলছে","প্রায় ১৬ মাসেও একটিও শব্দ নেই, বা ২৪ মাসে দুই শব্দের বাক্য নেই","প্রায় ১৮ মাসেও আঙুল দিয়ে দেখায় না, টা-টা দেয় না, কিছু এনে দেখায় না","১৮ মাসেও হাঁটে না","শুনতে পায় বলে মনে হয় না, বা নাম ধরে ডাকলে সাড়া দেয় না"]}}'::jsonb, 4, 365, 730, '{}'::text[], 'any', ARRAY['development', 'milestones', 'toddler', 'walking', 'words', 'pointing', 'pretend play']::text[], false, 'in_review'::lp_review_status, 4014),
  ('in-first-words', 'article', 'scientific', 'shared', 'educational', 'guideline', '🗣️', '{"en":"First words and how to help language grow","bn":"প্রথম শব্দ, আর ভাষা বাড়াতে যেভাবে সাহায্য করবেন"}'::jsonb, '{"en":"Children learn to talk by being talked with. Simple daily habits do more than any app or video.","bn":"শিশু কথা বলতে শেখে তার সাথে কথা বললে। প্রতিদিনের সহজ কিছু অভ্যাস যেকোনো অ্যাপ বা ভিডিওর চেয়ে অনেক বেশি কাজ করে।"}'::jsonb, '{"en":"## How talking grows\nLanguage starts long before the first word. Around 6–9 months babies babble “bababa” and “mamama”. Around 12 months many say a first word, often “mama”, “baba”, “dada” or a word for food or a pet. By 18 months most try three or more words, and by 2 years most put two words together. Children understand far more than they can say at every stage.\n\n## Conversation, not lectures\nThe biggest boost comes from back-and-forth talk: your child makes a sound or points, you answer, then you wait for their turn. These small exchanges build the brain''s language pathways.\n\n## Everyday ways to help\n- **Narrate:** “Now we wash hands. Water, cold water! Soap, bubbles.”\n- **Name and point:** cow, crow, rickshaw, moon, fan, grandma\n- **Wait:** pause after you speak and give your child time to answer\n- **Build up:** if your child says “ball”, you say “Big ball! Red ball.”\n- **Repeat gently:** if they say “lala” for kola (banana), answer “Yes, kola, you want kola”, without correcting harshly\n- **Read and sing:** picture books, rhymes such as “Ay ay chand mama”, songs with actions\n- **Face to face:** get down to their level so they can see your mouth\n\n## Two languages at home\nMany Bangladeshi families use Bangla with another language, a regional language or English. Learning two languages does not cause speech delay. Speak the language you are most comfortable in, and speak it richly.\n\n## Screens do not teach toddlers to talk\nVideos and cartoons do not wait for your child''s turn. Children under 2 learn language from real people. Video calls with a grandparent or a father working abroad are different: they are real conversations.\n\n## Hearing comes first\nA child who cannot hear well cannot learn words well. Watch whether your child turns to sounds and their name. Frequent ear infections can also affect hearing for a while.\n\n## For fathers, grandparents and siblings\nEvery person who talks with the child adds new words. A father who tells his child about his day, or a grandmother who sings old rhymes, is giving a real gift.","bn":"## কথা যেভাবে বাড়ে\nপ্রথম শব্দের অনেক আগেই ভাষা শুরু হয়। ৬–৯ মাসের দিকে শিশু “বাবাবা”, “মামামা” বলে আধো বুলি দেয়। ১২ মাসের দিকে অনেকে প্রথম শব্দ বলে, প্রায়ই “মা”, “বাবা”, “দাদা” বা কোনো খাবার কিংবা পোষা প্রাণীর নাম। ১৮ মাসে বেশিরভাগ শিশু তিন বা তার বেশি শব্দ বলার চেষ্টা করে, আর ২ বছরে বেশিরভাগ দুটি শব্দ জুড়ে বলে। প্রতিটি ধাপে শিশু যা বলতে পারে, বোঝে তার চেয়ে অনেক বেশি।\n\n## ভাষণ নয়, আলাপ\nসবচেয়ে বেশি কাজ করে আসা-যাওয়ার আলাপ: শিশু একটা আওয়াজ করল বা আঙুল তুলল, আপনি উত্তর দিলেন, তারপর ওর পালার জন্য অপেক্ষা করলেন। এই ছোট ছোট আদান-প্রদানেই মস্তিষ্কে ভাষার পথ তৈরি হয়।\n\n## প্রতিদিনের সহজ উপায়\n- **বলে বলে করুন:** “এখন হাত ধুই। পানি, ঠান্ডা পানি! সাবান, ফেনা।”\n- **নাম বলুন, দেখান:** গরু, কাক, রিকশা, চাঁদ, পাখা, নানু\n- **অপেক্ষা করুন:** কথা বলে একটু থামুন, শিশুকে উত্তর দেওয়ার সময় দিন\n- **বাড়িয়ে বলুন:** শিশু বলল “বল”, আপনি বলুন “বড় বল! লাল বল।”\n- **আলতো করে আবার বলুন:** কলাকে “লালা” বললে বকাঝকা না করে বলুন “হ্যাঁ, কলা, তুমি কলা চাও”\n- **পড়ুন আর গান গান:** ছবির বই, “আয় আয় চাঁদমামা” ধরনের ছড়া, হাত-পা নেড়ে গান\n- **মুখোমুখি:** শিশুর উচ্চতায় নেমে আসুন, যাতে আপনার মুখ দেখতে পায়\n\n## ঘরে দুই ভাষা\nঅনেক পরিবারে বাংলার সাথে আঞ্চলিক ভাষা, অন্য কোনো ভাষা বা ইংরেজি চলে। দুই ভাষা শিখলে কথা দেরিতে ফোটে না। যে ভাষায় আপনি সবচেয়ে স্বচ্ছন্দ, সেই ভাষায় প্রাণ খুলে কথা বলুন।\n\n## স্ক্রিন ছোট শিশুকে কথা শেখায় না\nভিডিও বা কার্টুন শিশুর পালার জন্য অপেক্ষা করে না। ২ বছরের কম শিশু ভাষা শেখে সত্যিকারের মানুষের কাছ থেকে। দাদা-দাদি বা বিদেশে কর্মরত বাবার সাথে ভিডিও কল আলাদা: সেখানে সত্যিকারের আলাপ হয়।\n\n## আগে শোনা\nযে শিশু ভালো শুনতে পায় না, সে ভালোভাবে শব্দও শিখতে পারে না। খেয়াল করুন শিশু শব্দের দিকে আর নাম ধরে ডাকলে ফেরে কিনা। বারবার কানে সংক্রমণ হলেও কিছুদিন শোনায় সমস্যা হতে পারে।\n\n## বাবা, দাদা-দাদি ও ভাইবোনের জন্য\nযে-ই শিশুর সাথে কথা বলে, সে-ই নতুন শব্দ যোগ করে। বাবা যখন নিজের দিনের গল্প শোনান, বা নানি যখন পুরোনো ছড়া গেয়ে শোনান, সেটা সত্যিকারের উপহার।"}'::jsonb, '{"seek_help":{"en":["Does not respond to sounds or their name","No babbling by 12 months","No single words by about 16 months","No two-word phrases by 24 months","Loses words they used to say","Ear pain or discharge from the ear"],"bn":["শব্দে বা নাম ধরে ডাকলে সাড়া দেয় না","১২ মাসেও আধো বুলি নেই","প্রায় ১৬ মাসেও একটিও শব্দ নেই","২৪ মাসে দুই শব্দের বাক্য নেই","আগে বলত এমন শব্দ আর বলে না","কানে ব্যথা বা কান দিয়ে পানি-পুঁজ পড়া"]}}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['language', 'first words', 'talking', 'speech', 'bilingual', 'hearing']::text[], false, 'in_review'::lp_review_status, 4015),
  ('in-play-ideas', 'article', 'scientific', 'shared', 'educational', 'guideline', '🎲', '{"en":"Play ideas for 6 to 24 months","bn":"৬ থেকে ২৪ মাসের খেলার আইডিয়া"}'::jsonb, '{"en":"Play is how young children learn. You do not need costly toys; pots, cups, cloth and your time are enough.","bn":"খেলার মধ্য দিয়েই ছোট শিশু শেখে। দামি খেলনা লাগে না; হাঁড়ি, কাপ, কাপড় আর আপনার সময়ই যথেষ্ট।"}'::jsonb, '{"en":"## Why play matters\nWhen a child bangs a spoon, drops a cup again and again or hides under a cloth, they are learning how the world works: cause and effect, size, sound, and that things still exist when hidden. Play with a loving adult also builds language and trust. WHO''s nurturing care framework counts play and early learning as part of good health.\n\n## Homemade toys that work\n- Steel bowls, a wooden spoon and a lid to bang\n- Plastic cups to stack, nest and fill\n- A cardboard box to crawl into or push\n- A ball made of rolled cloth or socks\n- A clear, tightly sealed plastic bottle with dal or rice inside to shake (glue the lid shut)\n- Old calendars and magazines with big pictures to look at\n- A basket of safe kitchen things to take out and put back\n\nCheck every toy: nothing small enough to fit in the mouth, no loose parts, no sharp edges, no strings longer than a short hand-length, and no button batteries.\n\n## Play by age\n- **6–9 months:** rattles, peek-a-boo, mirror play, passing a toy hand to hand, floor time\n- **9–12 months:** in-and-out games, banging, clapping songs, crawling after a rolling ball\n- **12–18 months:** stacking, pushing a box, simple shape puzzles, scribbling with a fat crayon, water and sand play with you right there\n- **18–24 months:** pretend play, kicking and throwing a ball, dancing, helping with simple chores\n\n## Move every day\nWHO advises that babies under 1 are active several times a day, especially on the floor. Children aged 1–2 should have at least 3 hours of varied physical activity spread through the day. Avoid keeping a child strapped in a seat, pram or carried on the hip for more than an hour at a time while awake.\n\n## Follow their lead\nNotice what interests your child and join in. Let them repeat the same game many times; repetition is how they master it. Talk about what they are doing instead of directing.\n\n## Everyone can play\nPlay does not need long hours. Ten minutes of full attention from a father after work, an older sibling or a grandparent can be the best part of a child''s day.","bn":"## খেলা কেন জরুরি\nশিশু যখন চামচ ঠোকে, বারবার কাপ ফেলে দেয়, বা কাপড়ের নিচে লুকায়, তখন সে শিখছে পৃথিবী কীভাবে চলে: কারণ ও ফল, ছোট-বড়, শব্দ, আর লুকালেও জিনিস হারিয়ে যায় না। আদরের কোনো বড় মানুষের সাথে খেলায় ভাষা আর আস্থাও গড়ে ওঠে। বিশ্ব স্বাস্থ্য সংস্থার লালন-যত্নের (nurturing care) কাঠামোতে খেলা ও শৈশবের শেখা ভালো স্বাস্থ্যেরই অংশ।\n\n## ঘরে বানানো খেলনা\n- স্টিলের বাটি, কাঠের চামচ আর ঢাকনা ঠোকার জন্য\n- প্লাস্টিকের কাপ সাজানো, একটার ভেতর আরেকটা রাখা, ভরা\n- কার্ডবোর্ডের বাক্স, ভেতরে ঢোকা বা ঠেলে নেওয়ার জন্য\n- কাপড় বা মোজা পেঁচিয়ে বানানো বল\n- স্বচ্ছ প্লাস্টিকের বোতলে ডাল বা চাল ভরে ঝাঁকানোর খেলনা (ঢাকনা আঠা দিয়ে শক্ত করে আটকে দিন)\n- বড় ছবিওয়ালা পুরোনো ক্যালেন্ডার ও পত্রিকা\n- রান্নাঘরের নিরাপদ জিনিসের একটা ঝুড়ি, বের করা আর আবার রাখার জন্য\n\nপ্রতিটি খেলনা দেখে নিন: মুখে ঢুকে যাওয়ার মতো ছোট কিছু নয়, খুলে যাওয়া অংশ নয়, ধারালো কিনারা নয়, লম্বা সুতা-দড়ি নয়, আর বোতাম ব্যাটারি একদম নয়।\n\n## বয়স অনুযায়ী খেলা\n- **৬–৯ মাস:** ঝুনঝুনি, লুকোচুরি, আয়নায় খেলা, এক হাত থেকে আরেক হাতে খেলনা নেওয়া, মেঝেতে সময়\n- **৯–১২ মাস:** ভরা-বের করার খেলা, ঠোকাঠুকি, হাততালির গান, গড়িয়ে যাওয়া বলের পেছনে হামাগুড়ি\n- **১২–১৮ মাস:** একটার ওপর আরেকটা সাজানো, বাক্স ঠেলা, সহজ আকারের পাজল, মোটা রং-পেন্সিলে হিজিবিজি, আপনি পাশে থেকে পানি ও বালু নিয়ে খেলা\n- **১৮–২৪ মাস:** ভান-খেলা, বলে লাথি ও ছোড়া, নাচ, ঘরের ছোট কাজে হাত লাগানো\n\n## প্রতিদিন নড়াচড়া\nবিশ্ব স্বাস্থ্য সংস্থা বলে, ১ বছরের কম শিশু দিনে কয়েকবার সক্রিয় থাকবে, বিশেষ করে মেঝেতে। ১–২ বছরের শিশুর দিনে মোট অন্তত ৩ ঘণ্টা নানা রকম নড়াচড়া দরকার, সারাদিনে ছড়িয়ে। জেগে থাকা অবস্থায় শিশুকে একটানা এক ঘণ্টার বেশি আসনে বাঁধা, প্র্যামে বা কোমরে কোলে রাখবেন না।\n\n## শিশুর পিছু পিছু চলুন\nশিশুর কী ভালো লাগছে খেয়াল করুন, সেই খেলায় যোগ দিন। একই খেলা বারবার খেলতে দিন; বারবার করেই সে আয়ত্ত করে। নির্দেশ না দিয়ে, সে যা করছে সেটা নিয়ে কথা বলুন।\n\n## খেলতে পারে সবাই\nখেলার জন্য লম্বা সময় লাগে না। কাজ থেকে ফিরে বাবার, বড় ভাইবোনের বা দাদা-দাদির পুরো মনোযোগের দশটা মিনিট শিশুর দিনের সবচেয়ে সুন্দর অংশ হতে পারে।"}'::jsonb, '{}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['play', 'homemade toys', 'active play', 'outdoor', 'learning through play']::text[], false, 'in_review'::lp_review_status, 4016),
  ('in-walking-and-moving', 'article', 'scientific', 'shared', 'educational', 'guideline', '👣', '{"en":"Crawling, standing and first steps","bn":"হামাগুড়ি, দাঁড়ানো আর প্রথম পা ফেলা"}'::jsonb, '{"en":"Most children walk alone somewhere between 9 and 18 months. Give them floor time and safe space, and skip the baby walker.","bn":"বেশিরভাগ শিশু ৯ থেকে ১৮ মাসের মধ্যে কোনো এক সময় একা হাঁটে। মেঝেতে সময় আর নিরাপদ জায়গা দিন, ওয়াকার বাদ দিন।"}'::jsonb, '{"en":"## The usual path\nMost babies sit alone by about 9 months. Many then crawl, though some shuffle on their bottom or skip crawling altogether, which is usually fine. Around 9–12 months they pull up to stand and walk holding furniture. First steps alone often come between about 12 and 15 months, and most children walk without holding on by 18 months.\n\n## How to help\n- Give lots of time on a clean floor or mat, not in a lap, seat or cot all day\n- Put a favourite toy just out of reach to tempt crawling\n- Offer sturdy furniture, a low bench or your hands to pull up on\n- Let your child push a heavy box or a stable chair across the floor\n- Hold both hands and walk together, then one hand\n- Go barefoot indoors; bare feet help balance and grip\n\n## Shoes\nShoes are only for protecting feet outdoors from heat, thorns and dirt. Choose soft, flexible, well-fitting shoes with a non-slip sole. Hard or tight shoes do not help walking.\n\n## Why we say no to baby walkers\nWheeled baby walkers do not help a child walk sooner. They let a baby move fast before they can control it, reach hot pots, fall down steps and tip over. Child health experts advise not using them. A stationary play centre or plain floor play is safer.\n\n## What is normal\n- Feet that look flat, and walking with feet apart\n- Slightly bowed legs, which usually straighten by about 2 years\n- Lots of falls on the bottom; this is how balance is learned\n- Walking on tiptoe now and then\n\n## Safety grows with movement\nThe day your child moves, the whole house changes. Block stairs and roof doors, keep ponds, buckets and drums out of reach, move hot pots and the boti off the floor, and fix shelves and TVs to the wall.\n\n## Active every day\nWHO advises at least 3 hours of physical activity a day for 1–2 year olds, spread through the day: crawling, walking, climbing, dancing, chasing a ball. Outside play in a safe yard or park is ideal.","bn":"## সাধারণ ধাপ\nবেশিরভাগ শিশু প্রায় ৯ মাসে একা বসতে পারে। তারপর অনেকে হামাগুড়ি দেয়; কেউ কেউ বসে বসে পাছা ঘষে এগোয়, কেউ হামাগুড়ি ছাড়াই সরাসরি দাঁড়ায়, সাধারণত এতে সমস্যা নেই। ৯–১২ মাসের দিকে কিছু ধরে উঠে দাঁড়ায়, আসবাব ধরে ধরে হাঁটে। একা প্রথম পা ফেলা সাধারণত ১২ থেকে ১৫ মাসের মধ্যে, আর ১৮ মাসের মধ্যে বেশিরভাগ শিশু কিছু না ধরে হাঁটে।\n\n## যেভাবে সাহায্য করবেন\n- সারাদিন কোলে, আসনে বা খাটে না রেখে পরিষ্কার মেঝে বা মাদুরে অনেকটা সময় দিন\n- প্রিয় খেলনা একটু দূরে রাখুন, যাতে হামাগুড়ি দিয়ে যেতে চায়\n- ধরে দাঁড়ানোর জন্য শক্ত আসবাব, নিচু টুল বা আপনার হাত দিন\n- একটা ভারী বাক্স বা নড়বড়ে নয় এমন চেয়ার মেঝেতে ঠেলে নিতে দিন\n- দুই হাত ধরে একসাথে হাঁটুন, পরে এক হাত\n- ঘরে খালি পায়ে থাকতে দিন; খালি পায়ে ভারসাম্য ও আঁকড়ে ধরা ভালো হয়\n\n## জুতা\nজুতা শুধু বাইরে গরম, কাঁটা আর ময়লা থেকে পা বাঁচানোর জন্য। নরম, নমনীয়, মাপমতো, পিছলে না যাওয়া তলার জুতা বাছুন। শক্ত বা আঁটসাঁট জুতা হাঁটায় সাহায্য করে না।\n\n## ওয়াকার কেন নয়\nচাকাওয়ালা ওয়াকার শিশুকে আগে হাঁটতে শেখায় না। নিয়ন্ত্রণ শেখার আগেই শিশু দ্রুত ছুটতে পারে, গরম হাঁড়ির নাগাল পায়, সিঁড়ি দিয়ে পড়ে যায়, উল্টে যায়। শিশুস্বাস্থ্য বিশেষজ্ঞরা এটি ব্যবহার না করতে বলেন। এক জায়গায় স্থির খেলার আসন বা সাধারণ মেঝেতে খেলা বেশি নিরাপদ।\n\n## যা স্বাভাবিক\n- পায়ের পাতা চ্যাপ্টা দেখানো, পা ফাঁক করে হাঁটা\n- পা একটু ধনুকের মতো বাঁকা, যা সাধারণত ২ বছরের দিকে সোজা হয়\n- বারবার পাছার ওপর পড়ে যাওয়া; এভাবেই ভারসাম্য শেখে\n- মাঝে মাঝে পায়ের আঙুলে ভর দিয়ে হাঁটা\n\n## চলাফেরার সাথে নিরাপত্তা\nযেদিন শিশু চলতে শুরু করে, সেদিন থেকে পুরো ঘরটাই বদলে যায়। সিঁড়ি আর ছাদের দরজা আটকে দিন, পুকুর, বালতি ও ড্রাম নাগালের বাইরে রাখুন, গরম হাঁড়ি আর বঁটি মেঝে থেকে সরিয়ে রাখুন, তাক ও টিভি দেয়ালে আটকে দিন।\n\n## প্রতিদিন সক্রিয়\nবিশ্ব স্বাস্থ্য সংস্থা ১–২ বছরের শিশুর জন্য দিনে অন্তত ৩ ঘণ্টা নড়াচড়ার কথা বলে, সারাদিনে ছড়িয়ে: হামাগুড়ি, হাঁটা, বেয়ে ওঠা, নাচ, বলের পেছনে ছোটা। নিরাপদ উঠান বা পার্কে বাইরে খেলা সবচেয়ে ভালো।"}'::jsonb, '{"seek_help":{"en":["Not walking alone by 18 months","Loses a movement skill they had","One leg or arm used much less than the other, or a limp","Legs very stiff or very floppy","Bowing of the legs that gets worse after 2 years"],"bn":["১৮ মাসেও একা হাঁটে না","আগে পারত এমন চলাফেরার দক্ষতা হারিয়ে ফেলছে","এক পা বা হাত অন্যটার চেয়ে অনেক কম ব্যবহার করে, বা খুঁড়িয়ে হাঁটে","পা খুব শক্ত বা খুব নরম-নেতানো","২ বছরের পরেও পায়ের বাঁক বাড়ছে"]}}'::jsonb, 4, 274, 730, '{}'::text[], 'any', ARRAY['walking', 'crawling', 'first steps', 'baby walker', 'shoes', 'bow legs', 'active play']::text[], false, 'in_review'::lp_review_status, 4017),
  ('in-screens-under-two', 'article', 'scientific', 'shared', 'important', 'guideline', '📵', '{"en":"Screens under 2: what WHO advises","bn":"২ বছরের কম শিশু ও স্ক্রিন: বিশ্ব স্বাস্থ্য সংস্থা যা বলে"}'::jsonb, '{"en":"WHO advises no screen time for children under 2. Video calls with family are the one helpful exception.","bn":"বিশ্ব স্বাস্থ্য সংস্থা ২ বছরের কম শিশুর জন্য কোনো স্ক্রিন-সময় না রাখতে বলে। পরিবারের সাথে ভিডিও কল একমাত্র উপকারী ব্যতিক্রম।"}'::jsonb, '{"en":"## What the guidelines say\nWHO''s 2019 guideline for children under 5 says that screen time is not recommended for babies under 1 year, and that sedentary screen time is not recommended for 1-year-olds either. From age 2, no more than 1 hour a day, and less is better. When a young child is sitting still, WHO encourages reading, storytelling and talking with a caregiver instead.\n\nChild health experts also note one exception: video calls with family. A call with a grandparent, or a father working in another city or abroad, is a real conversation, so it can be part of your child''s day.\n\n## Why screens are a problem at this age\n- Children under 2 learn language from people who talk back and wait for them. A cartoon does not.\n- Time on a screen is time not spent moving, playing, exploring and sleeping.\n- A TV on in the background reduces how much adults talk to the child, even if no one is watching.\n- Screens before bed make sleep harder.\n- Phones used to calm every cry or to get food in can become a habit that is hard to break.\n\n## Real life in a busy home\nMany parents use the phone because they are tired, cooking alone, or the child cries. That is understandable, not a failure. The goal is to slowly replace screen time with other things that also give you a few free minutes:\n- A basket of safe pots, spoons and cups near the kitchen\n- A box of picture books and old calendars\n- A playpen or a safe corner where you can see your child\n- Songs and rhymes while you work\n- Asking a sibling or grandparent for 15 minutes of play\n\n## Make a family plan\n- No phone or TV during meals, for adults too\n- Keep the TV off when no one is watching\n- No screens in the hour before bed\n- Keep phones out of reach and out of sight, with a lock code\n- Agree with grandparents and helpers on the same rules\n\n## If screens are already a habit\nCut down step by step. Start with meals and bedtime, then reduce daytime use. Expect protest for a few days; stay calm and offer play instead. Within a week or two most children settle.","bn":"## নির্দেশনা কী বলে\nবিশ্ব স্বাস্থ্য সংস্থার ২০১৯ সালের ৫ বছরের কম শিশুদের নির্দেশনা বলছে, ১ বছরের কম শিশুর জন্য স্ক্রিন-সময় সুপারিশ করা হয় না, ১ বছরের শিশুর জন্যও বসে বসে স্ক্রিন দেখা সুপারিশ করা হয় না। ২ বছর থেকে দিনে ১ ঘণ্টার বেশি নয়, কম হলে আরও ভালো। শিশু যখন বসে থাকে, তখন বড়দের সাথে বই পড়া, গল্প শোনা আর কথা বলাকে উৎসাহ দেয় বিশ্ব স্বাস্থ্য সংস্থা।\n\nশিশুস্বাস্থ্য বিশেষজ্ঞরা একটি ব্যতিক্রমের কথাও বলেন: পরিবারের সাথে ভিডিও কল। দাদা-দাদি, বা অন্য শহরে কিংবা বিদেশে কর্মরত বাবার সাথে কল সত্যিকারের আলাপ, তাই এটা শিশুর দিনের অংশ হতে পারে।\n\n## এ বয়সে স্ক্রিন কেন সমস্যা\n- ২ বছরের কম শিশু ভাষা শেখে এমন মানুষের কাছ থেকে, যে উত্তর দেয় আর অপেক্ষা করে। কার্টুন তা করে না।\n- স্ক্রিনের সময় মানে নড়াচড়া, খেলা, খুঁজে দেখা আর ঘুমের সময় কমে যাওয়া।\n- কেউ না দেখলেও পেছনে টিভি চললে বড়রা শিশুর সাথে কম কথা বলেন।\n- ঘুমের আগে স্ক্রিন দেখলে ঘুম আসতে কষ্ট হয়।\n- প্রতিটি কান্না থামাতে বা খাবার খাওয়াতে ফোন দিলে তা এমন অভ্যাস হয়ে যায়, যা ছাড়ানো কঠিন।\n\n## ব্যস্ত সংসারের বাস্তবতা\nঅনেক মা-বাবা ফোন দেন কারণ তাঁরা ক্লান্ত, একা রান্না করছেন, বা শিশু কাঁদছে। এটা বোঝা যায়, এটা ব্যর্থতা নয়। লক্ষ্য হলো ধীরে ধীরে স্ক্রিনের জায়গায় এমন কিছু আনা, যা আপনাকেও কয়েক মিনিট সময় দেয়:\n- রান্নাঘরের কাছে নিরাপদ হাঁড়ি, চামচ আর কাপের একটা ঝুড়ি\n- ছবির বই আর পুরোনো ক্যালেন্ডারের একটা বাক্স\n- চোখের সামনে একটা নিরাপদ কোণ বা ঘেরা জায়গা\n- কাজ করতে করতে গান আর ছড়া\n- ভাইবোন বা দাদা-দাদিকে ১৫ মিনিট খেলতে বলা\n\n## পরিবারের পরিকল্পনা\n- খাওয়ার সময় ফোন বা টিভি নয়, বড়দেরও না\n- কেউ না দেখলে টিভি বন্ধ\n- ঘুমের আগের এক ঘণ্টা কোনো স্ক্রিন নয়\n- ফোন নাগালের ও চোখের বাইরে রাখুন, লক কোড দিয়ে\n- দাদা-দাদি ও সহকারীর সাথেও একই নিয়মে একমত হোন\n\n## অভ্যাস হয়ে গেলে\nধাপে ধাপে কমান। আগে খাওয়া আর ঘুমের সময় থেকে শুরু করুন, তারপর দিনের ব্যবহার কমান। কয়েক দিন শিশু আপত্তি করবে ধরে নিন; শান্ত থাকুন, বদলে খেলা দিন। এক-দুই সপ্তাহের মধ্যে বেশিরভাগ শিশু মানিয়ে নেয়।"}'::jsonb, '{}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['screen time', 'mobile phone', 'tv', 'cartoons', 'video calls', 'under 2']::text[], false, 'in_review'::lp_review_status, 4018),
  ('in-baby-proofing-home', 'article', 'scientific', 'shared', 'important', 'guideline', '🏠', '{"en":"Making your home safe for a moving baby","bn":"চলতে শেখা শিশুর জন্য ঘর নিরাপদ করুন"}'::jsonb, '{"en":"Once your baby rolls, crawls and climbs, everyday things become dangers. Look at your home from your child''s height and fix the big risks first.","bn":"শিশু গড়াতে, হামাগুড়ি দিতে আর বেয়ে উঠতে শিখলে ঘরের সাধারণ জিনিসও বিপদ হয়ে যায়। শিশুর উচ্চতা থেকে ঘরটা দেখুন, বড় ঝুঁকিগুলো আগে ঠিক করুন।"}'::jsonb, '{"en":"## Why now\nWHO notes that most injuries to young children happen at home, and most can be prevented. Between 6 and 24 months children move fast, put everything in their mouth and have no sense of danger. Supervision matters most, but no one can watch every second, so make the home safe too. Get down on your knees and look around: what can your child reach, pull, climb or swallow?\n\n## Falls\n- Never leave a baby alone on a bed, chouki or table, even for a moment\n- Block stairs and the door to the roof; many roofs and balconies have low or no railings\n- Keep windows locked or barred; move beds and chairs away from windows\n- Do not use baby walkers\n\n## Burns\n- Keep children away from the chula, gas stove and kerosene stove; cook on a raised surface if you can\n- Put hot pots, rice and tea at the back, out of reach; turn handles inward\n- Never hold a child while cooking or drinking tea\n- Keep matches, lighters, mosquito coils and candles up high\n- Test bath water with your elbow; it should feel warm, not hot\n- Irons, hot water flasks and their cords out of reach\n\n## Poisoning\n- Kerosene, pesticides, rat poison, cleaning liquids and medicines in a high, locked place\n- Never store them in drink bottles or food containers\n- Put medicines away right after use, including the mother''s iron tablets\n\n## Choking and suffocation\n- Keep coins, buttons, beads, small toys and seeds off the floor\n- Button batteries, magnets and remote controls out of reach\n- Plastic bags tied and stored away\n- Curtain cords and strings tied up high\n\n## Cuts\n- The boti, knives, blades and broken glass stored up high, never on the floor\n\n## Electricity\n- Cover unused sockets; fix loose wires; keep phone chargers unplugged\n\n## Furniture\n- Fix shelves, almirahs and the TV to the wall; children climb and pull them over\n\n## Water\nDrowning can happen in a bucket, drum, ditch or pond within minutes and without a sound. See the water safety guide.\n\n## Know what to do\nSave 999 and the number of your nearest hospital in the phone. Learn basic first aid for choking, burns (cool running water for 20 minutes) and poisoning. Teach everyone who cares for your child, including older siblings and grandparents.","bn":"## কেন এখনই\nবিশ্ব স্বাস্থ্য সংস্থা জানায়, ছোট শিশুদের বেশিরভাগ দুর্ঘটনা ঘটে ঘরে, আর বেশিরভাগই প্রতিরোধযোগ্য। ৬ থেকে ২৪ মাসে শিশু দ্রুত চলে, সবকিছু মুখে দেয়, বিপদ বোঝে না। নজর রাখাই সবচেয়ে জরুরি, কিন্তু প্রতিটি মুহূর্ত কেউ চোখ রাখতে পারে না, তাই ঘরটাও নিরাপদ করুন। হাঁটু গেড়ে বসে চারদিকে তাকান: শিশু কী নাগালে পায়, কী টানতে পারে, কোথায় চড়তে পারে, কী গিলতে পারে?\n\n## পড়ে যাওয়া\n- খাট, চৌকি বা টেবিলে শিশুকে এক মুহূর্তের জন্যও একা রাখবেন না\n- সিঁড়ি আর ছাদের দরজা আটকে দিন; অনেক ছাদ ও বারান্দার রেলিং নিচু বা নেই-ই\n- জানালা বন্ধ রাখুন বা গ্রিল দিন; খাট-চেয়ার জানালা থেকে সরিয়ে রাখুন\n- ওয়াকার ব্যবহার করবেন না\n\n## পুড়ে যাওয়া\n- চুলা, গ্যাসের চুলা ও কেরোসিনের স্টোভ থেকে শিশুকে দূরে রাখুন; সম্ভব হলে উঁচু জায়গায় রান্না করুন\n- গরম হাঁড়ি, ভাত, চা নাগালের বাইরে পেছন দিকে রাখুন; হাতল ভেতরের দিকে ঘুরিয়ে দিন\n- রান্না বা চা খাওয়ার সময় শিশুকে কোলে নেবেন না\n- দেশলাই, লাইটার, মশার কয়েল ও মোমবাতি উঁচুতে রাখুন\n- গোসলের পানি কনুই ডুবিয়ে দেখুন; কুসুম গরম হবে, গরম নয়\n- ইস্ত্রি, গরম পানির ফ্লাস্ক আর তাদের তার নাগালের বাইরে\n\n## বিষক্রিয়া\n- কেরোসিন, কীটনাশক, ইঁদুর মারার বিষ, পরিষ্কারের তরল ও ওষুধ উঁচু ও তালাবদ্ধ জায়গায়\n- এগুলো কখনো পানীয়ের বোতল বা খাবারের পাত্রে রাখবেন না\n- ব্যবহারের পরপরই ওষুধ তুলে রাখুন, মায়ের আয়রন ট্যাবলেটসহ\n\n## গলায় আটকানো ও দম বন্ধ\n- কয়েন, বোতাম, পুঁতি, ছোট খেলনা ও বিচি মেঝে থেকে তুলে রাখুন\n- বোতাম ব্যাটারি, চুম্বক আর রিমোট কন্ট্রোল নাগালের বাইরে\n- প্লাস্টিকের ব্যাগ গিঁট দিয়ে তুলে রাখুন\n- পর্দার দড়ি ও সুতা উঁচুতে বেঁধে রাখুন\n\n## কেটে যাওয়া\n- বঁটি, ছুরি, ব্লেড ও ভাঙা কাচ উঁচুতে রাখুন, কখনো মেঝেতে নয়\n\n## বিদ্যুৎ\n- অব্যবহৃত সকেট ঢেকে দিন; ঢিলে তার ঠিক করুন; চার্জার প্লাগ থেকে খুলে রাখুন\n\n## আসবাব\n- তাক, আলমারি ও টিভি দেয়ালের সাথে আটকে দিন; শিশু বেয়ে উঠে টেনে ফেলে দিতে পারে\n\n## পানি\nবালতি, ড্রাম, ডোবা বা পুকুরে কয়েক মিনিটের মধ্যেই, কোনো শব্দ ছাড়াই শিশু ডুবে যেতে পারে। পানিতে নিরাপত্তার নির্দেশনাটি দেখুন।\n\n## কী করবেন জেনে রাখুন\nফোনে ৯৯৯ আর কাছের হাসপাতালের নম্বর সেভ করে রাখুন। গলায় আটকানো, পোড়া (২০ মিনিট ধরে কলের ঠান্ডা পানি) আর বিষক্রিয়ার প্রাথমিক চিকিৎসা শিখে নিন। শিশুকে যাঁরা দেখেন, বড় ভাইবোন ও দাদা-দাদিসহ, সবাইকে শিখিয়ে দিন।"}'::jsonb, '{"seek_help":{"en":["Any burn bigger than your child''s palm, or on the face, hands or genitals","Your child may have swallowed medicine, kerosene, poison or a battery: go to hospital now and take the bottle or packet","A fall from a height, or a fall followed by vomiting, sleepiness or unusual behaviour"],"bn":["শিশুর হাতের তালুর চেয়ে বড় পোড়া, বা মুখ, হাত কিংবা যৌনাঙ্গে পোড়া","ওষুধ, কেরোসিন, বিষ বা ব্যাটারি গিলে থাকতে পারে: এখনই হাসপাতালে যান, বোতল বা প্যাকেট সাথে নিন","উঁচু থেকে পড়া, বা পড়ার পর বমি, ঘুম ঘুম ভাব বা অস্বাভাবিক আচরণ"]}}'::jsonb, 5, 183, 730, '{}'::text[], 'any', ARRAY['baby proofing', 'injury prevention', 'burns', 'falls', 'poisoning', 'kerosene', 'boti', 'roof']::text[], false, 'in_review'::lp_review_status, 4019),
  ('in-water-safety', 'article', 'scientific', 'family', 'important', 'guideline', '🌊', '{"en":"Water safety: preventing drowning","bn":"পানিতে নিরাপত্তা: ডুবে যাওয়া প্রতিরোধ"}'::jsonb, '{"en":"Drowning is a leading cause of death for young children in Bangladesh. It is quick, silent and preventable with barriers and constant supervision.","bn":"বাংলাদেশে ছোট শিশুদের মৃত্যুর একটি প্রধান কারণ পানিতে ডুবে যাওয়া। এটা ঘটে দ্রুত, নিঃশব্দে, আর বেড়া ও সার্বক্ষণিক নজরদারিতে প্রতিরোধ করা যায়।"}'::jsonb, '{"en":"## Why this matters so much\nWHO describes drowning as a leading cause of death for young children in Bangladesh, especially once they start to crawl and walk. Most of these children drown close to home: in a pond, ditch or canal a few steps from the house, or in a bucket or drum of water inside it. It often happens in the few minutes when a mother is busy with cooking or washing and thinks someone else is watching.\n\n## How drowning happens\n- A young child''s head is heavy. If they fall face-first into even a few centimetres of water, they may not be able to lift themselves out.\n- Drowning is silent. There is no splashing or shouting.\n- It takes only a few minutes for a child to stop breathing under water.\n\n## Barriers at home\n- Cover every water container: buckets, drums, tanks, large pots. Empty buckets and basins after use and turn them upside down.\n- Keep the bathroom and toilet door closed; never leave a child alone in the bath.\n- Fence ponds, ditches and open wells near the house, or block the path to them with a fence or gate.\n- Use a door barrier or a safe play area (playpen) so a crawling child cannot leave the house unseen.\n\n## Supervision that works\n- Near water, a young child must be within arm''s reach of an adult at all times.\n- Hand over clearly: “I am going to cook now, you watch the baby.” Never assume someone else is watching.\n- Older siblings who are still children themselves should not be left in charge near water.\n- Take the child with you when you go to the pond to wash clothes or dishes, and keep them in sight and away from the edge, or leave them with an adult.\n\n## Daycare and community crèches\nWHO advises safe, supervised places for young children away from water. In some areas, community daycare centres look after young children during the busiest household hours. If one is near you, it can be a real protection. Ask your union health worker or local NGO.\n\n## Floods and the rainy season\nDuring the monsoon and floods, water comes closer to the house. Be extra watchful, keep children on raised areas, and never let a young child near flood water.\n\n## If a child is pulled from water\nShout for help and call 999. If the child is not breathing, start rescue breaths and chest compressions if you know how, and keep going until help arrives. Every child pulled from water needs to be checked at a hospital, even if they seem fine. Do not hang the child upside down or spin them to remove water; this wastes precious time.\n\n## For the whole family\nSwimming lessons are for older children, not toddlers. For under-2s, protection comes from barriers and adults. Talk with grandparents, neighbours and helpers so everyone follows the same rules.","bn":"## কেন এত গুরুত্বপূর্ণ\nবিশ্ব স্বাস্থ্য সংস্থা বলছে, বাংলাদেশে ছোট শিশুদের মৃত্যুর একটি প্রধান কারণ পানিতে ডোবা, বিশেষ করে শিশু যখন হামাগুড়ি দিতে ও হাঁটতে শুরু করে। এদের বেশিরভাগ ডোবে বাড়ির খুব কাছে: ঘর থেকে কয়েক পা দূরের পুকুর, ডোবা বা খালে, অথবা ঘরের ভেতরের বালতি বা ড্রামের পানিতে। প্রায়ই ঘটে সেই কয়েক মিনিটে, যখন মা রান্না বা ধোয়ামোছায় ব্যস্ত আর ভাবছেন অন্য কেউ দেখছে।\n\n## কীভাবে ঘটে\n- ছোট শিশুর মাথা ভারী। কয়েক সেন্টিমিটার পানিতেও মুখ থুবড়ে পড়লে সে নিজে মাথা তুলতে নাও পারে।\n- ডোবার সময় শব্দ হয় না। হাত-পা ছোড়া বা চিৎকার থাকে না।\n- পানির নিচে কয়েক মিনিটের মধ্যেই শিশুর শ্বাস বন্ধ হয়ে যেতে পারে।\n\n## ঘরে বাধা তৈরি করুন\n- প্রতিটি পানির পাত্র ঢেকে রাখুন: বালতি, ড্রাম, ট্যাংক, বড় হাঁড়ি। ব্যবহারের পর বালতি ও গামলা খালি করে উল্টে রাখুন।\n- বাথরুম ও টয়লেটের দরজা বন্ধ রাখুন; গোসলের সময় শিশুকে কখনো একা রাখবেন না।\n- বাড়ির কাছের পুকুর, ডোবা ও খোলা কুয়ার চারপাশে বেড়া দিন, অথবা সেদিকে যাওয়ার পথ বেড়া বা গেট দিয়ে আটকে দিন।\n- দরজায় বাধা বা নিরাপদ খেলার ঘেরা জায়গা ব্যবহার করুন, যাতে হামাগুড়ি দেওয়া শিশু কারো চোখ এড়িয়ে ঘর থেকে বের হতে না পারে।\n\n## যে নজরদারি কাজ করে\n- পানির কাছে ছোট শিশু সবসময় একজন বড় মানুষের হাতের নাগালের মধ্যে থাকবে।\n- স্পষ্ট করে দায়িত্ব দিন: “আমি এখন রান্নায় যাচ্ছি, তুমি বাবুকে দেখো।” অন্য কেউ দেখছে, ধরে নেবেন না।\n- যে বড় ভাইবোন নিজেই শিশু, তাকে পানির কাছে দায়িত্ব দেবেন না।\n- পুকুরে কাপড় বা থালাবাসন ধুতে গেলে শিশুকে সাথে নিয়ে চোখের সামনে ও কিনারা থেকে দূরে রাখুন, অথবা কোনো বড় মানুষের কাছে রেখে যান।\n\n## ডে-কেয়ার ও কমিউনিটি শিশুযত্ন কেন্দ্র\nবিশ্ব স্বাস্থ্য সংস্থা ছোট শিশুদের জন্য পানি থেকে দূরে নিরাপদ ও তত্ত্বাবধানে থাকা জায়গার পরামর্শ দেয়। কিছু এলাকায় কমিউনিটি শিশুযত্ন কেন্দ্র সংসারের সবচেয়ে ব্যস্ত সময়ে ছোট শিশুদের দেখাশোনা করে। কাছে থাকলে এটা সত্যিকারের সুরক্ষা। ইউনিয়নের স্বাস্থ্যকর্মী বা স্থানীয় এনজিওর কাছে খোঁজ নিন।\n\n## বর্ষা ও বন্যা\nবর্ষা ও বন্যায় পানি ঘরের আরও কাছে চলে আসে। তখন বাড়তি সতর্ক থাকুন, শিশুকে উঁচু জায়গায় রাখুন, বন্যার পানির কাছে ছোট শিশুকে কখনো যেতে দেবেন না।\n\n## শিশুকে পানি থেকে তোলার পর\nচিৎকার করে সাহায্য ডাকুন, ৯৯৯-এ ফোন করুন। শিশু শ্বাস না নিলে, জানা থাকলে মুখে শ্বাস দেওয়া ও বুকে চাপ দেওয়া শুরু করুন, সাহায্য না আসা পর্যন্ত চালিয়ে যান। পানি থেকে তোলা প্রতিটি শিশুকে হাসপাতালে দেখাতে হবে, ঠিক মনে হলেও। পানি বের করতে শিশুকে উল্টো করে ঝোলাবেন না বা মাথার ওপর ঘোরাবেন না; এতে মূল্যবান সময় নষ্ট হয়।\n\n## পুরো পরিবারের জন্য\nসাঁতার শেখা বড় শিশুদের জন্য, হাঁটি হাঁটি পা পা বয়সের জন্য নয়। ২ বছরের কম শিশুর সুরক্ষা আসে বাধা আর বড়দের নজর থেকে। দাদা-দাদি, প্রতিবেশী ও সহকারীদের সাথে কথা বলুন, যাতে সবাই একই নিয়ম মানেন।"}'::jsonb, '{"do_now":{"en":["Walk around your home today and cover or empty every container of water","Agree who watches the child at each busy time of day","Look at the path from your door to the nearest pond or ditch, and plan a barrier"],"bn":["আজই ঘরের চারপাশ ঘুরে প্রতিটি পানির পাত্র ঢাকুন বা খালি করুন","দিনের প্রতিটি ব্যস্ত সময়ে কে শিশুকে দেখবেন, ঠিক করে নিন","দরজা থেকে সবচেয়ে কাছের পুকুর বা ডোবার পথটা দেখুন, বাধা দেওয়ার পরিকল্পনা করুন"]},"seek_help":{"en":["Any child who was found in water, even if they now seem well","Cough, fast breathing or unusual sleepiness in the hours after being in water"],"bn":["পানিতে পাওয়া যেকোনো শিশু, এখন ভালো মনে হলেও","পানিতে পড়ার পরের কয়েক ঘণ্টায় কাশি, দ্রুত শ্বাস বা অস্বাভাবিক ঘুম ঘুম ভাব"]}}'::jsonb, 5, 183, 730, '{}'::text[], 'any', ARRAY['drowning', 'water safety', 'pond', 'bucket', 'supervision', 'daycare', 'barrier', 'flood']::text[], false, 'in_review'::lp_review_status, 4020),
  ('in-vaccines-9-15-months', 'article', 'scientific', 'shared', 'important', 'guideline', '💉', '{"en":"Vaccines at 9 and 15 months: MR and the card","bn":"৯ ও ১৫ মাসের টিকা: এমআর ও টিকা কার্ড"}'::jsonb, '{"en":"Measles-rubella (MR) vaccine is given at 9 months and again at 15 months in Bangladesh''s EPI. Check the card for every dose due.","bn":"বাংলাদেশের ইপিআই-তে হাম-রুবেলা (এমআর) টিকা দেওয়া হয় ৯ মাসে এবং আবার ১৫ মাসে। প্রতিটি ডোজের জন্য টিকা কার্ড দেখে নিন।"}'::jsonb, '{"en":"## What is given\nIn Bangladesh''s Expanded Programme on Immunization (EPI), children get the measles-rubella (MR) vaccine twice:\n- **MR 1 at 9 months**\n- **MR 2 at 15 months**\n\nAt the 9-month visit your child may also get other vaccines that have been added to the routine schedule in recent years. The vaccinator will tell you, and the card will show the date. EPI vaccines are free at government centres and outreach sites.\n\n## Why two doses\nMeasles spreads very easily and can cause pneumonia, severe diarrhoea, eye damage and death in young children. Rubella is usually mild in children but can harm an unborn baby if a pregnant woman catches it. Two doses give strong, lasting protection and help protect the whole community.\n\n## Before you go\n- Find the vaccine card and check which doses are due or missed\n- If any earlier dose (Penta, OPV, PCV, fIPV) was missed, take the child anyway; missed doses can usually be caught up\n- Feed your child before you leave, and take water and a cloth\n- A mild cold is usually not a reason to wait; let the vaccinator decide\n\n## After the vaccine\nSome children get a mild fever, are fussy, or have a light rash some days later. These usually pass on their own. Keep breastfeeding and giving fluids, dress lightly, and ask the health worker before giving any fever medicine.\n\n## Campaigns\nThe government sometimes holds MR campaigns for all children in an age group. Children usually get a campaign dose even if they had their routine doses; it is an extra protection. Keep the card safe and write campaign doses on it if possible.\n\n## The card is precious\nKeep the vaccine card with the birth certificate in a plastic sleeve. Take a photo of it on your phone. It will be needed for school admission and travel.","bn":"## কী দেওয়া হয়\nবাংলাদেশের সম্প্রসারিত টিকাদান কর্মসূচি (ইপিআই)-তে শিশুকে হাম-রুবেলা (এমআর) টিকা দুইবার দেওয়া হয়:\n- **এমআর-১, ৯ মাসে**\n- **এমআর-২, ১৫ মাসে**\n\n৯ মাসের সাক্ষাতে সম্প্রতি নিয়মিত সূচিতে যুক্ত হওয়া অন্য টিকাও দেওয়া হতে পারে। টিকাদানকারী জানিয়ে দেবেন, কার্ডে তারিখ লেখা থাকবে। সরকারি কেন্দ্র ও আউটরিচ টিকাকেন্দ্রে ইপিআই টিকা বিনামূল্যে।\n\n## কেন দুই ডোজ\nহাম খুব সহজে ছড়ায়, আর ছোট শিশুর নিউমোনিয়া, মারাত্মক ডায়রিয়া, চোখের ক্ষতি, এমনকি মৃত্যুও ঘটাতে পারে। রুবেলা শিশুদের সাধারণত হালকা হয়, কিন্তু গর্ভবতী নারীর হলে গর্ভের শিশুর ক্ষতি করতে পারে। দুই ডোজ শক্ত ও দীর্ঘস্থায়ী সুরক্ষা দেয়, পুরো এলাকাকেও রক্ষা করে।\n\n## যাওয়ার আগে\n- টিকা কার্ড বের করে দেখুন কোন ডোজ বাকি বা বাদ পড়েছে\n- আগের কোনো ডোজ (পেন্টা, ওপিভি, পিসিভি, এফআইপিভি) বাদ পড়লেও শিশুকে নিয়ে যান; বাদ পড়া ডোজ সাধারণত পরে দেওয়া যায়\n- বের হওয়ার আগে খাইয়ে নিন, সাথে পানি ও একটা কাপড় নিন\n- হালকা সর্দি সাধারণত অপেক্ষার কারণ নয়; টিকাদানকারীকে সিদ্ধান্ত নিতে দিন\n\n## টিকার পরে\nকোনো কোনো শিশুর হালকা জ্বর হয়, খিটখিটে থাকে, বা কয়েক দিন পর হালকা র‍্যাশ ওঠে। এগুলো সাধারণত নিজে থেকেই সেরে যায়। বুকের দুধ ও তরল চালিয়ে যান, হালকা কাপড় পরান, জ্বরের ওষুধ দেওয়ার আগে স্বাস্থ্যকর্মীর পরামর্শ নিন।\n\n## ক্যাম্পেইন\nসরকার মাঝে মাঝে নির্দিষ্ট বয়সের সব শিশুর জন্য এমআর ক্যাম্পেইন করে। নিয়মিত ডোজ নেওয়া থাকলেও সাধারণত ক্যাম্পেইনের ডোজ দেওয়া হয়; এটা বাড়তি সুরক্ষা। কার্ড যত্নে রাখুন, সম্ভব হলে ক্যাম্পেইনের ডোজও কার্ডে লিখিয়ে নিন।\n\n## কার্ডটি অমূল্য\nটিকা কার্ড জন্মনিবন্ধনের সাথে প্লাস্টিকের খামে রাখুন। ফোনে একটা ছবি তুলে রাখুন। স্কুলে ভর্তি ও ভ্রমণে এটি লাগবে।"}'::jsonb, '{"seek_help":{"en":["High fever, a fit, or a child who is very sleepy or hard to wake after a vaccine","Swelling of the face or trouble breathing soon after a vaccine: emergency","A rash with fever, red eyes and cough in a child who has not had MR: see a doctor, it may be measles"],"bn":["টিকার পর বেশি জ্বর, খিঁচুনি, বা শিশু খুব ঘুমকাতুরে বা জাগানো কঠিন","টিকার কিছুক্ষণের মধ্যে মুখ ফোলা বা শ্বাসকষ্ট: জরুরি অবস্থা","এমআর না পাওয়া শিশুর জ্বরের সাথে র‍্যাশ, লাল চোখ ও কাশি: ডাক্তার দেখান, হাম হতে পারে"]}}'::jsonb, 3, 244, 548, '{}'::text[], 'any', ARRAY['vaccine', 'mr', 'measles', 'rubella', 'epi', '9 months', '15 months', 'vaccine card']::text[], false, 'in_review'::lp_review_status, 4021),
  ('in-vitamin-a-deworming', 'article', 'scientific', 'shared', 'important', 'guideline', '💊', '{"en":"Vitamin A campaigns and deworming","bn":"ভিটামিন এ ক্যাম্পেইন ও কৃমিনাশক"}'::jsonb, '{"en":"Bangladesh gives free vitamin A capsules to young children in national campaigns. Deworming is given from the age the programme and your health worker advise.","bn":"বাংলাদেশে জাতীয় ক্যাম্পেইনে ছোট শিশুদের বিনামূল্যে ভিটামিন এ ক্যাপসুল খাওয়ানো হয়। কৃমিনাশক দেওয়া হয় কর্মসূচি ও স্বাস্থ্যকর্মী যে বয়স থেকে বলেন, সেই বয়স থেকে।"}'::jsonb, '{"en":"## Why vitamin A\nVitamin A helps the eyes, the skin and the body''s defence against infections such as diarrhoea and measles. Young children who lack it are more likely to fall seriously ill. Bangladesh runs a national vitamin A campaign, usually twice a year, when health workers give a capsule to children from 6 months up to 5 years.\n\n## On campaign day\n- Watch for announcements from the mosque, union office, community clinic, health worker or TV\n- Take your child to the nearest campaign point; it is free\n- In the campaign, a lower-dose capsule is used for babies 6–11 months and a higher-dose capsule for children 12–59 months; health workers usually tell them apart by colour\n- The health worker cuts the capsule and squeezes the drops into the child''s mouth. A child should never swallow a capsule whole\n- Tell the health worker if your child received vitamin A from a doctor in the last month, or is very ill that day\n- Ask for the dose to be noted on the card if there is a space\n\nDo not buy and give vitamin A capsules at home on your own. Too much vitamin A can be harmful. Follow the national programme and your health worker.\n\n## Deworming\nWorms spread through soil, dirty hands and unsafe water, and can cause anaemia and poor growth. Deworming tablets are usually not given before 1 year. From the age the national programme or your health worker advises, a single dose may be given about every six months, sometimes on campaign days. Follow their advice on which tablet and how much; for young children the tablet is usually crushed or chewed.\n\n## Food and habits still matter most\nCapsules and tablets help, but daily habits protect every day:\n- Foods rich in vitamin A: egg, liver, small fish like mola, ripe mango and papaya, pumpkin, carrot and dark green leafy vegetables, with a little oil\n- Handwashing with soap before eating and after the toilet\n- Using a latrine, keeping nails short and clean, and sandals outdoors\n- Safe drinking water","bn":"## ভিটামিন এ কেন\nভিটামিন এ চোখ, ত্বক আর ডায়রিয়া ও হামের মতো সংক্রমণের বিরুদ্ধে শরীরের প্রতিরোধে সাহায্য করে। যেসব ছোট শিশুর এর ঘাটতি থাকে, তারা বেশি গুরুতর অসুস্থ হয়। বাংলাদেশে সাধারণত বছরে দুইবার জাতীয় ভিটামিন এ ক্যাম্পেইন হয়, তখন স্বাস্থ্যকর্মীরা ৬ মাস থেকে ৫ বছর পর্যন্ত শিশুদের ক্যাপসুল খাওয়ান।\n\n## ক্যাম্পেইনের দিন\n- মসজিদ, ইউনিয়ন পরিষদ, কমিউনিটি ক্লিনিক, স্বাস্থ্যকর্মী বা টিভির ঘোষণার দিকে খেয়াল রাখুন\n- শিশুকে কাছের ক্যাম্পেইন কেন্দ্রে নিয়ে যান; এটা বিনামূল্যে\n- ক্যাম্পেইনে ৬–১১ মাসের শিশুর জন্য কম মাত্রার আর ১২–৫৯ মাসের শিশুর জন্য বেশি মাত্রার ক্যাপসুল থাকে; স্বাস্থ্যকর্মীরা সাধারণত রং দেখে আলাদা করেন\n- স্বাস্থ্যকর্মী ক্যাপসুল কেটে ভেতরের তরল শিশুর মুখে চেপে দেন। শিশুকে কখনো আস্ত ক্যাপসুল গিলতে দেবেন না\n- গত এক মাসে ডাক্তার ভিটামিন এ দিয়ে থাকলে, বা সেদিন শিশু খুব অসুস্থ থাকলে, স্বাস্থ্যকর্মীকে জানান\n- কার্ডে জায়গা থাকলে ডোজটি লিখে দিতে বলুন\n\nনিজে কিনে বাড়িতে ভিটামিন এ ক্যাপসুল খাওয়াবেন না। বেশি ভিটামিন এ ক্ষতিকর হতে পারে। জাতীয় কর্মসূচি ও স্বাস্থ্যকর্মীর পরামর্শ মেনে চলুন।\n\n## কৃমিনাশক\nকৃমি ছড়ায় মাটি, নোংরা হাত আর অনিরাপদ পানির মাধ্যমে, এতে রক্তস্বল্পতা ও বৃদ্ধি কমে যেতে পারে। সাধারণত ১ বছরের আগে কৃমিনাশক দেওয়া হয় না। জাতীয় কর্মসূচি বা স্বাস্থ্যকর্মী যে বয়স থেকে বলেন, সেই বয়স থেকে প্রায় ছয় মাস পরপর এক ডোজ দেওয়া হতে পারে, কখনো ক্যাম্পেইনের দিনেও। কোন ট্যাবলেট, কতটুকু, তা তাঁদের পরামর্শমতো দিন; ছোট শিশুর জন্য ট্যাবলেট সাধারণত গুঁড়া করে বা চিবিয়ে খাওয়ানো হয়।\n\n## খাবার ও অভ্যাসই সবচেয়ে বড়\nক্যাপসুল ও ট্যাবলেট সাহায্য করে, কিন্তু প্রতিদিনের অভ্যাস প্রতিদিন রক্ষা করে:\n- ভিটামিন এ সমৃদ্ধ খাবার: ডিম, কলিজা, মলার মতো ছোট মাছ, পাকা আম ও পেঁপে, মিষ্টিকুমড়া, গাজর আর গাঢ় সবুজ শাক, সাথে একটু তেল\n- খাওয়ার আগে ও টয়লেটের পরে সাবান দিয়ে হাত ধোয়া\n- ল্যাট্রিন ব্যবহার, নখ ছোট ও পরিষ্কার রাখা, বাইরে স্যান্ডেল পরা\n- নিরাপদ খাবার পানি"}'::jsonb, '{"seek_help":{"en":["Your child cannot see well in dim light or at dusk","Dry, wrinkled patches on the white of the eye","Your child is pale, tired or not growing well","Worms seen in the stool, or a very itchy bottom at night"],"bn":["কম আলোয় বা সন্ধ্যায় শিশু ভালো দেখতে পায় না","চোখের সাদা অংশে শুকনো, কোঁচকানো দাগ","শিশু ফ্যাকাশে, ক্লান্ত বা ঠিকমতো বাড়ছে না","পায়খানায় কৃমি দেখা যায়, বা রাতে মলদ্বারে খুব চুলকায়"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['vitamin a', 'capsule', 'campaign', 'deworming', 'worms', 'albendazole', 'national programme']::text[], false, 'in_review'::lp_review_status, 4022),
  ('in-cough-cold-pneumonia', 'article', 'scientific', 'shared', 'important', 'guideline', '🤧', '{"en":"Colds, coughs and the signs of pneumonia","bn":"সর্দি, কাশি আর নিউমোনিয়ার লক্ষণ"}'::jsonb, '{"en":"Most colds get better at home. Learn to count breathing and look for chest indrawing: these are the signs of pneumonia that need a health worker today.","bn":"বেশিরভাগ সর্দি-কাশি ঘরেই সেরে যায়। শ্বাস গুনতে আর বুকের খাঁচা দেবে যাওয়া দেখতে শিখুন: এগুলো নিউমোনিয়ার লক্ষণ, যার জন্য আজই স্বাস্থ্যকর্মীর কাছে যেতে হবে।"}'::jsonb, '{"en":"## Colds are common\nYoung children may catch several colds a year, more when they mix with other children. A runny or blocked nose, mild cough, sneezing and a low fever usually improve within a week to ten days.\n\n## Caring at home\n- Keep breastfeeding, more often than usual\n- Offer extra fluids and small, frequent meals\n- Clear a blocked nose gently, especially before feeds, with a clean soft cloth; saline drops can help\n- Let your child rest and keep them warm but not overdressed\n- For children over 1 year, a little honey in warm water can soothe a cough; never give honey under 1 year\n- Keep the home free of smoke: no smoking indoors, and keep the child away from the cooking fire\n\nCough and cold medicines are not advised for young children unless a doctor prescribes them. Antibiotics do not help a cold.\n\n## Pneumonia: the signs to know\nPneumonia is an infection of the lungs and one of the most serious illnesses of young children. WHO''s IMCI guide teaches health workers to look for two signs, and parents can learn them too.\n\n**1. Fast breathing.** When your child is calm or asleep, lift the clothes and count the breaths for one full minute (one rise of the chest is one breath).\n- 2 to 12 months: 50 breaths or more in a minute is fast\n- 12 months to 5 years: 40 breaths or more in a minute is fast\n\n**2. Chest indrawing.** Watch the lower chest as your child breathes in. If the lower chest wall sucks inwards instead of moving out, that is chest indrawing.\n\nIf your child has a cough or difficult breathing with either of these signs, take them to a health worker the same day. Pneumonia needs the right treatment.\n\n## Danger signs\nGo to hospital immediately if your child:\n- Cannot drink or breastfeed\n- Vomits everything\n- Has had a fit\n- Is very sleepy or hard to wake\n- Makes a harsh noise when breathing in while calm\n- Has blue lips or tongue\n\n## Prevention\nBreastfeeding, good food, handwashing, a smoke-free home and on-time vaccines (Penta, PCV and MR all help protect against pneumonia) lower the risk.","bn":"## সর্দি খুব সাধারণ\nছোট শিশুর বছরে কয়েকবার সর্দি লাগতে পারে, অন্য শিশুদের সাথে মিশলে আরও বেশি। নাক দিয়ে পানি পড়া বা নাক বন্ধ, হালকা কাশি, হাঁচি আর অল্প জ্বর সাধারণত এক সপ্তাহ থেকে দশ দিনে ভালো হয়ে যায়।\n\n## ঘরে যত্ন\n- বুকের দুধ চালিয়ে যান, স্বাভাবিকের চেয়ে বেশিবার\n- বাড়তি তরল আর অল্প অল্প করে বারবার খাবার দিন\n- নাক বন্ধ থাকলে, বিশেষ করে খাওয়ানোর আগে, পরিষ্কার নরম কাপড় দিয়ে আলতো করে পরিষ্কার করুন; নাকের স্যালাইন ড্রপ কাজে দিতে পারে\n- শিশুকে বিশ্রাম নিতে দিন, গরম রাখুন কিন্তু অতিরিক্ত কাপড় নয়\n- ১ বছরের বেশি শিশুর কাশিতে কুসুম গরম পানিতে একটু মধু আরাম দিতে পারে; ১ বছরের কম শিশুকে কখনো মধু দেবেন না\n- ঘর ধোঁয়ামুক্ত রাখুন: ঘরে ধূমপান নয়, রান্নার চুলার ধোঁয়া থেকে শিশুকে দূরে রাখুন\n\nডাক্তার না দিলে ছোট শিশুকে কাশি বা সর্দির ওষুধ দেওয়া উচিত নয়। সাধারণ সর্দিতে অ্যান্টিবায়োটিক কাজ করে না।\n\n## নিউমোনিয়া: যে লক্ষণ জানতে হবে\nনিউমোনিয়া ফুসফুসের সংক্রমণ, ছোট শিশুদের সবচেয়ে গুরুতর অসুখগুলোর একটি। বিশ্ব স্বাস্থ্য সংস্থার আইএমসিআই (IMCI) নির্দেশিকা স্বাস্থ্যকর্মীদের দুটি লক্ষণ দেখতে শেখায়; মা-বাবাও এগুলো শিখতে পারেন।\n\n**১. দ্রুত শ্বাস।** শিশু শান্ত থাকলে বা ঘুমালে জামা তুলে পুরো এক মিনিট শ্বাস গুনুন (বুক একবার ফুলে ওঠা মানে একটি শ্বাস)।\n- ২ থেকে ১২ মাস: মিনিটে ৫০ বা তার বেশি হলে দ্রুত\n- ১২ মাস থেকে ৫ বছর: মিনিটে ৪০ বা তার বেশি হলে দ্রুত\n\n**২. বুকের খাঁচা দেবে যাওয়া।** শ্বাস নেওয়ার সময় বুকের নিচের দিকটা দেখুন। বাইরে না ফুলে যদি বুকের নিচের অংশ ভেতরে ঢুকে যায়, সেটাই বুক দেবে যাওয়া।\n\nকাশি বা শ্বাসকষ্টের সাথে এর যেকোনো একটি লক্ষণ থাকলে সেদিনই শিশুকে স্বাস্থ্যকর্মীর কাছে নিয়ে যান। নিউমোনিয়ার সঠিক চিকিৎসা দরকার।\n\n## বিপদের লক্ষণ\nশিশুর এগুলো হলে এখনই হাসপাতালে যান:\n- কিছু পান করতে বা বুকের দুধ টানতে পারছে না\n- যা খায় সব বমি করে দেয়\n- খিঁচুনি হয়েছে\n- খুব ঘুমকাতুরে বা জাগানো কঠিন\n- শান্ত অবস্থায়ও শ্বাস নেওয়ার সময় কর্কশ শব্দ হয়\n- ঠোঁট বা জিভ নীল\n\n## প্রতিরোধ\nবুকের দুধ, ভালো খাবার, হাত ধোয়া, ধোঁয়ামুক্ত ঘর আর সময়মতো টিকা (পেন্টা, পিসিভি ও এমআর নিউমোনিয়া থেকে রক্ষায় সাহায্য করে) ঝুঁকি কমায়।"}'::jsonb, '{"warning_signs":{"en":["Fast breathing: 50 or more a minute (2–12 months) or 40 or more (12 months–5 years)","Lower chest sucks in with each breath","Unable to drink or breastfeed, or vomits everything","A fit, or very sleepy and hard to wake","Harsh noise when breathing in while calm, or blue lips"],"bn":["দ্রুত শ্বাস: মিনিটে ৫০ বা বেশি (২–১২ মাস) বা ৪০ বা বেশি (১২ মাস–৫ বছর)","প্রতিটি শ্বাসে বুকের নিচের অংশ ভেতরে ঢুকে যায়","পান করতে বা বুকের দুধ টানতে পারে না, বা সব বমি করে","খিঁচুনি, বা খুব ঘুমকাতুরে ও জাগানো কঠিন","শান্ত অবস্থায় শ্বাস নিতে কর্কশ শব্দ, বা নীল ঠোঁট"]},"seek_help":{"en":["Any warning sign: go to hospital or call 999 now","Fast breathing or chest indrawing: see a health worker today","Cough for more than 14 days","Fever lasting more than 2 days, or a cold that gets worse after getting better"],"bn":["যেকোনো বিপদের লক্ষণ: এখনই হাসপাতালে যান বা ৯৯৯-এ ফোন করুন","দ্রুত শ্বাস বা বুক দেবে যাওয়া: আজই স্বাস্থ্যকর্মীকে দেখান","১৪ দিনের বেশি কাশি","২ দিনের বেশি জ্বর, বা ভালো হতে হতে আবার সর্দি-কাশি বেড়ে যাওয়া"]}}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['cough', 'cold', 'pneumonia', 'fast breathing', 'chest indrawing', 'respiratory infection']::text[], false, 'in_review'::lp_review_status, 4023),
  ('in-diarrhoea-ors-zinc', 'article', 'scientific', 'shared', 'important', 'guideline', '💧', '{"en":"Diarrhoea: ORS, zinc and keep feeding","bn":"ডায়রিয়া: খাবার স্যালাইন, জিংক ও খাওয়া চালিয়ে যাওয়া"}'::jsonb, '{"en":"Most diarrhoea can be treated at home with ORS, zinc for 10–14 days and continued feeding, as your health worker advises. Know the signs that need a hospital.","bn":"বেশিরভাগ ডায়রিয়া ঘরেই সারানো যায়: খাবার স্যালাইন, ১০–১৪ দিন জিংক আর খাওয়া চালিয়ে যাওয়া, স্বাস্থ্যকর্মীর পরামর্শমতো। কোন লক্ষণে হাসপাতালে যেতে হবে, জেনে রাখুন।"}'::jsonb, '{"en":"## What diarrhoea is\nDiarrhoea means three or more loose or watery stools in a day. The real danger is not the stool itself but the loss of water and salts from the body (dehydration), which can quickly become serious in a young child.\n\n## The three things that treat it\nWHO''s treatment for diarrhoea at home rests on three steps.\n\n**1. Give ORS (orsaline).**\n- Mix one packet in exactly the amount of clean water written on the packet; not more, not less\n- After each loose stool, a child under 2 needs about 50–100 ml, roughly a quarter to half of a 250 ml cup, in addition to their usual drinks\n- Give it slowly by spoon or small sips from a cup\n- If your child vomits, wait 10 minutes, then continue more slowly\n- Make a fresh mix each day and throw away the old one as the packet says\n- If you have no packet yet, give rice water (bhater mar) or clean water and get ORS as soon as you can\n\n**2. Give zinc for 10–14 days.**\nZinc tablets shorten diarrhoea and help prevent it coming back over the next months. Your health worker will give or advise the dose; the tablet dissolves in a little breast milk, ORS or clean water. Keep giving it for the full 10–14 days, even after the diarrhoea stops.\n\n**3. Keep feeding.**\nBreastfeed more often than usual. Keep giving soft foods such as khichuri, mashed potato, banana or egg in small, frequent meals. After the diarrhoea ends, give one extra meal a day for about two weeks.\n\n## What not to give\n- Medicines to stop diarrhoea, or antibiotics, unless a doctor prescribes them; most diarrhoea does not need antibiotics\n- Soft drinks, packaged juice and very sweet drinks, which can make it worse\n- Do not stop food or breast milk\n\n## Prevention\nHandwashing with soap, safe water, clean food, using a latrine and safely disposing of children''s stool all prevent diarrhoea. Breastfeeding and vaccines also protect.","bn":"## ডায়রিয়া কী\nদিনে তিন বা তার বেশিবার পাতলা বা পানির মতো পায়খানাকে ডায়রিয়া বলে। আসল বিপদ পায়খানা নয়, শরীর থেকে পানি ও লবণ বেরিয়ে যাওয়া (পানিশূন্যতা), যা ছোট শিশুর ক্ষেত্রে খুব দ্রুত গুরুতর হয়ে উঠতে পারে।\n\n## যে তিনটি জিনিসে সারে\nঘরে ডায়রিয়ার চিকিৎসায় বিশ্ব স্বাস্থ্য সংস্থার পরামর্শ তিনটি ধাপে।\n\n**১. খাবার স্যালাইন দিন।**\n- প্যাকেটের গায়ে যতটুকু পরিষ্কার পানির কথা লেখা আছে, ঠিক ততটুকুতে একটি প্যাকেট গুলুন; বেশিও না, কমও না\n- প্রতিবার পাতলা পায়খানার পর ২ বছরের কম শিশুকে স্বাভাবিক পানীয়ের বাইরেও প্রায় ৫০–১০০ মিলি, মানে ২৫০ মিলি কাপের মোটামুটি সিকি থেকে আধা কাপ, দিতে হয়\n- চামচে বা কাপ থেকে অল্প অল্প চুমুকে ধীরে দিন\n- বমি করলে ১০ মিনিট অপেক্ষা করে আবার আরও ধীরে দিন\n- প্রতিদিন নতুন করে গুলুন, পুরোনোটা প্যাকেটের নির্দেশমতো ফেলে দিন\n- এখনো প্যাকেট না থাকলে ভাতের মাড় বা পরিষ্কার পানি দিন, আর যত দ্রুত সম্ভব খাবার স্যালাইন জোগাড় করুন\n\n**২. ১০–১৪ দিন জিংক দিন।**\nজিংক ট্যাবলেট ডায়রিয়ার সময় কমায়, আর পরের কয়েক মাসে আবার হওয়া ঠেকাতে সাহায্য করে। মাত্রা স্বাস্থ্যকর্মী দেবেন বা বলে দেবেন; ট্যাবলেট একটু বুকের দুধ, স্যালাইন বা পরিষ্কার পানিতে গলে যায়। ডায়রিয়া থেমে গেলেও পুরো ১০–১৪ দিন খাওয়াতে থাকুন।\n\n**৩. খাওয়া চালিয়ে যান।**\nস্বাভাবিকের চেয়ে বেশিবার বুকের দুধ দিন। খিচুড়ি, আলু চটকানো, কলা বা ডিমের মতো নরম খাবার অল্প অল্প করে বারবার দিন। ডায়রিয়া সেরে গেলে প্রায় দুই সপ্তাহ দিনে একবার বাড়তি খাবার দিন।\n\n## যা দেবেন না\n- ডাক্তার না দিলে পায়খানা বন্ধের ওষুধ বা অ্যান্টিবায়োটিক; বেশিরভাগ ডায়রিয়ায় অ্যান্টিবায়োটিক লাগে না\n- কোমল পানীয়, প্যাকেটের জুস আর খুব মিষ্টি পানীয়, এতে ডায়রিয়া বাড়তে পারে\n- খাবার বা বুকের দুধ বন্ধ করবেন না\n\n## প্রতিরোধ\nসাবান দিয়ে হাত ধোয়া, নিরাপদ পানি, পরিষ্কার খাবার, ল্যাট্রিন ব্যবহার আর শিশুর পায়খানা নিরাপদে ফেলা ডায়রিয়া প্রতিরোধ করে। বুকের দুধ আর টিকাও সুরক্ষা দেয়।"}'::jsonb, '{"warning_signs":{"en":["Very sleepy, floppy or hard to wake","Unable to drink or breastfeed, or drinks very poorly","Sunken eyes","Pinched skin of the belly goes back very slowly","Blood in the stool","Vomiting everything","Diarrhoea for 14 days or more"],"bn":["খুব ঘুমকাতুরে, নেতিয়ে পড়া বা জাগানো কঠিন","পান করতে বা বুকের দুধ টানতে পারছে না, বা খুব কম পান করছে","চোখ বসে গেছে","পেটের চামড়া চিমটি দিয়ে ছাড়লে খুব ধীরে আগের অবস্থায় ফেরে","পায়খানায় রক্ত","যা খায় সব বমি করে","১৪ দিন বা তার বেশি ডায়রিয়া"]},"seek_help":{"en":["Any warning sign: go to hospital now, giving ORS on the way if the child can drink","Very thirsty, restless or irritable: see a health worker today","Fever with diarrhoea, or no improvement after 2–3 days"],"bn":["যেকোনো বিপদের লক্ষণ: এখনই হাসপাতালে যান, শিশু পান করতে পারলে পথে স্যালাইন দিতে থাকুন","খুব পিপাসা, অস্থির বা খিটখিটে: আজই স্বাস্থ্যকর্মীকে দেখান","ডায়রিয়ার সাথে জ্বর, বা ২–৩ দিনেও উন্নতি নেই"]}}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['diarrhoea', 'ors', 'orsaline', 'zinc', 'dehydration', 'loose motion']::text[], false, 'in_review'::lp_review_status, 4024),
  ('in-toilet-readiness', 'article', 'scientific', 'shared', 'educational', 'consensus', '🚽', '{"en":"Getting ready for toilet learning","bn":"টয়লেট শেখার প্রস্তুতি"}'::jsonb, '{"en":"Most children are ready to start toilet learning somewhere between 18 months and 3 years. Watch for the signs, prepare gently, and never punish.","bn":"বেশিরভাগ শিশু ১৮ মাস থেকে ৩ বছরের মধ্যে কোনো এক সময় টয়লেট শেখার জন্য প্রস্তুত হয়। লক্ষণ খেয়াল করুন, আলতো করে প্রস্তুতি নিন, কখনো শাস্তি নয়।"}'::jsonb, '{"en":"## Ready is not an age\nControlling the bladder and bowel depends on the body and brain maturing. Some children are ready before 2, many between 2 and 3. Starting before a child is ready usually takes longer and causes more stress, not less. In the months before 2, your job is to watch for signs and prepare.\n\n## Signs of readiness\n- Stays dry for about 2 hours at a time, or wakes dry from naps\n- Has bowel movements at fairly regular times\n- Shows by face, body or words that they are passing urine or stool\n- Pulls at a wet or dirty nappy, or asks to be changed\n- Can walk to the toilet area and sit down steadily\n- Follows simple instructions like “come here” and “sit down”\n- Is curious about how others use the toilet\n- Wants to do things by themselves\n\nYour child does not need all of these, but several together mean it is time to begin.\n\n## Preparing gently\n- Use simple, consistent words for urine and stool in your family\n- Let your child see family members of the same sex use the toilet, if you are comfortable\n- Choose a small potty, or a child seat and footrest for the toilet; for squat toilets, hold your child securely\n- Let your child sit on the potty in clothes first, just to get used to it\n- Read a picture book or tell a short story about using the toilet\n- Teach handwashing with soap after every toilet visit\n\n## Avoid pressure\nShaming, scolding, threatening or forcing a child to sit for long times makes toilet learning harder and can cause constipation. Accidents are part of learning. Clean up calmly and say: “Next time we will try the potty.”\n\n## Choose a calm time\nAvoid starting during a move, a new baby''s arrival, illness or a long journey. Agree on the same approach with everyone who cares for your child.\n\n## Cleaning\nMany Bangladeshi families clean with water after the toilet; teach this gently. For girls, clean from front to back. Always finish with handwashing.","bn":"## প্রস্তুতি মানে বয়স নয়\nপ্রস্রাব-পায়খানা নিয়ন্ত্রণ নির্ভর করে শরীর ও মস্তিষ্ক পরিণত হওয়ার ওপর। কেউ ২ বছরের আগেই প্রস্তুত হয়, অনেকে ২ থেকে ৩ বছরে। প্রস্তুত হওয়ার আগে শুরু করলে সাধারণত সময় বেশি লাগে, চাপও বাড়ে। ২ বছরের আগের মাসগুলোতে আপনার কাজ হলো লক্ষণ খেয়াল করা আর প্রস্তুতি নেওয়া।\n\n## প্রস্তুতির লক্ষণ\n- একটানা প্রায় ২ ঘণ্টা শুকনো থাকে, বা দিনের ঘুম থেকে শুকনো অবস্থায় ওঠে\n- মোটামুটি নির্দিষ্ট সময়ে পায়খানা হয়\n- মুখের ভাব, শরীর বা কথায় বোঝায় যে প্রস্রাব বা পায়খানা করছে\n- ভেজা বা নোংরা ন্যাপি টানে, বা বদলে দিতে বলে\n- নিজে হেঁটে টয়লেটের জায়গায় গিয়ে ঠিকভাবে বসতে পারে\n- “এখানে আসো”, “বসো” ধরনের সহজ কথা মানে\n- অন্যরা কীভাবে টয়লেট ব্যবহার করে, তা নিয়ে কৌতূহল দেখায়\n- সব নিজে নিজে করতে চায়\n\nসবগুলো লক্ষণ লাগবে না, তবে কয়েকটা একসাথে দেখলে বুঝবেন শুরু করার সময় হয়েছে।\n\n## আলতো প্রস্তুতি\n- প্রস্রাব ও পায়খানার জন্য পরিবারে সহজ, একই শব্দ ব্যবহার করুন\n- আপনি স্বচ্ছন্দ হলে শিশুকে একই লিঙ্গের পরিবারের সদস্যদের টয়লেট ব্যবহার দেখতে দিন\n- ছোট পটি, বা টয়লেটের জন্য শিশুর আসন ও পা রাখার টুল নিন; প্যান বা স্কোয়াট টয়লেটে শিশুকে শক্ত করে ধরে রাখুন\n- প্রথমে কাপড় পরা অবস্থাতেই পটিতে বসতে দিন, শুধু অভ্যস্ত হওয়ার জন্য\n- টয়লেট ব্যবহার নিয়ে ছবির বই পড়ুন বা ছোট একটা গল্প বলুন\n- প্রতিবার টয়লেটের পর সাবান দিয়ে হাত ধোয়া শেখান\n\n## চাপ দেবেন না\nলজ্জা দেওয়া, বকা, ভয় দেখানো বা জোর করে অনেকক্ষণ বসিয়ে রাখলে টয়লেট শেখা আরও কঠিন হয়, কোষ্ঠকাঠিন্যও হতে পারে। ভুল হওয়া শেখারই অংশ। শান্তভাবে পরিষ্কার করে বলুন: “পরের বার আমরা পটিতে চেষ্টা করব।”\n\n## শান্ত সময় বেছে নিন\nবাসা বদল, নতুন ভাই-বোনের জন্ম, অসুখ বা লম্বা ভ্রমণের সময় শুরু করবেন না। শিশুকে যাঁরা দেখেন, সবাই একই পদ্ধতিতে একমত হোন।\n\n## পরিষ্কার করা\nআমাদের বেশিরভাগ পরিবারে টয়লেটের পর পানি দিয়ে পরিষ্কার করা হয়; আলতো করে এটা শেখান। মেয়েশিশুকে সামনে থেকে পেছনের দিকে পরিষ্কার করুন। সবশেষে সবসময় হাত ধোয়া।"}'::jsonb, '{"seek_help":{"en":["Hard, painful stools or blood on the stool","Pain or crying when passing urine","Your child was dry for a long time and has started wetting again with other changes","You feel stuck or worried; a health worker can help"],"bn":["শক্ত, ব্যথাযুক্ত পায়খানা বা পায়খানায় রক্ত","প্রস্রাবের সময় ব্যথা বা কান্না","অনেক দিন শুকনো থাকার পর অন্য পরিবর্তনের সাথে আবার ভেজাতে শুরু করেছে","আটকে গেছেন বা দুশ্চিন্তা হচ্ছে; স্বাস্থ্যকর্মী সাহায্য করতে পারেন"]}}'::jsonb, 4, 548, 730, '{}'::text[], 'any', ARRAY['toilet training', 'potty', 'readiness', 'nappy', 'hygiene']::text[], false, 'in_review'::lp_review_status, 4025),
  ('in-father-and-toddler', 'article', 'scientific', 'father', 'educational', 'consensus', '👨‍👧', '{"en":"Dad and the toddler: your part matters","bn":"বাবা আর ছোট্ট সোনামণি: আপনার ভূমিকা গুরুত্বপূর্ণ"}'::jsonb, '{"en":"Fathers are not helpers; they are parents. Practical daily roles for dads from 6 to 24 months, even when work keeps you away.","bn":"বাবা সাহায্যকারী নন, তিনিও মা-বাবারই একজন। ৬ থেকে ২৪ মাসে বাবার জন্য প্রতিদিনের বাস্তব কিছু দায়িত্ব, কাজের জন্য দূরে থাকলেও।"}'::jsonb, '{"en":"## Why your part matters\nWHO''s nurturing care framework says children thrive when all caregivers, fathers included, provide health, nutrition, safety, responsive care and early learning. Children who spend time with an involved father benefit, and mothers who are supported cope better. What counts is not money alone, but time and attention.\n\n## Daily roles you can own\n- **One meal a day:** feed your child patiently, without a phone, talking about the food\n- **Bath time or toothbrushing:** a fun routine your child links with you\n- **Bedtime:** a song, a dua or a picture book, every night you are home\n- **Play:** ten minutes of floor play after work, rolling a ball, building with cups, chasing games\n- **Walks:** carry your child outside and name what you see: cow, rickshaw, mango tree, moon\n- **Health visits:** take your child for vaccines and check-ups, and keep the card safe\n- **Safety rounds:** cover water containers, block stairs and the roof, fix shelves and the TV to the wall, store kerosene and medicines high\n\n## Support the mother\nThe mother may still be breastfeeding at night and doing most of the housework. Take turns with night waking, cook or buy food, take the child out so she can rest, and stand with her if relatives criticise how she feeds or raises the child. Ask her how she is, and listen.\n\n## Gentle and safe\nToddlers test limits. Stay calm; speak in a low voice, get down to their level, and redirect. Never hit, shake or throw a baby in the air roughly. Shaking can cause serious brain injury.\n\n## When work keeps you away\nMany Bangladeshi fathers work long hours, in another city or abroad. You can still be close:\n- A short video call at the same time each day; sing the same song, show the same toy\n- Send voice notes of you reading a story or saying goodnight\n- When you are home, take over a full day of care, not just treats\n- Ask for photos and short videos of new skills, and talk about them with your child\n\n## You learn by doing\nNo one is born knowing how to change a nappy or calm a crying toddler. The more you do it, the more confident you become, and your child will learn that you are a safe place too.","bn":"## আপনার ভূমিকা কেন জরুরি\nবিশ্ব স্বাস্থ্য সংস্থার লালন-যত্ন (nurturing care) কাঠামো বলে, বাবাসহ সব যত্নকারী যখন স্বাস্থ্য, পুষ্টি, নিরাপত্তা, সাড়া দেওয়া যত্ন আর শৈশবের শেখার সুযোগ দেন, তখন শিশু সবচেয়ে ভালোভাবে বেড়ে ওঠে। যে বাবা সময় দেন, তাঁর সন্তান উপকৃত হয়, আর সহায়তা পেলে মা-ও ভালোভাবে সামলাতে পারেন। শুধু টাকা নয়, সময় আর মনোযোগই আসল।\n\n## প্রতিদিন যে দায়িত্বগুলো নিতে পারেন\n- **দিনে এক বেলার খাবার:** ফোন ছাড়া, খাবার নিয়ে গল্প করতে করতে ধৈর্য ধরে খাওয়ান\n- **গোসল বা দাঁত ব্রাশ:** মজার একটা রুটিন, যা শিশু আপনার সাথে মিলিয়ে মনে রাখবে\n- **ঘুমের সময়:** যে রাতে বাড়িতে আছেন, প্রতি রাতে একটা গান, দোয়া বা ছবির বই\n- **খেলা:** কাজ থেকে ফিরে দশ মিনিট মেঝেতে খেলা: বল গড়ানো, কাপ সাজানো, ধরাধরি\n- **হাঁটা:** শিশুকে কোলে নিয়ে বাইরে যান, যা দেখছেন তার নাম বলুন: গরু, রিকশা, আমগাছ, চাঁদ\n- **স্বাস্থ্যসেবা:** টিকা ও চেকআপে শিশুকে নিয়ে যান, কার্ড যত্নে রাখুন\n- **নিরাপত্তা টহল:** পানির পাত্র ঢাকুন, সিঁড়ি ও ছাদ আটকান, তাক ও টিভি দেয়ালে আটকান, কেরোসিন ও ওষুধ উঁচুতে রাখুন\n\n## মায়ের পাশে থাকুন\nমা হয়তো এখনো রাতে বুকের দুধ খাওয়াচ্ছেন আর ঘরের বেশিরভাগ কাজ করছেন। রাতে পালা করে উঠুন, রান্না করুন বা খাবার কিনে আনুন, শিশুকে নিয়ে বাইরে যান যাতে তিনি বিশ্রাম পান। আত্মীয়রা তাঁর খাওয়ানো বা সন্তান পালন নিয়ে সমালোচনা করলে তাঁর পাশে দাঁড়ান। তিনি কেমন আছেন জিজ্ঞেস করুন, মন দিয়ে শুনুন।\n\n## কোমল ও নিরাপদ\nছোট শিশু সীমা পরখ করে দেখে। শান্ত থাকুন; নিচু গলায় কথা বলুন, ওর উচ্চতায় নেমে আসুন, মনোযোগ অন্যদিকে ঘোরান। কখনো মারবেন না, ঝাঁকাবেন না, শিশুকে জোরে শূন্যে ছুড়বেন না। ঝাঁকুনিতে মস্তিষ্কে মারাত্মক আঘাত লাগতে পারে।\n\n## কাজের জন্য দূরে থাকলে\nআমাদের দেশের অনেক বাবা লম্বা সময় কাজ করেন, অন্য শহরে বা বিদেশে থাকেন। তবুও কাছে থাকা যায়:\n- প্রতিদিন একই সময়ে ছোট একটা ভিডিও কল; একই গান গান, একই খেলনা দেখান\n- গল্প পড়ে বা শুভরাত্রি বলে ভয়েস মেসেজ পাঠান\n- বাড়িতে এলে শুধু উপহার নয়, পুরো একটা দিন যত্নের দায়িত্ব নিন\n- নতুন দক্ষতার ছবি ও ছোট ভিডিও চেয়ে নিন, সেগুলো নিয়ে শিশুর সাথে কথা বলুন\n\n## করতে করতেই শেখা\nন্যাপি বদলানো বা কাঁদতে থাকা শিশুকে শান্ত করা কেউ জন্ম থেকে জানে না। যত করবেন, তত আত্মবিশ্বাস বাড়বে, আর শিশুও শিখবে যে আপনিও তার নিরাপদ আশ্রয়।"}'::jsonb, '{}'::jsonb, 4, 183, 730, '{}'::text[], 'any', ARRAY['father', 'dad', 'fatherhood', 'bonding', 'play', 'migrant worker', 'shared care']::text[], false, 'in_review'::lp_review_status, 4026),
  ('in-checklist-baby-proofing', 'checklist', 'scientific', 'family', 'important', 'guideline', '✅', '{"en":"Baby-proofing checklist","bn":"ঘর নিরাপদ করার চেকলিস্ট"}'::jsonb, '{"en":"Go round your home at your child''s height and tick off each item. Repeat every few months as your child learns to reach and climb higher.","bn":"শিশুর উচ্চতায় ঘর ঘুরে দেখুন আর একটা একটা করে টিক দিন। শিশু যত উঁচুতে নাগাল পায় ও চড়তে শেখে, কয়েক মাস পরপর আবার দেখুন।"}'::jsonb, '{"en":"Do this together as parents, and walk through it with grandparents and helpers too. Start with water, fire and poisons; these cause the most serious injuries.","bn":"মা-বাবা দুজনে মিলে করুন, দাদা-দাদি ও সহকারীদের সাথেও একবার ঘুরে দেখুন। পানি, আগুন আর বিষ দিয়ে শুরু করুন; এগুলোতেই সবচেয়ে গুরুতর দুর্ঘটনা ঘটে।"}'::jsonb, '{"items":{"en":["All buckets, drums and water tanks covered or emptied and turned over","Pond, ditch or well near the house fenced or the path blocked","Bathroom door kept closed","Stairs and roof door blocked; windows locked or barred","Child never left alone on a bed or chouki","Cooking area out of the child''s reach; pot handles turned inward","Matches, lighters and mosquito coils stored high","Kerosene, pesticides, rat poison and cleaners locked away, never in drink bottles","All medicines, including iron tablets, stored high and closed","Floor swept for coins, buttons, seeds and small toys","Button batteries and magnets out of reach","Boti, knives and blades stored high","Unused sockets covered and loose wires fixed","Shelves, almirah and TV fixed to the wall","Plastic bags and long cords put away","999 and the nearest hospital number saved in every adult''s phone"],"bn":["সব বালতি, ড্রাম ও পানির ট্যাংক ঢাকা, বা খালি করে উল্টে রাখা","বাড়ির কাছের পুকুর, ডোবা বা কুয়ায় বেড়া, বা যাওয়ার পথ আটকানো","বাথরুমের দরজা বন্ধ রাখা হয়","সিঁড়ি ও ছাদের দরজা আটকানো; জানালা বন্ধ বা গ্রিল দেওয়া","খাট বা চৌকিতে শিশুকে কখনো একা রাখা হয় না","রান্নার জায়গা শিশুর নাগালের বাইরে; হাঁড়ির হাতল ভেতরের দিকে","দেশলাই, লাইটার ও মশার কয়েল উঁচুতে রাখা","কেরোসিন, কীটনাশক, ইঁদুরের বিষ ও পরিষ্কারের তরল তালাবদ্ধ, কখনো পানীয়ের বোতলে নয়","আয়রন ট্যাবলেটসহ সব ওষুধ উঁচুতে, বন্ধ করে রাখা","মেঝে ঝাড়ু দিয়ে কয়েন, বোতাম, বিচি ও ছোট খেলনা সরানো","বোতাম ব্যাটারি ও চুম্বক নাগালের বাইরে","বঁটি, ছুরি ও ব্লেড উঁচুতে রাখা","অব্যবহৃত সকেট ঢাকা, ঢিলে তার ঠিক করা","তাক, আলমারি ও টিভি দেয়ালে আটকানো","প্লাস্টিকের ব্যাগ ও লম্বা দড়ি তুলে রাখা","প্রত্যেক বড় মানুষের ফোনে ৯৯৯ ও কাছের হাসপাতালের নম্বর সেভ করা"]}}'::jsonb, 2, 183, 730, '{}'::text[], 'any', ARRAY['baby proofing', 'checklist', 'home safety', 'drowning', 'burns', 'poisoning']::text[], false, 'in_review'::lp_review_status, 4027),
  ('in-checklist-daily-food-groups', 'checklist', 'scientific', 'shared', 'routine', 'guideline', '🥗', '{"en":"Daily food groups checklist: 6–23 months","bn":"প্রতিদিনের খাদ্যদল চেকলিস্ট: ৬–২৩ মাস"}'::jsonb, '{"en":"Tick the food groups your child ate today. Aim for at least 5 of the 8 groups, with an animal food every day.","bn":"আজ শিশু কোন কোন খাদ্যদল খেয়েছে, টিক দিন। ৮টির মধ্যে অন্তত ৫টি দল, আর প্রতিদিন একটি প্রাণিজ খাবারের লক্ষ্য রাখুন।"}'::jsonb, '{"en":"Health programmes use these eight groups to check whether a young child''s diet is varied enough. Count a group if your child ate at least a spoonful of it today. Five or more is a good day. The last items are habits to check too.","bn":"ছোট শিশুর খাবারে যথেষ্ট বৈচিত্র্য আছে কিনা দেখতে পুষ্টি কর্মসূচিতে এই আটটি দল ব্যবহার করা হয়। আজ কোনো দলের অন্তত এক চামচ খেয়ে থাকলে সেটা গুনুন। পাঁচ বা বেশি হলে দিনটা ভালো। শেষের কয়েকটি অভ্যাসও মিলিয়ে নিন।"}'::jsonb, '{"items":{"en":["Breast milk","Grains, roots and tubers: rice, roti, suji, potato","Pulses, nuts and seeds: lentils, beans, ground nuts or seeds","Dairy: milk, yoghurt, cheese","Flesh foods: fish, chicken, meat, liver","Eggs","Vitamin A-rich fruits and vegetables: ripe mango, papaya, pumpkin, carrot, dark green leafy vegetables","Other fruits and vegetables: banana, guava, bottle gourd, tomato and others","A little oil added to at least one meal","Meals and snacks given as often as needed for age","Food thick enough to stay on the spoon","No sugary drinks, chips or packaged snacks today"],"bn":["বুকের দুধ","শস্য, শিকড় ও কন্দ: ভাত, রুটি, সুজি, আলু","ডাল, বাদাম ও বীজ: মসুর ডাল, শিম জাতীয় দানা, গুঁড়া বাদাম বা বীজ","দুধজাত: দুধ, দই, পনির","মাছ-মাংস: মাছ, মুরগি, মাংস, কলিজা","ডিম","ভিটামিন এ সমৃদ্ধ ফল ও সবজি: পাকা আম, পেঁপে, মিষ্টিকুমড়া, গাজর, গাঢ় সবুজ শাক","অন্যান্য ফল ও সবজি: কলা, পেয়ারা, লাউ, টমেটো ইত্যাদি","অন্তত এক বেলার খাবারে একটু তেল","বয়স অনুযায়ী যতবার দরকার, ততবার খাবার ও নাশতা","খাবার এমন ঘন যে চামচে আটকে থাকে","আজ কোনো মিষ্টি পানীয়, চিপস বা প্যাকেটের নাশতা নয়"]}}'::jsonb, 2, 183, 730, '{}'::text[], 'any', ARRAY['food groups', 'dietary diversity', 'checklist', 'daily feeding', 'meal plan']::text[], false, 'in_review'::lp_review_status, 4028),
  ('in-activity-stacking-pouring', 'activity', 'scientific', 'shared', 'routine', 'consensus', '🥤', '{"en":"Stacking cups and pouring","bn":"কাপ সাজানো আর ঢালাঢালি"}'::jsonb, '{"en":"Plastic cups, steel bowls and a little rice or water: a simple game that builds hand control, size sense and patience.","bn":"প্লাস্টিকের কাপ, স্টিলের বাটি আর একটু চাল বা পানি: সহজ একটা খেলা, যা হাতের নিয়ন্ত্রণ, ছোট-বড় বোঝা আর ধৈর্য গড়ে তোলে।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Stacking, nesting and pouring teach how sizes fit together, cause and effect, and careful use of the hands and eyes together. Knocking a tower down is part of the fun and the learning.","bn":"সাজানো, একটার ভেতর আরেকটা রাখা আর ঢালা শেখায় কোন আকার কোথায় মেলে, কারণ ও ফল, আর চোখ-হাত একসাথে সাবধানে ব্যবহার করা। টাওয়ার ভেঙে ফেলাও খেলা আর শেখার অংশ।"},"items":{"en":["3–6 plastic cups or steel bowls of different sizes","A tray, mat or old sheet","A little dry rice or lentils, or a shallow bowl of water","A spoon"],"bn":["বিভিন্ন মাপের ৩–৬টি প্লাস্টিকের কাপ বা স্টিলের বাটি","একটা ট্রে, মাদুর বা পুরোনো চাদর","একটু শুকনো চাল বা ডাল, অথবা অগভীর বাটিতে পানি","একটা চামচ"]},"steps":{"en":["Sit on the floor facing your child with the cups on the mat","Stack two cups and say “up, up!”, then let your child knock them down","Show how a small cup goes inside a big one, and let them try","From about 12 months, put a little rice in one cup and pour it into another; name it: “pour, full, empty”","Let your child scoop with the spoon and pour, even if it spills","With water, use only a shallow amount and stay right beside your child the whole time","Finish by putting the cups away together"],"bn":["মাদুরে কাপগুলো রেখে শিশুর মুখোমুখি মেঝেতে বসুন","দুটো কাপ একটার ওপর আরেকটা রেখে বলুন “ওপরে, ওপরে!”, তারপর শিশুকে ফেলে দিতে দিন","ছোট কাপ কীভাবে বড় কাপের ভেতর ঢোকে দেখান, ওকে চেষ্টা করতে দিন","প্রায় ১২ মাস থেকে এক কাপে একটু চাল নিয়ে আরেক কাপে ঢালুন; নাম বলুন: “ঢালো, ভরা, খালি”","শিশুকে চামচে তুলে ঢালতে দিন, পড়ে গেলেও","পানি নিলে খুব অল্প নিন, আর পুরো সময় শিশুর ঠিক পাশে থাকুন","শেষে একসাথে কাপগুলো গুছিয়ে রাখুন"]},"avoid":{"en":["Leaving a child alone with water, even a shallow bowl","Letting a baby under 1 year play with loose rice or lentils without close watching","Glass or cracked containers"],"bn":["অগভীর বাটি হলেও পানির সাথে শিশুকে একা রাখা","১ বছরের কম শিশুকে কাছ থেকে না দেখে খোলা চাল বা ডাল নিয়ে খেলতে দেওয়া","কাচের বা ফাটা পাত্র"]}}'::jsonb, 2, 274, 730, '{}'::text[], 'any', ARRAY['stacking', 'pouring', 'fine motor', 'cups', 'water play', 'activity']::text[], false, 'in_review'::lp_review_status, 4029),
  ('in-activity-peekaboo', 'activity', 'scientific', 'shared', 'routine', 'consensus', '🙈', '{"en":"Peek-a-boo and hide-and-find","bn":"কু-কু খেলা আর লুকিয়ে খোঁজা"}'::jsonb, '{"en":"Hiding your face or a toy and bringing it back teaches your baby that people and things still exist when out of sight.","bn":"মুখ বা খেলনা লুকিয়ে আবার বের করলে শিশু শেখে যে চোখের আড়াল হলেও মানুষ আর জিনিস হারিয়ে যায় না।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Between 6 and 12 months babies learn that things still exist when hidden. Practising this in a happy game also helps with the fear of a parent leaving: you go, and you always come back.","bn":"৬ থেকে ১২ মাসে শিশু শেখে যে লুকানো জিনিসও থেকে যায়। আনন্দের খেলায় এটা অভ্যাস করলে মা-বাবা চলে যাওয়ার ভয়ও কমে: আপনি যান, আবার ফিরেও আসেন।"},"items":{"en":["A light cloth or orna","A favourite small toy (too big to swallow)","A cushion or a cardboard box"],"bn":["একটা হালকা কাপড় বা ওড়না","প্রিয় একটা ছোট খেলনা (গিলে ফেলার মতো ছোট নয়)","একটা কুশন বা কার্ডবোর্ডের বাক্স"]},"steps":{"en":["Cover your face with your hands or the cloth and say “Where is Ammu?”","Uncover with a smile: “Ku-ku! Here I am!”","Put the cloth lightly over your baby''s head for a second and let them pull it off","Hide a toy under the cloth while your baby watches, and ask “Where did it go?”","As your baby gets better, hide the toy behind a cushion or in a box","From about 12 months, hide yourself behind a door or curtain and call your child''s name so they can find you","Stop when your baby looks tired or upset"],"bn":["হাত বা কাপড় দিয়ে মুখ ঢেকে বলুন “আম্মু কোথায়?”","হেসে মুখ খুলুন: “কু-কু! এই তো আমি!”","এক সেকেন্ডের জন্য শিশুর মাথায় হালকা করে কাপড় রাখুন, ওকে টেনে সরাতে দিন","শিশু দেখছে এমন অবস্থায় কাপড়ের নিচে খেলনা লুকান, জিজ্ঞেস করুন “কোথায় গেল?”","শিশু পারদর্শী হলে কুশনের পেছনে বা বাক্সে লুকান","প্রায় ১২ মাস থেকে দরজা বা পর্দার আড়ালে নিজে লুকিয়ে শিশুর নাম ধরে ডাকুন, যাতে আপনাকে খুঁজে পায়","শিশু ক্লান্ত বা বিরক্ত হলে থামুন"]},"avoid":{"en":["Leaving a cloth over a baby''s face","Hiding where your child cannot hear you, which can frighten them","Using small objects that fit in the mouth"],"bn":["শিশুর মুখের ওপর কাপড় রেখে দেওয়া","এমন জায়গায় লুকানো যেখান থেকে শিশু আপনার গলা শুনতে পায় না, এতে ভয় পেতে পারে","মুখে ঢুকে যায় এমন ছোট জিনিস ব্যবহার"]}}'::jsonb, 2, 183, 548, '{}'::text[], 'any', ARRAY['peek-a-boo', 'hide and find', 'object permanence', 'separation', 'activity']::text[], false, 'in_review'::lp_review_status, 4030),
  ('in-activity-picture-books', 'activity', 'scientific', 'shared', 'routine', 'consensus', '📖', '{"en":"Reading picture books together","bn":"একসাথে ছবির বই পড়া"}'::jsonb, '{"en":"You do not need to read every word. Point, name, make sounds and let your child turn the pages.","bn":"প্রতিটি শব্দ পড়ার দরকার নেই। আঙুল দিয়ে দেখান, নাম বলুন, আওয়াজ করুন, আর শিশুকে পাতা ওল্টাতে দিন।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Looking at books together builds vocabulary, attention and closeness. A few minutes every day, especially at bedtime, becomes a calm habit your child looks forward to.","bn":"একসাথে বই দেখলে শব্দভান্ডার, মনোযোগ আর ঘনিষ্ঠতা বাড়ে। প্রতিদিন কয়েক মিনিট, বিশেষ করে ঘুমের আগে, এমন এক শান্ত অভ্যাস হয়ে যায় যার জন্য শিশু অপেক্ষা করে।"},"items":{"en":["A picture book with big, clear pictures: cardboard or cloth books last longer","Or an old calendar, a magazine, or family photos","A quiet corner and your lap"],"bn":["বড় ও স্পষ্ট ছবির একটা বই: শক্ত বোর্ড বা কাপড়ের বই বেশি দিন টেকে","অথবা পুরোনো ক্যালেন্ডার, পত্রিকা বা পরিবারের ছবি","একটা শান্ত কোণ আর আপনার কোল"]},"steps":{"en":["Sit your child on your lap so you both see the page","Point and name: “Look, a cat! Meow!”","Wait and let your child look, point or babble before you turn the page","Answer what they point at, even if it is not the main picture","Let your child hold the book, turn pages and chew a cloth book","From about 18 months, ask “Where is the cow?” and let them point","Read the same favourite book again and again; repetition helps learning","Keep it short and happy: stop while your child still enjoys it"],"bn":["শিশুকে কোলে বসান, যাতে দুজনেই পাতা দেখতে পান","আঙুল দিয়ে দেখিয়ে নাম বলুন: “দেখো, বিড়াল! মিউ!”","পাতা ওল্টানোর আগে অপেক্ষা করুন, শিশুকে দেখতে, আঙুল তুলতে বা আধো বুলি বলতে দিন","সে যেদিকে আঙুল তোলে, তার উত্তর দিন, মূল ছবি না হলেও","শিশুকে বই ধরতে, পাতা ওল্টাতে, কাপড়ের বই কামড়াতেও দিন","প্রায় ১৮ মাস থেকে জিজ্ঞেস করুন “গরু কোথায়?”, ওকে দেখাতে দিন","প্রিয় বইটা বারবার পড়ুন; বারবার পড়লে শেখা পোক্ত হয়","ছোট আর আনন্দময় রাখুন: শিশুর ভালো লাগা থাকতেই থামুন"]},"avoid":{"en":["Forcing a child to sit still until the book ends","Replacing books with videos on a phone"],"bn":["বই শেষ না হওয়া পর্যন্ত জোর করে বসিয়ে রাখা","বইয়ের বদলে ফোনে ভিডিও দেখানো"]}}'::jsonb, 2, 183, 730, '{}'::text[], 'any', ARRAY['reading', 'picture books', 'language', 'bedtime', 'activity', 'books']::text[], false, 'in_review'::lp_review_status, 4031),
  ('in-activity-music-movement', 'activity', 'scientific', 'shared', 'routine', 'consensus', '🎵', '{"en":"Music, rhymes and movement","bn":"গান, ছড়া আর নাচ"}'::jsonb, '{"en":"Sing, clap, bounce and dance together. Rhymes with actions build language, rhythm and strong bodies.","bn":"একসাথে গান গান, হাততালি দিন, দোলান, নাচুন। হাত-পা নেড়ে ছড়া ভাষা, তাল আর শক্ত শরীর গড়ে তোলে।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Rhythm and repetition help children hear the sounds of words. Moving to music builds balance and strength, and counts towards the active time WHO advises every day.","bn":"তাল আর বারবার বলা শিশুকে শব্দের ধ্বনি শুনতে সাহায্য করে। গানের সাথে নড়াচড়ায় ভারসাম্য ও শক্তি বাড়ে, আর এটা বিশ্ব স্বাস্থ্য সংস্থার বলা প্রতিদিনের সক্রিয় সময়েরও অংশ।"},"items":{"en":["Your voice: any song or rhyme you know","A steel plate and spoon, or a small homemade shaker with the lid glued shut","Space on the floor to move"],"bn":["আপনার কণ্ঠ: জানা যেকোনো গান বা ছড়া","স্টিলের থালা ও চামচ, বা ঢাকনা আঠা দিয়ে আটকানো ঘরে বানানো ঝুনঝুনি","নড়াচড়ার জন্য মেঝেতে একটু জায়গা"]},"steps":{"en":["Sing a rhyme your family knows, like “Ay ay chand mama” or “Hattima tim tim”, slowly and with a smile","Add actions: clap, wave, touch nose and toes","For babies: hold them securely and sway or bounce gently to the beat","For toddlers: dance together, stop when the music stops, start again","Let your child bang the plate or shake the shaker in time","Pause before the last word of a familiar line and let your child fill it in","Repeat favourites every day"],"bn":["পরিবারের চেনা কোনো ছড়া, যেমন “আয় আয় চাঁদমামা” বা “হাট্টিমা টিম টিম”, ধীরে, হাসিমুখে গান","হাত-পা নাড়া যোগ করুন: হাততালি, হাত নাড়া, নাক আর পায়ের আঙুল ছোঁয়া","ছোট শিশুকে শক্ত করে ধরে তালে তালে আলতো দোলান","একটু বড় শিশুর সাথে নাচুন, গান থামলে থামুন, আবার শুরু করুন","শিশুকে তালে তালে থালা বাজাতে বা ঝুনঝুনি ঝাঁকাতে দিন","চেনা লাইনের শেষ শব্দের আগে থেমে শিশুকে শেষ করতে দিন","প্রিয় গানগুলো প্রতিদিন আবার করুন"]},"avoid":{"en":["Shaking a baby or throwing them high in the air","Very loud music close to the ears","Replacing singing together with songs on a screen"],"bn":["শিশুকে ঝাঁকানো বা শূন্যে উঁচুতে ছুড়ে দেওয়া","কানের কাছে খুব জোরে গান","একসাথে গান গাওয়ার বদলে স্ক্রিনে গান চালানো"]}}'::jsonb, 2, 183, 730, '{}'::text[], 'any', ARRAY['music', 'rhymes', 'dancing', 'movement', 'songs', 'activity']::text[], false, 'in_review'::lp_review_status, 4032),
  ('in-sc-refuses-food', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🙅', '{"en":"My child refuses food or eats very little","bn":"শিশু খেতে চায় না বা খুব কম খায়"}'::jsonb, '{"en":"Small appetites are common and often normal. Check growth, keep meals calm, and never force.","bn":"কম খিদে খুব সাধারণ, প্রায়ই স্বাভাবিক। বৃদ্ধি দেখে নিন, খাওয়ার সময় শান্ত রাখুন, কখনো জোর নয়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Many parents in Bangladesh worry that their child “eats nothing”. Often the child eats less than the adults expect but is growing well. Sometimes, though, poor appetite comes from illness, anaemia, too much milk or snacks, or stressful meals.","bn":"আমাদের দেশে অনেক মা-বাবার চিন্তা, শিশু “কিছুই খায় না”। প্রায়ই দেখা যায় বড়রা যতটা আশা করেন শিশু তার চেয়ে কম খায়, কিন্তু ঠিকমতোই বাড়ছে। তবে কখনো কখনো কম খিদের পেছনে থাকে অসুখ, রক্তস্বল্পতা, বেশি দুধ বা নাশতা, কিংবা চাপের খাওয়ার সময়।"},"why":{"en":"A young child''s stomach is about the size of their fist. Appetite drops after the first year as growth slows, and during teething or illness. Children also refuse food to show independence, or when meals have become a fight.","bn":"ছোট শিশুর পেট মোটামুটি তার মুঠির সমান। প্রথম বছরের পর বৃদ্ধির গতি কমলে খিদেও কমে, দাঁত ওঠা বা অসুখের সময়ও কমে। আবার নিজের ইচ্ছা বোঝাতে, বা খাওয়া যদি লড়াই হয়ে যায়, তখনও শিশু খেতে চায় না।"},"normal":{"en":"Eating a lot one day and little the next, refusing new foods many times before accepting them, and eating better from their own fingers than from a spoon are all normal.","bn":"এক দিন বেশি খাওয়া, পরের দিন কম; নতুন খাবার অনেকবার ফিরিয়ে দিয়ে তারপর মেনে নেওয়া; চামচের চেয়ে নিজের আঙুলে বেশি খাওয়া, এ সবই স্বাভাবিক।"},"do_now":{"en":["Look at the growth card: is weight going up over the months?","Check for illness: fever, cough, diarrhoea, mouth sores","Count snacks, biscuits, juice and milk between meals"],"bn":["বৃদ্ধি কার্ড দেখুন: মাসে মাসে ওজন বাড়ছে কি?","অসুখ আছে কিনা দেখুন: জ্বর, কাশি, ডায়রিয়া, মুখে ঘা","দুই বেলার মাঝে নাশতা, বিস্কুট, জুস আর দুধ কতটা খাচ্ছে, গুনে দেখুন"]},"steps":{"en":["Offer meals and snacks at regular times, with about 2–3 hours between them","Give small portions; offer more if your child wants it","Make food thick and energy-rich: add oil, egg, lentils or fish","Let your child touch the food and feed themselves","Sit together, talk and eat the same food yourself","Offer a refused food again on other days alongside a liked food","End the meal calmly after 20–30 minutes, and wait for the next one"],"bn":["নির্দিষ্ট সময়ে খাবার ও নাশতা দিন, মাঝে প্রায় ২–৩ ঘণ্টা ফাঁক রেখে","অল্প করে দিন; শিশু চাইলে আরও দিন","খাবার ঘন ও শক্তিপূর্ণ করুন: তেল, ডিম, ডাল বা মাছ যোগ করুন","খাবার ছুঁতে আর নিজে খেতে দিন","একসাথে বসুন, গল্প করুন, নিজেও একই খাবার খান","যে খাবার ফিরিয়ে দিয়েছে, অন্য দিন পছন্দের খাবারের পাশে আবার দিন","২০–৩০ মিনিট পর শান্তভাবে খাওয়া শেষ করুন, পরের বেলার জন্য অপেক্ষা করুন"]},"avoid":{"en":["Force-feeding, holding the nose or feeding a crying child","Filling the gaps with biscuits, chips or sweet drinks","Feeding with a phone or TV on","Comparing your child with other children in front of them"],"bn":["জোর করে, নাক টিপে বা কান্নার মধ্যে খাওয়ানো","ফাঁকে ফাঁকে বিস্কুট, চিপস বা মিষ্টি পানীয় দিয়ে পেট ভরানো","ফোন বা টিভি চালিয়ে খাওয়ানো","শিশুর সামনে অন্য শিশুর সাথে তুলনা করা"]},"example":{"en":"Rina''s 14-month-old son pushed away every spoon of rice. She stopped the biscuits between meals, gave him soft pieces of egg and potato to pick up himself, and sat with him while she ate. Within two weeks he was eating small but steady meals, and his weight on the card kept rising.","bn":"রিনার ১৪ মাসের ছেলে ভাতের প্রতিটি চামচ ঠেলে দিত। রিনা দুই বেলার মাঝে বিস্কুট বন্ধ করলেন, ডিম আর আলুর নরম টুকরো দিলেন নিজে তুলে খাওয়ার জন্য, আর নিজে খেতে খেতে ছেলের পাশে বসলেন। দুই সপ্তাহের মধ্যে ছেলে অল্প কিন্তু নিয়মিত খেতে শুরু করল, কার্ডে ওজনও বাড়তে থাকল।"},"warning_signs":{"en":["Weight not increasing, or falling, on the growth card","Pale, very tired or often ill","Refuses all food and drink, or vomits everything","Swelling of both feet"],"bn":["বৃদ্ধি কার্ডে ওজন বাড়ছে না বা কমছে","ফ্যাকাশে, খুব ক্লান্ত বা প্রায়ই অসুস্থ","সব খাবার ও পানীয় ফিরিয়ে দেয়, বা সব বমি করে","দুই পা ফুলে যাওয়া"]},"seek_help":{"en":["Any warning sign: see a health worker or doctor soon","Poor appetite lasting more than a week with illness","You are worried, or meals have become very stressful: ask at the community clinic for feeding counselling"],"bn":["যেকোনো বিপদের লক্ষণ: তাড়াতাড়ি স্বাস্থ্যকর্মী বা ডাক্তার দেখান","অসুখের সাথে এক সপ্তাহের বেশি খিদে কম","আপনি চিন্তিত, বা খাওয়ার সময়টা খুব চাপের হয়ে গেছে: কমিউনিটি ক্লিনিকে খাওয়ানোর পরামর্শ চান"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['refuses food', 'poor appetite', 'picky eater', 'eats little', 'feeding problems']::text[], false, 'in_review'::lp_review_status, 4033),
  ('in-sc-only-breast-milk', 'scenario', 'scientific', 'mother', 'important', 'guideline', '🤱', '{"en":"My baby only wants breast milk","bn":"শিশু শুধু বুকের দুধই খেতে চায়"}'::jsonb, '{"en":"Keep breastfeeding, and gently build up other foods by changing the timing, texture and who feeds.","bn":"বুকের দুধ চালিয়ে যান, আর সময়, ঘনত্ব আর কে খাওয়াচ্ছে তা বদলে আলতো করে অন্য খাবার বাড়ান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"After 6 months a baby needs other foods as well as breast milk. Some babies are slow to accept them and prefer the comfort of the breast, especially when they are tired, teething or unwell.","bn":"৬ মাসের পর বুকের দুধের পাশাপাশি অন্য খাবারও লাগে। কিছু শিশু নতুন খাবার ধীরে মেনে নেয় আর বুকের আরামটাই বেশি চায়, বিশেষ করে ক্লান্ত থাকলে, দাঁত উঠলে বা অসুস্থ হলে।"},"why":{"en":"Breast milk is familiar, comforting and always there. A baby who has just breastfed is not hungry for food. New tastes and textures take many tries, and the mother''s smell can make the baby ask for the breast when she offers food.","bn":"বুকের দুধ চেনা, আরামের, আর সবসময় হাতের কাছে। সদ্য বুকের দুধ খাওয়া শিশুর আর খাবারের খিদে থাকে না। নতুন স্বাদ ও ঘনত্বে অভ্যস্ত হতে অনেকবার চেষ্টা লাগে, আর মা খাবার দিতে এলে মায়ের গন্ধেই শিশু বুকের দুধ চাইতে পারে।"},"normal":{"en":"In the first weeks of first foods, eating only a few spoonfuls is normal. Most babies eat more over a month or two with regular, patient offers.","bn":"প্রথম খাবার শুরুর প্রথম কয়েক সপ্তাহে কয়েক চামচ খাওয়া স্বাভাবিক। নিয়মিত ও ধৈর্য ধরে দিলে এক-দুই মাসে বেশিরভাগ শিশু বেশি খেতে শুরু করে।"},"do_now":{"en":["Keep breastfeeding; do not stop it to force food","Offer food about an hour after a breastfeed, when the baby is awake and a little hungry","Check the growth card for weight gain"],"bn":["বুকের দুধ চালিয়ে যান; খাবার খাওয়াতে বুকের দুধ বন্ধ করবেন না","বুকের দুধের প্রায় এক ঘণ্টা পর, শিশু যখন জেগে আছে আর একটু খিদে আছে, তখন খাবার দিন","বৃদ্ধি কার্ডে ওজন বাড়ছে কিনা দেখুন"]},"steps":{"en":["Let the father, grandmother or another family member offer food sometimes","Try different textures: some babies prefer smoother food, others soft pieces they can hold","Mix a little expressed breast milk into the food for a familiar taste","Let your baby watch the family eat and sit at the meal","Offer small amounts at the same times each day","Praise and smile at every taste, however small","As food intake grows, offer food first at main meals and breastfeed after"],"bn":["মাঝে মাঝে বাবা, দাদি-নানি বা পরিবারের অন্য কাউকে খাবার দিতে দিন","ভিন্ন ঘনত্ব চেষ্টা করুন: কেউ মিহি খাবার পছন্দ করে, কেউ হাতে ধরার মতো নরম টুকরো","চেনা স্বাদের জন্য খাবারে একটু বুকের দুধ চেপে মিশিয়ে দিন","পরিবারের সবাই যখন খায়, শিশুকে পাশে বসিয়ে দেখতে দিন","প্রতিদিন একই সময়ে অল্প অল্প করে দিন","যত অল্পই চাখুক, হাসিমুখে প্রশংসা করুন","খাওয়া বাড়লে প্রধান বেলাগুলোতে আগে খাবার, পরে বুকের দুধ দিন"]},"avoid":{"en":["Stopping breastfeeding suddenly to make the baby eat","Applying bitter things on the breast to stop feeding","Force-feeding or feeding while the baby cries","Replacing meals with formula or cow''s milk in a bottle"],"bn":["খাবার খাওয়াতে হঠাৎ বুকের দুধ বন্ধ করা","বুকের দুধ ছাড়াতে স্তনে তেতো কিছু লাগানো","জোর করে বা কান্নার মধ্যে খাওয়ানো","খাবারের বদলে ফিডারে ফর্মুলা বা গরুর দুধ দেওয়া"]},"example":{"en":"At 8 months, Tania''s daughter cried for the breast every time Tania brought the bowl. Her husband started giving the evening khichuri while Tania was in another room. The baby ate a few spoons more each week, and by 10 months she was having three small meals a day and still breastfeeding happily.","bn":"৮ মাস বয়সে তানিয়া বাটি নিয়ে এলেই মেয়ে বুকের দুধের জন্য কাঁদত। তানিয়া অন্য ঘরে থাকার সময় তাঁর স্বামী সন্ধ্যার খিচুড়ি খাওয়ানো শুরু করলেন। প্রতি সপ্তাহে শিশু কয়েক চামচ করে বেশি খেল, আর ১০ মাসে দিনে তিন বেলা অল্প অল্প খাচ্ছিল, বুকের দুধও খুশিমনে চলছিল।"},"warning_signs":{"en":["Weight not increasing on the card","Pale, very tired or unusually floppy","Very few wet nappies, or very dark urine"],"bn":["কার্ডে ওজন বাড়ছে না","ফ্যাকাশে, খুব ক্লান্ত বা অস্বাভাবিক নেতানো","খুব কম ভেজা ন্যাপি, বা খুব গাঢ় প্রস্রাব"]},"seek_help":{"en":["Any warning sign: see a health worker soon","Your baby gags or chokes on all textures","Still taking almost no food by 9 months: ask for feeding counselling and a check for anaemia"],"bn":["যেকোনো বিপদের লক্ষণ: তাড়াতাড়ি স্বাস্থ্যকর্মী দেখান","যেকোনো ঘনত্বের খাবারেই ওয়াক ওঠে বা গলায় আটকায়","৯ মাসেও প্রায় কোনো খাবার খায় না: খাওয়ানোর পরামর্শ ও রক্তস্বল্পতা পরীক্ষার কথা বলুন"]}}'::jsonb, 3, 183, 548, '{}'::text[], 'any', ARRAY['only breast milk', 'refuses solids', 'breastfeeding', 'complementary feeding']::text[], false, 'in_review'::lp_review_status, 4034),
  ('in-sc-night-waking', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🌃', '{"en":"My child wakes many times at night","bn":"শিশু রাতে বারবার জেগে ওঠে"}'::jsonb, '{"en":"Night waking is common in the first two years. A steady routine and calm, boring night care usually help over a few weeks.","bn":"প্রথম দুই বছরে রাতে জেগে ওঠা খুব সাধারণ। নিয়মিত রুটিন আর রাতে শান্ত, একঘেয়ে যত্নে সাধারণত কয়েক সপ্তাহে উন্নতি হয়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"All children wake briefly between sleep cycles. Some go back to sleep alone; others call out because they need help to settle. Waking more than usual is often linked to a change: teething, illness, a new skill, a trip or fear of separation.","bn":"ঘুমের এক চক্র থেকে আরেক চক্রে যাওয়ার সময় সব শিশুই একটু জাগে। কেউ নিজে নিজে আবার ঘুমিয়ে পড়ে; কেউ ডাকে, কারণ ঘুমাতে তার সাহায্য লাগে। স্বাভাবিকের চেয়ে বেশি জাগা প্রায়ই কোনো পরিবর্তনের সাথে জড়িত: দাঁত ওঠা, অসুখ, নতুন দক্ষতা, বেড়াতে যাওয়া বা মা-বাবাকে ছেড়ে থাকার ভয়।"},"why":{"en":"A child who always falls asleep while feeding or being rocked may need the same thing to fall back asleep at night. Late naps, an irregular bedtime, screens before bed, a hot room or mosquitoes also break sleep.","bn":"যে শিশু সবসময় দুধ খেতে খেতে বা দোল খেতে খেতে ঘুমায়, রাতে আবার ঘুমাতেও তার একই জিনিস লাগতে পারে। দেরিতে দিনের ঘুম, অনিয়মিত ঘুমের সময়, ঘুমের আগে স্ক্রিন, গরম ঘর বা মশাও ঘুম ভাঙায়।"},"normal":{"en":"Waking once or twice a night, and breastfeeding at night, is common and normal up to 2 years. Phases of worse sleep often last a week or two.","bn":"রাতে এক-দুইবার জাগা আর রাতে বুকের দুধ খাওয়া ২ বছর পর্যন্ত খুব সাধারণ ও স্বাভাবিক। ঘুম খারাপ যাওয়ার পর্ব প্রায়ই এক-দুই সপ্তাহ থাকে।"},"do_now":{"en":["Check for fever, ear pain, a blocked nose, a wet nappy or mosquito bites","Make the room dark, quiet and not too hot","Keep night care calm: low light, few words, no phone"],"bn":["জ্বর, কানে ব্যথা, নাক বন্ধ, ভেজা ন্যাপি বা মশার কামড় আছে কিনা দেখুন","ঘর অন্ধকার, শান্ত আর কম গরম রাখুন","রাতের যত্ন শান্ত রাখুন: কম আলো, কম কথা, ফোন নয়"]},"steps":{"en":["Set a regular bedtime and wake time, and keep them even on holidays","Use the same short routine each night: wash, nappy, feed, brush teeth, song or dua, bed","Avoid naps late in the afternoon","Switch off screens an hour before bed","Sometimes put your child down drowsy but awake, so they learn to settle in bed","When they wake, wait a moment; then comfort with a hand on the back and soft words before picking up","Take turns between parents so each gets some unbroken sleep"],"bn":["নিয়মিত ঘুমানো ও ওঠার সময় ঠিক করুন, ছুটির দিনেও তা মেনে চলুন","প্রতি রাতে একই ছোট রুটিন: হাত-মুখ ধোয়া, ন্যাপি, খাওয়ানো, দাঁত ব্রাশ, গান বা দোয়া, বিছানা","বিকেলের শেষে দিনের ঘুম এড়িয়ে চলুন","ঘুমের এক ঘণ্টা আগে স্ক্রিন বন্ধ করুন","মাঝে মাঝে ঘুম ঘুম কিন্তু জেগে থাকা অবস্থায় শুইয়ে দিন, যাতে বিছানায় নিজে ঘুমাতে শেখে","জেগে উঠলে একটু অপেক্ষা করুন; কোলে নেওয়ার আগে পিঠে হাত রেখে নরম গলায় শান্ত করুন","মা-বাবা পালা করে উঠুন, যাতে প্রত্যেকে কিছুটা টানা ঘুম পান"]},"avoid":{"en":["Giving a phone or TV at night to settle","Putting the child to bed with a bottle of milk or sweet drink","Sleep medicines or syrups unless a doctor prescribes them","Shouting or shaking a child out of tiredness"],"bn":["রাতে শান্ত করতে ফোন বা টিভি দেওয়া","দুধ বা মিষ্টি পানীয়ের ফিডার মুখে দিয়ে ঘুম পাড়ানো","ডাক্তার না দিলে ঘুমের ওষুধ বা সিরাপ","ক্লান্তি থেকে শিশুকে বকা বা ঝাঁকানো"]},"example":{"en":"Arif and Sumi''s 11-month-old woke five times a night. They moved bedtime earlier, dropped the late-evening nap and the cartoon before sleep, and Arif took the first waking with a back pat and a lullaby. After three weeks their son woke once or twice and went back to sleep more easily.","bn":"আরিফ আর সুমির ১১ মাসের ছেলে রাতে পাঁচবার জাগত। তাঁরা ঘুমের সময় একটু এগিয়ে আনলেন, সন্ধ্যার দেরির ঘুম আর ঘুমের আগের কার্টুন বাদ দিলেন, আর রাতের প্রথম জাগাটা আরিফ সামলাতেন পিঠে হাত বুলিয়ে আর ঘুমপাড়ানি গান গেয়ে। তিন সপ্তাহ পর ছেলে এক-দুইবার জাগত আর সহজেই আবার ঘুমিয়ে পড়ত।"},"warning_signs":{"en":["Loud snoring with pauses in breathing","Fever, ear pain or breathing difficulty at night","A parent feels so exhausted or low that they cannot cope"],"bn":["জোরে নাক ডাকা, মাঝে মাঝে শ্বাস থেমে যাওয়া","রাতে জ্বর, কানে ব্যথা বা শ্বাসকষ্ট","মা বা বাবা এত ক্লান্ত বা মনমরা যে আর সামলাতে পারছেন না"]},"seek_help":{"en":["Any warning sign: see a doctor","Night waking with poor growth or daytime sleepiness","Sudden change in sleep with crying in pain"],"bn":["যেকোনো বিপদের লক্ষণ: ডাক্তার দেখান","রাতে জাগার সাথে বৃদ্ধি কম বা দিনে অতিরিক্ত ঘুম ঘুম ভাব","হঠাৎ ঘুমের পরিবর্তন, সাথে ব্যথায় কান্না"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['night waking', 'sleep problems', 'bedtime', 'settling', 'tired parents']::text[], false, 'in_review'::lp_review_status, 4035),
  ('in-sc-separation-anxiety', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🫂', '{"en":"My child cries when I leave the room","bn":"আমি ঘর থেকে বের হলেই শিশু কাঁদে"}'::jsonb, '{"en":"Separation anxiety is a normal stage that shows a strong bond. Short, warm goodbyes and always coming back help your child feel safe.","bn":"ছেড়ে থাকার ভয় একটি স্বাভাবিক ধাপ, যা শক্ত বন্ধনের লক্ষণ। ছোট ও আদরমাখা বিদায় আর সবসময় ফিরে আসা শিশুকে নিরাপদ বোধ করায়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"From around 8 months, many babies cry, cling or follow a parent when they leave, even to the next room. It often peaks between about 10 and 18 months and fades slowly after that.","bn":"প্রায় ৮ মাস থেকে অনেক শিশু মা-বাবা চলে গেলে, এমনকি পাশের ঘরে গেলেও, কাঁদে, আঁকড়ে ধরে বা পেছন পেছন যায়। প্রায় ১০ থেকে ১৮ মাসে এটা সবচেয়ে বেশি থাকে, তারপর ধীরে ধীরে কমে।"},"why":{"en":"Your child now understands that you exist when you are out of sight, but does not yet understand time or that you will come back soon. Their bond with you is strong, so your leaving feels like a loss.","bn":"শিশু এখন বোঝে যে চোখের আড়ালেও আপনি আছেন, কিন্তু সময় বা আপনি যে শিগগিরই ফিরবেন, তা এখনো বোঝে না। আপনার সাথে তার বন্ধন শক্ত, তাই আপনার চলে যাওয়াটা তার কাছে হারানোর মতো লাগে।"},"normal":{"en":"Crying for a few minutes when a parent leaves and calming with another familiar adult is normal. So is being clingy with grandparents or relatives the child does not see often.","bn":"মা-বাবা গেলে কয়েক মিনিট কাঁদা আর অন্য চেনা বড় মানুষের কাছে শান্ত হয়ে যাওয়া স্বাভাবিক। কম দেখা দাদা-দাদি বা আত্মীয়দের কাছে না যেতে চাওয়াও স্বাভাবিক।"},"do_now":{"en":["Stay calm and warm; your calm helps your child calm down","Tell your child where you are going in simple words","Leave them with a familiar person and a favourite toy or cloth"],"bn":["শান্ত আর আদরমাখা থাকুন; আপনার শান্ত ভাব শিশুকেও শান্ত করে","সহজ কথায় বলুন কোথায় যাচ্ছেন","চেনা কারো কাছে, প্রিয় খেলনা বা কাপড়সহ রেখে যান"]},"steps":{"en":["Practise short separations at home: go to the next room, keep talking, come back","Play peek-a-boo and hide-and-find games","Make a short goodbye routine: a hug, the same words, a wave","Always say goodbye; do not sneak away","Come back when you said you would, and greet your child happily","Before starting daycare or going back to work, let your child spend time with the new carer while you are there","Give extra closeness at home, especially at bedtime"],"bn":["বাড়িতে ছোট ছোট বিচ্ছেদ অভ্যাস করুন: পাশের ঘরে যান, কথা বলতে থাকুন, ফিরে আসুন","কু-কু আর লুকিয়ে খোঁজার খেলা খেলুন","ছোট একটা বিদায়ের নিয়ম বানান: একটা জড়িয়ে ধরা, একই কথা, হাত নাড়া","সবসময় বিদায় বলে যান; চুপিচুপি চলে যাবেন না","যখন ফিরবেন বলেছেন তখনই ফিরুন, খুশিমনে শিশুকে সম্ভাষণ করুন","ডে-কেয়ার শুরু বা কাজে ফেরার আগে আপনি থাকতে থাকতেই নতুন যত্নকারীর সাথে শিশুকে সময় কাটাতে দিন","বাড়িতে বাড়তি কাছে রাখুন, বিশেষ করে ঘুমের সময়"]},"avoid":{"en":["Sneaking out while the child is distracted","Long, tearful goodbyes","Teasing or shaming: “Big boys don''t cry”","Threatening to leave the child as a punishment"],"bn":["শিশু অন্যমনস্ক থাকার সুযোগে চুপিচুপি বেরিয়ে যাওয়া","লম্বা, কান্নাকাটির বিদায়","খোঁচা দেওয়া বা লজ্জা দেওয়া: “বড় ছেলেরা কাঁদে না”","শাস্তি হিসেবে শিশুকে রেখে চলে যাওয়ার ভয় দেখানো"]},"example":{"en":"Nasrin went back to her office job when her daughter was 13 months. For a week before, the grandmother looked after the child for an hour each morning while Nasrin was in the house. On work days Nasrin hugged her daughter, said “Ammu goes to office, Ammu comes back after Asr”, waved and left. The crying grew shorter each day.","bn":"মেয়ের ১৩ মাস বয়সে নাসরিন অফিসে ফিরলেন। তার আগের এক সপ্তাহ নাসরিন বাড়িতে থাকতেই নানি প্রতিদিন সকালে এক ঘণ্টা মেয়েকে দেখতেন। কাজের দিনে নাসরিন মেয়েকে জড়িয়ে ধরে বলতেন “আম্মু অফিসে যায়, আসরের পরে আম্মু ফিরে আসবে”, হাত নেড়ে বেরিয়ে যেতেন। প্রতিদিন কান্নার সময় কমে আসছিল।"},"seek_help":{"en":["Your child cannot be comforted by any familiar adult, for long periods, every time","The fear stops your child from eating, sleeping or playing for weeks","Clinginess comes with loss of skills or no interest in people","A parent feels overwhelmed or guilty and low"],"bn":["প্রতিবার দীর্ঘ সময় কোনো চেনা বড় মানুষই শিশুকে শান্ত করতে পারে না","ভয়ের কারণে কয়েক সপ্তাহ ধরে খাওয়া, ঘুম বা খেলা বন্ধ","আঁকড়ে থাকার সাথে দক্ষতা হারানো বা মানুষের প্রতি আগ্রহ না থাকা","মা বা বাবা অতিরিক্ত চাপ, অপরাধবোধ বা মন খারাপে ভুগছেন"]}}'::jsonb, 3, 213, 730, '{}'::text[], 'any', ARRAY['separation anxiety', 'clingy', 'crying when mother leaves', 'working mother', 'stranger anxiety']::text[], false, 'in_review'::lp_review_status, 4036),
  ('in-sc-biting', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '😬', '{"en":"My child bites","bn":"শিশু কামড়ায়"}'::jsonb, '{"en":"Biting is common between about 9 months and 2 years. Respond calmly and the same way every time, and teach what to do instead.","bn":"প্রায় ৯ মাস থেকে ২ বছরের মধ্যে কামড়ানো খুব সাধারণ। প্রতিবার শান্তভাবে একইভাবে সাড়া দিন, আর বদলে কী করবে তা শেখান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Babies and toddlers bite the breast, a parent''s shoulder, a sibling or another child. At this age it is rarely meant to hurt; it is a way to explore, relieve gum pain or express a feeling they cannot yet put into words.","bn":"ছোট শিশু স্তন, মা-বাবার কাঁধ, ভাইবোন বা অন্য শিশুকে কামড়ায়। এ বয়সে কষ্ট দেওয়ার উদ্দেশ্যে খুব কমই কামড়ায়; এটা খুঁজে দেখা, মাড়ির ব্যথা কমানো, বা যে অনুভূতি এখনো মুখে বলতে পারে না তা প্রকাশের একটা উপায়।"},"why":{"en":"Common reasons: teething, excitement, frustration, tiredness, wanting attention, or copying. A big reaction, laughing or shouting, can make biting more interesting to repeat.","bn":"সাধারণ কারণ: দাঁত ওঠা, উত্তেজনা, হতাশা, ক্লান্তি, মনোযোগ চাওয়া বা দেখে শেখা। বড় প্রতিক্রিয়া, হাসি বা চিৎকার, কামড়কে আবার করার মতো মজার করে তুলতে পারে।"},"normal":{"en":"Occasional biting in children under 2, especially when teething or tired, is a normal phase that usually passes as language grows.","bn":"২ বছরের কম শিশুর মাঝে মাঝে কামড়ানো, বিশেষ করে দাঁত ওঠার সময় বা ক্লান্ত থাকলে, একটা স্বাভাবিক পর্ব, যা ভাষা বাড়ার সাথে সাধারণত চলে যায়।"},"do_now":{"en":["Calmly say “No biting. Biting hurts.” in a firm, low voice","Move your child away from the person they bit","Comfort the person who was bitten first; wash any broken skin with soap and water"],"bn":["শান্ত, দৃঢ়, নিচু গলায় বলুন “কামড়ানো না। কামড়ালে ব্যথা লাগে।”","যাকে কামড়েছে, তার কাছ থেকে শিশুকে সরিয়ে নিন","আগে যে কামড় খেয়েছে তাকে সান্ত্বনা দিন; চামড়া কেটে গেলে সাবান-পানিতে ধুয়ে দিন"]},"steps":{"en":["If your baby bites while breastfeeding, calmly take them off the breast by slipping your finger into the corner of the mouth, and pause the feed briefly","Offer safe things to chew when teething: a teething ring or cold, clean cloth","Watch for times biting happens, such as tiredness or crowded play, and step in early","Name the feeling: “You are angry, he took your toy”","Teach another action: “Gentle hands”, stroking, or saying “mine” or “no”","Praise gentle play when you see it","Make sure everyone in the family responds the same way"],"bn":["বুকের দুধ খাওয়ার সময় কামড়ালে শান্তভাবে মুখের কোনায় আঙুল ঢুকিয়ে শিশুকে ছাড়িয়ে নিন, অল্প সময় খাওয়ানো থামান","দাঁত ওঠার সময় চিবানোর নিরাপদ জিনিস দিন: টিদার বা ঠান্ডা পরিষ্কার কাপড়","কখন কামড়ায় খেয়াল করুন, যেমন ক্লান্ত থাকলে বা ভিড়ের মধ্যে খেলায়, আর আগেভাগেই সামলে নিন","অনুভূতির নাম বলুন: “তুমি রাগ করেছ, ও তোমার খেলনা নিয়ে নিয়েছে”","বদলে অন্য কিছু শেখান: “আস্তে হাত”, আলতো ছোঁয়া, বা “আমার” কিংবা “না” বলা","আলতো খেলা দেখলেই প্রশংসা করুন","পরিবারের সবাই যেন একইভাবে সাড়া দেন"]},"avoid":{"en":["Biting your child back “to show how it feels”","Hitting, shouting or long scolding","Laughing at biting, which makes it a game","Labelling the child as bad or naughty"],"bn":["“কেমন লাগে বোঝাতে” শিশুকে পাল্টা কামড় দেওয়া","মারা, চিৎকার বা লম্বা বকাঝকা","কামড়ানো দেখে হাসা, এতে এটা খেলা হয়ে যায়","শিশুকে খারাপ বা দুষ্টু বলে তকমা দেওয়া"]},"example":{"en":"Fifteen-month-old Rafi bit his cousin when she took his ball. His father picked him up, said quietly “No biting, it hurts”, sat with the crying cousin, then told Rafi “You wanted your ball. Say ‘my ball’.” Over the next weeks, whenever Rafi got cross, his parents named the feeling and gave him words, and the biting stopped.","bn":"১৫ মাসের রাফি তার চাচাতো বোন বল নিয়ে নিলে তাকে কামড়ে দিল। বাবা রাফিকে কোলে তুলে আস্তে বললেন “কামড়ানো না, ব্যথা লাগে”, কাঁদতে থাকা বোনটির পাশে বসলেন, তারপর রাফিকে বললেন “তুমি তোমার বল চাইছিলে। বলো ‘আমার বল’।” পরের কয়েক সপ্তাহ রাফি রাগ করলেই মা-বাবা অনুভূতির নাম বলে দিতেন আর কথা শিখিয়ে দিতেন; কামড়ানো বন্ধ হয়ে গেল।"},"seek_help":{"en":["A bite breaks the skin and the area becomes red, swollen, hot or oozes pus","Biting is frequent, severe and continues after age 3","Biting comes with very little speech or little interest in people"],"bn":["কামড়ে চামড়া কেটে গেছে, আর জায়গাটা লাল, ফোলা, গরম হয়েছে বা পুঁজ বের হচ্ছে","ঘনঘন, জোরে কামড়ায়, আর ৩ বছরের পরেও চলছে","কামড়ানোর সাথে কথা খুব কম বা মানুষের প্রতি আগ্রহ কম"]}}'::jsonb, 3, 274, 730, '{}'::text[], 'any', ARRAY['biting', 'toddler behaviour', 'teething', 'breastfeeding bite', 'aggression']::text[], false, 'in_review'::lp_review_status, 4037),
  ('in-sc-diarrhoea', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🚼', '{"en":"My child has diarrhoea","bn":"শিশুর ডায়রিয়া হয়েছে"}'::jsonb, '{"en":"Start ORS now, keep breastfeeding and feeding, and give zinc for 10–14 days as your health worker advises. Watch for danger signs.","bn":"এখনই খাবার স্যালাইন শুরু করুন, বুকের দুধ ও খাবার চালিয়ে যান, আর স্বাস্থ্যকর্মীর পরামর্শমতো ১০–১৪ দিন জিংক দিন। বিপদের লক্ষণে চোখ রাখুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Three or more loose or watery stools in a day is diarrhoea. In young children the main danger is losing water and salts. With the right fluids and food at home, most children recover within a few days.","bn":"দিনে তিন বা তার বেশিবার পাতলা বা পানির মতো পায়খানা হলে তা ডায়রিয়া। ছোট শিশুর প্রধান বিপদ শরীর থেকে পানি ও লবণ বেরিয়ে যাওয়া। ঘরে সঠিক তরল আর খাবারে বেশিরভাগ শিশু কয়েক দিনের মধ্যে সেরে ওঠে।"},"why":{"en":"Most diarrhoea in young children is caused by germs from dirty hands, unsafe water or spoiled food, often viruses. Crawling and putting things in the mouth add to the risk at this age.","bn":"ছোট শিশুর বেশিরভাগ ডায়রিয়া হয় নোংরা হাত, অনিরাপদ পানি বা নষ্ট খাবারের জীবাণু থেকে, প্রায়ই ভাইরাসে। এ বয়সে হামাগুড়ি দেওয়া আর সবকিছু মুখে দেওয়ায় ঝুঁকি বাড়ে।"},"normal":{"en":"A breastfed baby''s stools are often soft and frequent; that is not diarrhoea. With an illness, loose stools may last a few days and slowly firm up.","bn":"বুকের দুধ খাওয়া শিশুর পায়খানা প্রায়ই নরম ও ঘনঘন হয়; সেটা ডায়রিয়া নয়। অসুখে পাতলা পায়খানা কয়েক দিন থাকতে পারে, তারপর ধীরে ধীরে শক্ত হয়।"},"do_now":{"en":["Start ORS (orsaline), mixed exactly as the packet says","After each loose stool, give about 50–100 ml (a quarter to half a cup) by spoon or small sips","Keep breastfeeding, more often than usual","Contact your health worker or community clinic about zinc"],"bn":["প্যাকেটের নির্দেশমতো ঠিকঠাক গুলে খাবার স্যালাইন শুরু করুন","প্রতিবার পাতলা পায়খানার পর চামচে বা অল্প চুমুকে প্রায় ৫০–১০০ মিলি (সিকি থেকে আধা কাপ) দিন","বুকের দুধ চালিয়ে যান, স্বাভাবিকের চেয়ে বেশিবার","জিংকের জন্য স্বাস্থ্যকর্মী বা কমিউনিটি ক্লিনিকে যোগাযোগ করুন"]},"steps":{"en":["Give zinc once a day for 10–14 days, in the dose your health worker gives, even after the diarrhoea stops","If your child vomits, wait 10 minutes and give ORS more slowly","Keep giving soft foods: khichuri, mashed potato, banana, egg","Wash your hands with soap after cleaning your child and before feeding","Dispose of stool in a latrine and wash the cloths well","After recovery, give one extra meal a day for about two weeks"],"bn":["স্বাস্থ্যকর্মী যে মাত্রা দেন, সেই মাত্রায় দিনে একবার ১০–১৪ দিন জিংক দিন, ডায়রিয়া থেমে গেলেও","বমি করলে ১০ মিনিট অপেক্ষা করে আরও ধীরে স্যালাইন দিন","নরম খাবার চালিয়ে যান: খিচুড়ি, আলু চটকানো, কলা, ডিম","শিশুকে পরিষ্কার করার পরে আর খাওয়ানোর আগে সাবান দিয়ে হাত ধুয়ে নিন","পায়খানা ল্যাট্রিনে ফেলুন, কাপড় ভালো করে ধুয়ে নিন","সেরে ওঠার পর প্রায় দুই সপ্তাহ দিনে একবার বাড়তি খাবার দিন"]},"avoid":{"en":["Stopping breast milk or food","Anti-diarrhoea medicines or antibiotics unless a doctor prescribes them","Soft drinks, packaged juice or glucose drinks instead of ORS","Making ORS stronger or weaker than the packet says"],"bn":["বুকের দুধ বা খাবার বন্ধ করা","ডাক্তার না দিলে পায়খানা বন্ধের ওষুধ বা অ্যান্টিবায়োটিক","স্যালাইনের বদলে কোমল পানীয়, প্যাকেটের জুস বা গ্লুকোজের পানীয়","প্যাকেটে যা বলা আছে তার চেয়ে ঘন বা পাতলা করে স্যালাইন বানানো"]},"example":{"en":"When 10-month-old Mim had watery stools four times one morning, her mother mixed a packet of orsaline in the amount of water printed on it and gave half a cup by spoon after each stool. The community health worker gave zinc tablets for 10 days. Mim kept breastfeeding and eating khichuri, and the diarrhoea settled in three days.","bn":"এক সকালে ১০ মাসের মীমের চারবার পানির মতো পায়খানা হলে মা প্যাকেটে লেখা পরিমাণ পানিতে এক প্যাকেট খাবার স্যালাইন গুলে প্রতিবার পায়খানার পর চামচে আধা কাপ করে দিলেন। কমিউনিটি স্বাস্থ্যকর্মী ১০ দিনের জিংক ট্যাবলেট দিলেন। মীম বুকের দুধ আর খিচুড়ি খেতে থাকল, তিন দিনে ডায়রিয়া থেমে গেল।"},"warning_signs":{"en":["Very sleepy, floppy or hard to wake","Unable to drink or breastfeed, or drinks poorly","Sunken eyes, or no tears when crying","Skin pinched on the belly goes back very slowly","Blood in the stool","Vomits everything, or diarrhoea lasting 14 days or more"],"bn":["খুব ঘুমকাতুরে, নেতিয়ে পড়া বা জাগানো কঠিন","পান করতে বা বুকের দুধ টানতে পারছে না, বা খুব কম পান করছে","চোখ বসে গেছে, বা কাঁদলে চোখে পানি নেই","পেটের চামড়া চিমটি দিয়ে ছাড়লে খুব ধীরে আগের অবস্থায় ফেরে","পায়খানায় রক্ত","যা খায় সব বমি, বা ১৪ দিন বা তার বেশি ডায়রিয়া"]},"seek_help":{"en":["Any warning sign: go to hospital now, giving ORS on the way if your child can drink","Very thirsty, restless or irritable: see a health worker today","High fever, or no improvement after 2–3 days"],"bn":["যেকোনো বিপদের লক্ষণ: এখনই হাসপাতালে যান, শিশু পান করতে পারলে পথে স্যালাইন দিতে থাকুন","খুব পিপাসা, অস্থির বা খিটখিটে: আজই স্বাস্থ্যকর্মী দেখান","বেশি জ্বর, বা ২–৩ দিনেও উন্নতি নেই"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['diarrhoea', 'loose motion', 'ors', 'zinc', 'dehydration', 'vomiting']::text[], false, 'in_review'::lp_review_status, 4038),
  ('in-sc-fever', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🌡️', '{"en":"My child has a fever","bn":"শিশুর জ্বর হয়েছে"}'::jsonb, '{"en":"Fever is the body fighting an infection. Measure it, keep your child drinking, look for danger signs, and see a health worker if it lasts or worries you.","bn":"জ্বর মানে শরীর সংক্রমণের সাথে লড়ছে। মেপে দেখুন, শিশুকে পান করাতে থাকুন, বিপদের লক্ষণ খুঁজুন, আর জ্বর না কমলে বা চিন্তা হলে স্বাস্থ্যকর্মী দেখান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"A temperature of 38°C or more is a fever. In young children it is most often caused by a cold or other virus, but it can also be a sign of pneumonia, an ear or urine infection, dengue, malaria in some areas, or other serious illness.","bn":"৩৮°সে বা তার বেশি তাপমাত্রা হলে জ্বর। ছোট শিশুর জ্বর বেশিরভাগ সময় সর্দি বা অন্য ভাইরাস থেকে হয়, তবে নিউমোনিয়া, কান বা প্রস্রাবের সংক্রমণ, ডেঙ্গু, কিছু এলাকায় ম্যালেরিয়া বা অন্য গুরুতর অসুখেরও লক্ষণ হতে পারে।"},"why":{"en":"Fever itself is the body''s defence. What matters most is how your child looks and behaves, how long the fever lasts, and whether there are other signs.","bn":"জ্বর নিজে শরীরের প্রতিরক্ষা। সবচেয়ে জরুরি হলো শিশু দেখতে ও আচরণে কেমন, জ্বর কত দিন ধরে, আর অন্য কোনো লক্ষণ আছে কিনা।"},"normal":{"en":"A child with a mild fever who still plays a little, drinks well and smiles when the fever comes down is usually not seriously ill. A light fever for a day or two after a vaccine is also common.","bn":"হালকা জ্বরে যে শিশু একটু-আধটু খেলে, ভালোভাবে পান করে, আর জ্বর কমলে হাসে, সে সাধারণত গুরুতর অসুস্থ নয়। টিকার পর এক-দুই দিন হালকা জ্বরও সাধারণ।"},"do_now":{"en":["Measure the temperature with a thermometer under the arm","Check for danger signs (see below)","Breastfeed more often and offer extra fluids","Dress your child in light cotton clothes; do not wrap in blankets"],"bn":["থার্মোমিটার বগলে দিয়ে তাপমাত্রা মাপুন","বিপদের লক্ষণ আছে কিনা দেখুন (নিচে দেখুন)","বেশিবার বুকের দুধ দিন, বাড়তি তরল দিন","হালকা সুতির কাপড় পরান; কাঁথা-কম্বলে মুড়িয়ে রাখবেন না"]},"steps":{"en":["Give paracetamol only in the dose a health worker or doctor advises for your child''s weight","Wipe with a cloth dipped in normal-temperature water if your child feels uncomfortable; never use cold water or ice","Keep offering small meals your child likes","Write down the temperature and times so you can tell the health worker","Use a mosquito net day and night, especially in the dengue season","If a fit happens: lay your child on their side on a flat surface, move hard objects away, put nothing in the mouth, note how long it lasts, then go to hospital"],"bn":["স্বাস্থ্যকর্মী বা ডাক্তার শিশুর ওজন অনুযায়ী যে মাত্রা বলেন, শুধু সেই মাত্রায় প্যারাসিটামল দিন","শিশুর অস্বস্তি হলে স্বাভাবিক তাপমাত্রার পানিতে ভেজানো কাপড়ে গা মুছে দিন; ঠান্ডা পানি বা বরফ কখনো নয়","শিশুর পছন্দের খাবার অল্প অল্প দিতে থাকুন","তাপমাত্রা আর সময় লিখে রাখুন, স্বাস্থ্যকর্মীকে জানাতে পারবেন","দিনে-রাতে মশারি ব্যবহার করুন, বিশেষ করে ডেঙ্গুর মৌসুমে","খিঁচুনি হলে: শিশুকে সমান জায়গায় কাত করে শোয়ান, শক্ত জিনিস সরিয়ে দিন, মুখে কিছু ঢোকাবেন না, কতক্ষণ চলল খেয়াল করুন, তারপর হাসপাতালে যান"]},"avoid":{"en":["Aspirin for children","Antibiotics without a doctor''s prescription","Cold water baths, ice or wrapping in thick blankets","Waiting many days at home with a high or lasting fever"],"bn":["শিশুকে অ্যাসপিরিন","ডাক্তারের ব্যবস্থাপত্র ছাড়া অ্যান্টিবায়োটিক","ঠান্ডা পানিতে গোসল, বরফ, বা মোটা কাঁথা-কম্বলে মোড়ানো","বেশি বা টানা জ্বর নিয়ে বাড়িতে দিনের পর দিন অপেক্ষা"]},"example":{"en":"During the rainy season, 18-month-old Ayaan had a fever of 39°C. His parents gave paracetamol in the dose their doctor had advised, kept him under the net and offered water and breast milk often. When the fever was still there on the third day, they took him to the Upazila Health Complex, where he was checked and tested.","bn":"বর্ষাকালে ১৮ মাসের আয়ানের ৩৯°সে জ্বর এল। মা-বাবা ডাক্তারের ব্যবস্থাপত্রের মাত্রায় প্যারাসিটামল দিলেন, মশারির নিচে রাখলেন, বারবার পানি ও বুকের দুধ দিলেন। তৃতীয় দিনেও জ্বর না কমায় তাঁরা ওকে উপজেলা স্বাস্থ্য কমপ্লেক্সে নিয়ে গেলেন, সেখানে দেখে পরীক্ষা করা হলো।"},"warning_signs":{"en":["Unable to drink or breastfeed, or vomits everything","A fit (convulsion)","Very sleepy, floppy or hard to wake","Fast breathing, chest indrawing or difficulty breathing","Stiff neck, or a rash that does not fade when you press a glass on it","Bleeding from gums or nose, severe tummy pain or repeated vomiting (possible severe dengue)"],"bn":["পান করতে বা বুকের দুধ টানতে পারে না, বা সব বমি করে","খিঁচুনি","খুব ঘুমকাতুরে, নেতিয়ে পড়া বা জাগানো কঠিন","দ্রুত শ্বাস, বুক দেবে যাওয়া বা শ্বাসকষ্ট","ঘাড় শক্ত, বা এমন র‍্যাশ যা গ্লাস চেপে ধরলেও মিলিয়ে যায় না","মাড়ি বা নাক দিয়ে রক্ত, পেটে তীব্র ব্যথা বা বারবার বমি (মারাত্মক ডেঙ্গু হতে পারে)"]},"seek_help":{"en":["Any warning sign: go to hospital or call 999 now","Fever lasting more than 2 days: see a health worker","Fever with ear pain, pain when passing urine, or a new rash","You are worried, even if you cannot say why"],"bn":["যেকোনো বিপদের লক্ষণ: এখনই হাসপাতালে যান বা ৯৯৯-এ ফোন করুন","২ দিনের বেশি জ্বর: স্বাস্থ্যকর্মী দেখান","জ্বরের সাথে কানে ব্যথা, প্রস্রাবে ব্যথা বা নতুন র‍্যাশ","আপনি চিন্তিত, কেন তা বলতে না পারলেও"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['fever', 'high temperature', 'febrile convulsion', 'dengue', 'paracetamol', 'thermometer']::text[], false, 'in_review'::lp_review_status, 4039),
  ('in-sc-head-bump', 'scenario', 'scientific', 'shared', 'important', 'consensus', '🤕', '{"en":"My child fell and hit their head","bn":"শিশু পড়ে গিয়ে মাথায় আঘাত পেয়েছে"}'::jsonb, '{"en":"Most bumps are minor. Comfort, cool the swelling and watch closely for 24 hours. Know the signs that mean hospital now.","bn":"বেশিরভাগ আঘাত সামান্য। শান্ত করুন, ফোলা জায়গায় ঠান্ডা দিন, ২৪ ঘণ্টা কাছ থেকে নজর রাখুন। কোন লক্ষণে এখনই হাসপাতালে যেতে হবে, জেনে রাখুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Babies and toddlers fall often: off beds, while learning to walk, or down a step. Most head bumps cause only a lump and tears. A few cause injury inside the skull, so watching your child in the hours afterwards matters.","bn":"ছোট শিশু প্রায়ই পড়ে যায়: খাট থেকে, হাঁটা শিখতে গিয়ে, বা সিঁড়ি থেকে। বেশিরভাগ মাথার আঘাতে শুধু ফোলা আর কান্না হয়। অল্প কিছু ক্ষেত্রে মাথার ভেতরে আঘাত লাগে, তাই পরের কয়েক ঘণ্টা শিশুর দিকে নজর রাখা জরুরি।"},"why":{"en":"A young child''s head is large and heavy compared with the body, so they often land head-first. Falls from heights, such as stairs, a roof, a balcony or from an adult''s arms, carry more risk.","bn":"শরীরের তুলনায় ছোট শিশুর মাথা বড় ও ভারী, তাই প্রায়ই মাথা আগে পড়ে। উঁচু থেকে পড়া, যেমন সিঁড়ি, ছাদ, বারান্দা বা বড় কারো কোল থেকে, বেশি ঝুঁকির।"},"normal":{"en":"Crying straight away, a lump that swells quickly, and being a bit quiet or sleepy for a short time are common after a minor bump. A child who cries, settles and then plays and feeds normally is usually fine.","bn":"সামান্য আঘাতের পর সাথে সাথে কান্না, দ্রুত ফুলে ওঠা, আর অল্প সময় একটু চুপচাপ বা ঘুম ঘুম থাকা সাধারণ। যে শিশু কেঁদে শান্ত হয়, তারপর স্বাভাবিকভাবে খেলে ও খায়, সে সাধারণত ঠিক আছে।"},"do_now":{"en":["Stay calm, pick up and comfort your child unless they may have hurt the neck or back","Check that they are awake, crying and moving arms and legs","Hold a cold, wet cloth or ice wrapped in cloth on the lump for 10–20 minutes"],"bn":["শান্ত থাকুন; ঘাড় বা পিঠে আঘাতের সন্দেহ না থাকলে কোলে তুলে সান্ত্বনা দিন","দেখুন সে জেগে আছে, কাঁদছে, হাত-পা নাড়ছে কিনা","ফোলা জায়গায় ঠান্ডা ভেজা কাপড় বা কাপড়ে মোড়ানো বরফ ১০–২০ মিনিট ধরে রাখুন"]},"steps":{"en":["Watch your child closely for the next 24 hours","Let them nap if they want, but check that they wake easily and act like themselves","Offer feeds and drinks as usual","Keep play quiet for the rest of the day","Make sure an adult stays with the child through the night","Find out how the fall happened, and fix the danger: a bed edge, stairs, an open roof door"],"bn":["পরের ২৪ ঘণ্টা শিশুকে কাছ থেকে দেখুন","ঘুমাতে চাইলে ঘুমাতে দিন, কিন্তু সহজে জাগে আর স্বাভাবিক আচরণ করে কিনা দেখে নিন","স্বাভাবিকভাবে খাবার ও পানীয় দিন","বাকি দিনটা শান্ত খেলা রাখুন","রাতে একজন বড় মানুষ যেন শিশুর সাথে থাকেন","কীভাবে পড়ল খুঁজে বের করুন, আর বিপদটা ঠিক করুন: খাটের কিনারা, সিঁড়ি, খোলা ছাদের দরজা"]},"avoid":{"en":["Rubbing oil, turmeric or pressing hard on the lump","Giving any medicine that causes sleepiness","Shaking a child to wake them","Leaving the child alone after a fall"],"bn":["ফোলা জায়গায় তেল, হলুদ ঘষা বা জোরে চাপ দেওয়া","ঘুম আনে এমন কোনো ওষুধ দেওয়া","জাগাতে শিশুকে ঝাঁকানো","পড়ার পর শিশুকে একা রেখে যাওয়া"]},"example":{"en":"Ten-month-old Sara rolled off the chouki onto the floor while her mother fetched water. She cried at once and a lump came up on her forehead. Her mother held a cold cloth on it, fed her, and watched her all day. Sara played normally. That evening her father fixed a wooden rail along the chouki''s open side.","bn":"মা পানি আনতে গেলে ১০ মাসের সারা চৌকি থেকে গড়িয়ে মেঝেতে পড়ে গেল। সাথে সাথে কাঁদল, কপালে ফুলে উঠল। মা ঠান্ডা কাপড় ধরে রাখলেন, খাওয়ালেন, আর সারাদিন চোখে চোখে রাখলেন। সারা স্বাভাবিকভাবে খেলল। সেই সন্ধ্যায় বাবা চৌকির খোলা পাশে একটা কাঠের রেলিং লাগিয়ে দিলেন।"},"warning_signs":{"en":["Lost consciousness, even briefly","Vomiting more than once","Unusually sleepy, hard to wake or floppy","A fit (convulsion)","Blood or clear fluid from the nose or ears","Will not stop crying, or acts strangely; weakness in an arm or leg","A soft, boggy swelling, or a fall from a height such as stairs, a roof or a balcony"],"bn":["অল্প সময়ের জন্য হলেও অজ্ঞান হয়েছিল","একবারের বেশি বমি","অস্বাভাবিক ঘুমকাতুরে, জাগানো কঠিন বা নেতিয়ে পড়া","খিঁচুনি","নাক বা কান দিয়ে রক্ত বা পরিষ্কার পানি বের হওয়া","কান্না থামছে না, বা অদ্ভুত আচরণ; হাত বা পায়ে দুর্বলতা","নরম, থলথলে ফোলা, অথবা সিঁড়ি, ছাদ বা বারান্দার মতো উঁচু থেকে পড়া"]},"seek_help":{"en":["Any warning sign: go to hospital or call 999 now","A baby under 1 year with a large swelling: see a doctor today","You are unsure how the injury happened, or you are worried"],"bn":["যেকোনো বিপদের লক্ষণ: এখনই হাসপাতালে যান বা ৯৯৯-এ ফোন করুন","১ বছরের কম শিশুর বড় ফোলা: আজই ডাক্তার দেখান","কীভাবে আঘাত পেল নিশ্চিত নন, বা আপনি চিন্তিত"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['head injury', 'fall', 'bump', 'concussion', 'fell from bed', 'first aid']::text[], false, 'in_review'::lp_review_status, 4040),
  ('in-sc-swallowed-object', 'scenario', 'scientific', 'shared', 'important', 'consensus', '🪙', '{"en":"My child put something in their mouth or swallowed it","bn":"শিশু কিছু মুখে দিয়েছে বা গিলে ফেলেছে"}'::jsonb, '{"en":"If your child cannot breathe, start choking first aid and call 999. A swallowed button battery or magnet is always an emergency, even if your child seems fine.","bn":"শিশু শ্বাস নিতে না পারলে গলায় আটকানোর প্রাথমিক চিকিৎসা শুরু করুন, ৯৯৯-এ ফোন করুন। বোতাম ব্যাটারি বা চুম্বক গিলে ফেলা সবসময় জরুরি অবস্থা, শিশুকে ঠিক মনে হলেও।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Young children explore with their mouths. Coins, beads, seeds, small toy parts, buttons and batteries are common finds. An object can block the airway (choking), get stuck in the food pipe, or pass through the gut.","bn":"ছোট শিশু মুখ দিয়ে দুনিয়া চেনে। কয়েন, পুঁতি, বিচি, খেলনার ছোট অংশ, বোতাম আর ব্যাটারি প্রায়ই মুখে যায়। জিনিসটা শ্বাসনালি আটকে দিতে পারে, খাদ্যনালিতে আটকে থাকতে পারে, বা পেট দিয়ে বেরিয়ে যেতে পারে।"},"why":{"en":"Button batteries can burn through the food pipe within hours. Two or more magnets can pull together through the gut wall. Sharp objects can cut. These need urgent care even without symptoms.","bn":"বোতাম ব্যাটারি কয়েক ঘণ্টার মধ্যে খাদ্যনালি পুড়িয়ে দিতে পারে। দুই বা বেশি চুম্বক পেটের দেয়াল ভেদ করে পরস্পরকে টেনে আনতে পারে। ধারালো জিনিস কেটে দিতে পারে। কোনো লক্ষণ না থাকলেও এগুলোর জন্য জরুরি চিকিৎসা লাগে।"},"normal":{"en":"Many small smooth objects, like a small coin, pass in the stool within a few days without harm. But you should still have your child checked, because you cannot tell at home where it is.","bn":"অনেক ছোট মসৃণ জিনিস, যেমন ছোট কয়েন, কয়েক দিনের মধ্যে কোনো ক্ষতি ছাড়াই পায়খানার সাথে বেরিয়ে যায়। তবুও শিশুকে দেখিয়ে নিন, কারণ জিনিসটা কোথায় আছে তা বাড়িতে বোঝা যায় না।"},"do_now":{"en":["If the object is still in the mouth, ask for it calmly or hook it out only if you can clearly see it","If your child is coughing hard, let them cough; do not slap or hold upside down","If your child cannot cough, cry or breathe: shout for help, call 999 and start choking first aid","Under 1 year: up to 5 back blows face-down on your forearm, then up to 5 chest thrusts with two fingers; over 1 year: back blows, then abdominal thrusts; repeat"],"bn":["জিনিসটা এখনো মুখে থাকলে শান্তভাবে চেয়ে নিন, বা স্পষ্ট দেখতে পেলে তবেই আঙুলে বের করুন","শিশু জোরে কাশলে কাশতে দিন; চাপড় দেবেন না বা উল্টো করে ঝোলাবেন না","কাশতে, কাঁদতে বা শ্বাস নিতে না পারলে: চিৎকার করে সাহায্য ডাকুন, ৯৯৯-এ ফোন করুন, গলায় আটকানোর প্রাথমিক চিকিৎসা শুরু করুন","১ বছরের কম: বাহুর ওপর উপুড় করে পিঠে ৫ বার পর্যন্ত চাপড়, তারপর দুই আঙুলে বুকে ৫ বার পর্যন্ত চাপ; ১ বছরের বেশি: পিঠে চাপড়, তারপর পেটে চাপ; বারবার করুন"]},"steps":{"en":["If it was a button battery, magnet or sharp object: go to hospital now, even if your child seems well","Take the packet, the remote or a similar object with you","Do not give food or drink until a doctor has seen your child, if a battery or sharp object is possible","For a small smooth object with no symptoms, see a doctor the same day","Afterwards, sweep the floor, check toys, and lock away batteries and remotes"],"bn":["বোতাম ব্যাটারি, চুম্বক বা ধারালো কিছু হলে: এখনই হাসপাতালে যান, শিশুকে ঠিক মনে হলেও","প্যাকেট, রিমোট বা একই রকম জিনিস সাথে নিন","ব্যাটারি বা ধারালো কিছু হওয়ার সম্ভাবনা থাকলে ডাক্তার না দেখা পর্যন্ত খাবার বা পানীয় দেবেন না","লক্ষণ নেই এমন ছোট মসৃণ জিনিস হলে সেদিনই ডাক্তার দেখান","পরে মেঝে ঝাড়ু দিন, খেলনা দেখে নিন, ব্যাটারি ও রিমোট তালাবদ্ধ করুন"]},"avoid":{"en":["Sweeping a finger blindly in the mouth, which can push it deeper","Making your child vomit","Giving banana, rice or oil to “push it down”","Waiting to see if a battery passes"],"bn":["না দেখে মুখের ভেতরে আঙুল চালানো, এতে আরও ভেতরে চলে যেতে পারে","শিশুকে বমি করানো","“নিচে নামাতে” কলা, ভাত বা তেল খাওয়ানো","ব্যাটারি বেরিয়ে যায় কিনা দেখার জন্য অপেক্ষা করা"]},"example":{"en":"Sixteen-month-old Tamim was found chewing an old TV remote, and its back cover was open with one small battery missing. He looked fine, but his father took him straight to the hospital with the remote. An X-ray found the battery, and doctors removed it quickly.","bn":"১৬ মাসের তামিমকে দেখা গেল পুরোনো টিভির রিমোট চিবাচ্ছে, পেছনের ঢাকনা খোলা, একটা ছোট ব্যাটারি নেই। তামিমকে ঠিকঠাক দেখাচ্ছিল, কিন্তু বাবা রিমোটসহ সোজা হাসপাতালে নিয়ে গেলেন। এক্স-রে-তে ব্যাটারি পাওয়া গেল, ডাক্তাররা দ্রুত তা বের করে আনলেন।"},"warning_signs":{"en":["Cannot breathe, cough or cry, or turning blue","Noisy breathing, wheezing or a cough that will not stop","Drooling, refusing to eat, gagging or vomiting","Pain in the chest, throat or tummy","Blood in vomit or stool"],"bn":["শ্বাস নিতে, কাশতে বা কাঁদতে পারে না, বা নীল হয়ে যাচ্ছে","শব্দ করে শ্বাস, শাঁ শাঁ আওয়াজ বা না থামা কাশি","লালা ঝরা, খেতে না চাওয়া, ওয়াক ওঠা বা বমি","বুকে, গলায় বা পেটে ব্যথা","বমি বা পায়খানায় রক্ত"]},"seek_help":{"en":["Any warning sign: call 999 or go to hospital now","Any button battery, magnet or sharp object: hospital now","Any other swallowed object: see a doctor the same day"],"bn":["যেকোনো বিপদের লক্ষণ: এখনই ৯৯৯-এ ফোন করুন বা হাসপাতালে যান","যেকোনো বোতাম ব্যাটারি, চুম্বক বা ধারালো জিনিস: এখনই হাসপাতালে","অন্য যেকোনো জিনিস গিলে থাকলে: সেদিনই ডাক্তার দেখান"]}}'::jsonb, 3, 183, 730, '{}'::text[], 'any', ARRAY['swallowed object', 'coin', 'button battery', 'magnet', 'choking', 'foreign body']::text[], false, 'in_review'::lp_review_status, 4041),
  ('in-sc-tantrums', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '😤', '{"en":"My toddler has tantrums","bn":"ছোট্ট শিশু জেদ করে কান্নাকাটি করে"}'::jsonb, '{"en":"Tantrums are a normal part of toddler development. Stay calm, keep your child safe, and help them through the feeling without hitting or shouting.","bn":"জেদ আর কান্নাকাটি ছোট শিশুর বিকাশের স্বাভাবিক অংশ। শান্ত থাকুন, শিশুকে নিরাপদ রাখুন, আর মারধর বা চিৎকার ছাড়াই অনুভূতিটা পার হতে সাহায্য করুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Between about 1 and 3 years, many children cry, scream, throw themselves on the floor or hit out when they are upset. It can be embarrassing, especially in front of relatives or in a shop, but it does not mean you are a bad parent or your child is spoilt.","bn":"প্রায় ১ থেকে ৩ বছরে অনেক শিশু মন খারাপ হলে কাঁদে, চিৎকার করে, মাটিতে গড়াগড়ি দেয় বা হাত-পা ছোড়ে। বিশেষ করে আত্মীয়দের সামনে বা দোকানে এটা লজ্জার লাগতে পারে, কিন্তু এর মানে এই নয় যে আপনি খারাপ মা-বাবা বা শিশু আহ্লাদি হয়ে গেছে।"},"why":{"en":"Toddlers want to do things themselves but cannot yet say what they want or control strong feelings. Tiredness, hunger, too much noise, or hearing “no” many times make tantrums more likely.","bn":"ছোট শিশু সব নিজে করতে চায়, কিন্তু কী চায় তা এখনো বলতে পারে না, আর তীব্র অনুভূতিও সামলাতে পারে না। ক্লান্তি, খিদে, বেশি হট্টগোল, বা বারবার “না” শোনায় জেদ বেশি হয়।"},"normal":{"en":"Short tantrums of a few minutes, a few times a week, that end with the child calming and returning to play, are common at this age.","bn":"সপ্তাহে কয়েকবার কয়েক মিনিটের জেদ, যার শেষে শিশু শান্ত হয়ে আবার খেলায় ফেরে, এ বয়সে খুব সাধারণ।"},"do_now":{"en":["Stay calm; take a slow breath before you respond","Keep your child safe: move hard or sharp things away","Stay close and use few, gentle words: “You are angry. I am here.”"],"bn":["শান্ত থাকুন; সাড়া দেওয়ার আগে ধীরে একটা শ্বাস নিন","শিশুকে নিরাপদ রাখুন: শক্ত বা ধারালো জিনিস সরিয়ে দিন","কাছে থাকুন, অল্প আর নরম কথা বলুন: “তুমি রাগ করেছ। আমি আছি।”"]},"steps":{"en":["Wait for the storm to pass; do not argue or explain during it","When your child calms, offer a hug and name what happened: “You wanted the phone and I said no”","Do not give in to the thing the tantrum was about, but offer a choice: “Ball or book?”","Keep routines for meals and sleep so your child is not overtired or hungry","Warn before changes: “Two more turns, then bath”","Give lots of attention and praise when your child is calm and cooperative","Agree as a family on the same response, so grandparents and parents do not undo each other"],"bn":["ঝড় থামা পর্যন্ত অপেক্ষা করুন; তখন তর্ক বা বোঝানো নয়","শান্ত হলে জড়িয়ে ধরুন, কী হয়েছিল তার নাম দিন: “তুমি ফোন চাইছিলে, আমি না বলেছি”","যে জিনিসের জন্য জেদ, তা দিয়ে দেবেন না, তবে পছন্দ দিন: “বল, না বই?”","খাওয়া আর ঘুমের রুটিন ঠিক রাখুন, যাতে শিশু বেশি ক্লান্ত বা ক্ষুধার্ত না থাকে","পরিবর্তনের আগে জানিয়ে দিন: “আর দুইবার, তারপর গোসল”","শিশু শান্ত ও সহযোগী থাকলে অনেক মনোযোগ আর প্রশংসা দিন","পরিবারে সবাই একইভাবে সাড়া দিতে একমত হোন, যাতে দাদা-দাদি আর মা-বাবা একে অপরের কাজ উল্টে না দেন"]},"avoid":{"en":["Hitting, slapping or shaking; WHO is clear that physical punishment harms children","Shouting, threats or frightening stories about ghosts or the police","Giving a phone or sweets to stop every tantrum","Shaming in front of others"],"bn":["মারা, চড় দেওয়া বা ঝাঁকানো; বিশ্ব স্বাস্থ্য সংস্থা স্পষ্ট বলে, শারীরিক শাস্তি শিশুর ক্ষতি করে","চিৎকার, হুমকি, বা ভূত কিংবা পুলিশের ভয় দেখানো","প্রতিটি জেদ থামাতে ফোন বা মিষ্টি দেওয়া","অন্যদের সামনে লজ্জা দেওয়া"]},"example":{"en":"At a family dinner, 20-month-old Ruhi screamed and lay on the floor when her uncle''s phone was taken back. Her mother knelt beside her, moved a glass away and said softly “You wanted the phone. It''s hard.” After a few minutes Ruhi climbed into her lap. Her mother then offered “Do you want to give Nanu the spoon or the bowl?” and Ruhi chose the spoon.","bn":"পারিবারিক দাওয়াতে মামার ফোন ফিরিয়ে নেওয়ায় ২০ মাসের রুহি চিৎকার করে মেঝেতে শুয়ে পড়ল। মা পাশে হাঁটু গেড়ে বসলেন, একটা গ্লাস সরিয়ে রাখলেন, নরম গলায় বললেন “তুমি ফোনটা চাইছিলে। খুব কষ্ট লাগছে।” কয়েক মিনিট পর রুহি মায়ের কোলে উঠে এল। তারপর মা বললেন “নানুকে চামচ দেবে, না বাটি?” রুহি চামচটা বেছে নিল।"},"seek_help":{"en":["Tantrums are very long, very frequent or getting worse after age 2","Your child often hurts themselves or holds their breath until they faint","Tantrums come with loss of words, little eye contact or little interest in people","You feel you might lose control or hurt your child: ask for help now"],"bn":["২ বছরের পরে জেদ খুব লম্বা, খুব ঘনঘন বা বাড়ছে","শিশু প্রায়ই নিজেকে আঘাত করে, বা দম আটকে রেখে অজ্ঞান হয়ে যায়","জেদের সাথে শব্দ হারানো, চোখে চোখ কম রাখা বা মানুষের প্রতি আগ্রহ কম","মনে হচ্ছে নিজেকে সামলাতে পারবেন না বা শিশুকে আঘাত করে ফেলবেন: এখনই সাহায্য চান"]}}'::jsonb, 3, 365, 730, '{}'::text[], 'any', ARRAY['tantrums', 'toddler behaviour', 'anger', 'crying', 'positive discipline', 'no hitting']::text[], false, 'in_review'::lp_review_status, 4042),
  ('in-sc-phone-while-eating', 'scenario', 'scientific', 'shared', 'routine', 'guideline', '📱', '{"en":"My child will only eat with the phone on","bn":"ফোন না চালালে শিশু খায় না"}'::jsonb, '{"en":"A common habit that can be changed. Replace the screen step by step with talk, company and self-feeding.","bn":"খুব সাধারণ একটা অভ্যাস, যা বদলানো যায়। ধাপে ধাপে স্ক্রিনের জায়গায় আনুন কথা, সঙ্গ আর নিজে খাওয়া।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Many families start showing cartoons to get food into a fussy child. It seems to work: the child opens the mouth without noticing. Soon, meals without the phone become a battle.","bn":"খেতে না চাওয়া শিশুকে খাওয়াতে অনেক পরিবার কার্টুন দেখানো শুরু করে। মনে হয় কাজ হচ্ছে: শিশু না খেয়াল করেই মুখ খুলছে। কিছুদিন পর ফোন ছাড়া খাওয়ানোই লড়াই হয়ে দাঁড়ায়।"},"why":{"en":"A child watching a screen does not notice taste, texture, hunger or fullness. They miss the talk and eye contact that make meals a time of learning. WHO advises no screen time for children under 2.","bn":"স্ক্রিন দেখতে দেখতে শিশু স্বাদ, ঘনত্ব, খিদে বা পেট ভরা কিছুই খেয়াল করে না। খাওয়ার সময়ের যে কথা আর চোখে চোখ রাখা শেখার সুযোগ দেয়, তা হারায়। বিশ্ব স্বাস্থ্য সংস্থা ২ বছরের কম শিশুর জন্য কোনো স্ক্রিন-সময় না রাখতে বলে।"},"normal":{"en":"Expect protest, eating less and some crying for a few days when you remove the phone. This is the habit breaking, not your child starving.","bn":"ফোন সরালে কয়েক দিন আপত্তি, কম খাওয়া আর কিছু কান্না হবে ধরে নিন। এটা অভ্যাস ভাঙার লক্ষণ, শিশু না খেয়ে থাকছে এমন নয়।"},"do_now":{"en":["Decide together as a family to stop phone and TV at meals, starting with one meal a day","Tell your child simply: “Phone sleeps now. We eat together.”","Put the phone out of sight before bringing the food"],"bn":["পরিবারে সবাই মিলে ঠিক করুন খাওয়ার সময় ফোন ও টিভি বন্ধ, দিনে এক বেলা দিয়ে শুরু","সহজ করে বলুন: “ফোন এখন ঘুমাবে। আমরা একসাথে খাব।”","খাবার আনার আগেই ফোন চোখের আড়ালে রাখুন"]},"steps":{"en":["Start with the meal your child enjoys most","Sit facing your child, talk, sing and name the food","Give finger foods and a spoon so your child has something to do","Let a sibling or parent eat at the same time; children copy","Keep meals short, about 20–30 minutes, and stop calmly","Avoid snacks and milk just before meals so your child comes hungry","Once one meal is screen-free, move to the next, until all meals are"],"bn":["যে বেলার খাবার শিশুর সবচেয়ে পছন্দ, সেটা দিয়ে শুরু করুন","শিশুর মুখোমুখি বসুন, কথা বলুন, গান গান, খাবারের নাম বলুন","হাতে ধরে খাওয়ার মতো খাবার আর একটা চামচ দিন, যাতে কিছু করার থাকে","ভাইবোন বা মা-বাবা একই সময়ে খান; শিশু দেখে শেখে","খাওয়ার সময় ছোট রাখুন, প্রায় ২০–৩০ মিনিট, তারপর শান্তভাবে থামুন","খাবারের ঠিক আগে নাশতা বা দুধ দেবেন না, যাতে খিদে নিয়ে আসে","এক বেলা স্ক্রিনমুক্ত হলে পরের বেলায় যান, যতক্ষণ না সব বেলা স্ক্রিনমুক্ত হয়"]},"avoid":{"en":["Giving the phone back after a few minutes of crying, which teaches that crying works","Swapping the phone for TV","Force-feeding to make up for less food","Adults using phones at the table"],"bn":["কয়েক মিনিট কান্নার পর আবার ফোন দেওয়া, এতে শিশু শেখে কাঁদলেই কাজ হয়","ফোনের বদলে টিভি চালানো","কম খাওয়া পুষিয়ে নিতে জোর করে খাওয়ানো","খাওয়ার সময় বড়দের ফোন ব্যবহার"]},"example":{"en":"Lamia''s 19-month-old son had eaten every meal to cartoons since he was 10 months. The family agreed to stop at lunch first. For three days he cried and ate little; Lamia stayed calm, sat with him and gave him pieces of fish and rice balls to hold. By the second week he was eating lunch while chatting about “fish” and “rice”, and they moved on to dinner.","bn":"লামিয়ার ১৯ মাসের ছেলে ১০ মাস বয়স থেকে প্রতিটি বেলা কার্টুন দেখে খেত। পরিবার ঠিক করল আগে দুপুরের খাবারে বন্ধ করবে। তিন দিন ছেলে কাঁদল, কম খেল; লামিয়া শান্ত থাকলেন, পাশে বসলেন, হাতে ধরার জন্য মাছের টুকরো আর ছোট ভাতের দলা দিলেন। দ্বিতীয় সপ্তাহে ছেলে “মাছ”, “ভাত” বলে গল্প করতে করতে দুপুরে খাচ্ছিল, আর তাঁরা রাতের খাবারেও শুরু করলেন।"},"seek_help":{"en":["Weight falls on the growth card during the change","Your child refuses all food and drink for a whole day","Very little speech or eye contact, or little interest in people, along with heavy screen use"],"bn":["পরিবর্তনের সময় বৃদ্ধি কার্ডে ওজন কমছে","সারাদিন কোনো খাবার বা পানীয়ই নিচ্ছে না","অনেক বেশি স্ক্রিন দেখার সাথে কথা বা চোখে চোখ রাখা খুব কম, বা মানুষের প্রতি আগ্রহ কম"]}}'::jsonb, 3, 274, 730, '{}'::text[], 'any', ARRAY['phone while eating', 'cartoons', 'screen time', 'mealtime', 'feeding habits']::text[], false, 'in_review'::lp_review_status, 4043),
  ('in-sc-not-walking-yet', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🦶', '{"en":"My child is not walking yet at 15–18 months","bn":"১৫–১৮ মাসেও শিশু হাঁটছে না"}'::jsonb, '{"en":"Many healthy children walk between 15 and 18 months. Give lots of floor time, and see a health worker if your child is not walking by 18 months.","bn":"অনেক সুস্থ শিশু ১৫ থেকে ১৮ মাসের মধ্যে হাঁটে। মেঝেতে প্রচুর সময় দিন, আর ১৮ মাসেও না হাঁটলে স্বাস্থ্যকর্মী দেখান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"By 15 months most children take a few steps alone, and by 18 months most walk without holding on. There is a wide normal range, and some healthy children walk a little later than their cousins or neighbours.","bn":"১৫ মাসে বেশিরভাগ শিশু একা কয়েক পা হাঁটে, আর ১৮ মাসে বেশিরভাগ কিছু না ধরে হাঁটে। স্বাভাবিকের সীমা অনেক চওড়া, কিছু সুস্থ শিশু চাচাতো-মামাতো ভাইবোন বা প্রতিবেশীর চেয়ে একটু দেরিতে হাঁটে।"},"why":{"en":"Late walking can run in families, or happen in children who bottom-shuffle, are heavier, were born early, or have spent little time on the floor because they are carried most of the day. Less often it is a sign of a problem with muscles, nerves, joints or nutrition.","bn":"দেরিতে হাঁটা পারিবারিক ধারাও হতে পারে, আবার হতে পারে যে শিশু বসে বসে পাছা ঘষে চলে, ওজন বেশি, সময়ের আগে জন্মেছে, বা সারাদিন কোলে থাকায় মেঝেতে কম সময় পেয়েছে। কম ক্ষেত্রে এটা পেশি, স্নায়ু, জোড়া বা পুষ্টির সমস্যার লক্ষণ।"},"normal":{"en":"A 15–17-month-old who pulls to stand, walks holding furniture or your hands, and is learning other new skills is very likely on the way. Children born early may walk a little later; count from the due date.","bn":"১৫–১৭ মাসের যে শিশু ধরে দাঁড়ায়, আসবাব বা আপনার হাত ধরে হাঁটে, আর অন্যান্য নতুন দক্ষতা শিখছে, সে খুব সম্ভবত হাঁটার পথেই আছে। সময়ের আগে জন্মানো শিশু একটু দেরিতে হাঁটতে পারে; প্রসবের সম্ভাব্য তারিখ থেকে হিসাব করুন।"},"do_now":{"en":["Look at what your child can do: stand holding on, cruise, stand alone for a moment?","Notice other skills: words, pointing, using both hands, understanding you","Check the growth card for weight and length"],"bn":["দেখুন শিশু কী কী পারে: ধরে দাঁড়ায়, আসবাব ধরে হাঁটে, এক মুহূর্ত একা দাঁড়ায়?","অন্য দক্ষতাও খেয়াল করুন: শব্দ, আঙুল দিয়ে দেখানো, দুই হাত ব্যবহার, আপনার কথা বোঝা","বৃদ্ধি কার্ডে ওজন ও দৈর্ঘ্য দেখুন"]},"steps":{"en":["Give plenty of time on a safe, clean floor instead of being carried or sitting in a seat","Let your child walk barefoot indoors","Put toys on a low bench or bed so they practise standing and cruising","Let them push a heavy box or a stable chair","Hold both hands and walk together, then one hand","Kneel a short distance away and invite them to step to you; cheer every try","Keep an animal food, egg or fish, in the diet every day for strong muscles and bones"],"bn":["কোলে বা আসনে না রেখে নিরাপদ, পরিষ্কার মেঝেতে প্রচুর সময় দিন","ঘরে খালি পায়ে হাঁটতে দিন","নিচু টুল বা খাটে খেলনা রাখুন, যাতে দাঁড়ানো আর ধরে হাঁটা অভ্যাস হয়","ভারী বাক্স বা নড়বড়ে নয় এমন চেয়ার ঠেলতে দিন","দুই হাত ধরে একসাথে হাঁটুন, পরে এক হাত","একটু দূরে হাঁটু গেড়ে বসে আপনার দিকে পা ফেলতে ডাকুন; প্রতিটি চেষ্টায় উৎসাহ দিন","শক্ত পেশি ও হাড়ের জন্য প্রতিদিন খাবারে ডিম বা মাছের মতো প্রাণিজ খাবার রাখুন"]},"avoid":{"en":["Baby walkers, which do not help and cause injuries","Pulling or forcing a child to stand on their legs","Massaging with force or tying the legs to “straighten” them","Comparing your child with others in front of them"],"bn":["ওয়াকার, যা সাহায্য করে না বরং আঘাত ঘটায়","জোর করে টেনে পায়ে দাঁড় করানো","জোরে মালিশ বা পা “সোজা” করতে বেঁধে রাখা","শিশুর সামনে অন্যদের সাথে তুলনা করা"]},"example":{"en":"At 16 months, Nabil was walking holding the wall but not alone, and his grandmother worried. His parents stopped carrying him for most of the day, put his toys on the chouki edge, and his father knelt across the room each evening calling “Come to Abbu!”. Nabil took his first steps alone at 17 months.","bn":"১৬ মাসে নাবিল দেয়াল ধরে হাঁটত, কিন্তু একা না; দাদি চিন্তায় পড়লেন। মা-বাবা সারাদিন কোলে রাখা বন্ধ করলেন, খেলনা চৌকির কিনারায় রাখলেন, আর প্রতি সন্ধ্যায় বাবা ঘরের অপর পাশে হাঁটু গেড়ে বসে ডাকতেন “আব্বুর কাছে আসো!”। ১৭ মাসে নাবিল একা প্রথম পা ফেলল।"},"warning_signs":{"en":["Not walking alone by 18 months","Not pulling to stand or bearing weight on the legs by about 12–15 months","Loses skills they had","Legs very stiff or very floppy, or one side weaker than the other","Also slow with words, understanding or using the hands"],"bn":["১৮ মাসেও একা হাঁটে না","প্রায় ১২–১৫ মাসেও ধরে দাঁড়ায় না বা পায়ে ভর দেয় না","আগে পারত এমন দক্ষতা হারাচ্ছে","পা খুব শক্ত বা খুব নরম-নেতানো, বা এক পাশ অন্য পাশের চেয়ে দুর্বল","সাথে কথা, বোঝা বা হাত ব্যবহারেও পিছিয়ে"]},"seek_help":{"en":["Not walking alone by 18 months: see a health worker or doctor for a check","Any other warning sign: ask early, at any age","Your instinct tells you something is not right"],"bn":["১৮ মাসেও একা না হাঁটলে: পরীক্ষার জন্য স্বাস্থ্যকর্মী বা ডাক্তার দেখান","অন্য যেকোনো বিপদের লক্ষণ: যেকোনো বয়সে আগেভাগে জিজ্ঞেস করুন","আপনার মন বলছে কিছু ঠিক নেই"]}}'::jsonb, 3, 457, 730, '{}'::text[], 'any', ARRAY['not walking', 'late walker', '15 months', '18 months', 'motor delay', 'development']::text[], false, 'in_review'::lp_review_status, 4044)
