INSERT INTO lp_task_templates (key, title, description, why, benefit, steps, safety_note, task_type, frequency, assignee, subject, min_day, max_day, estimated_minutes, xp, emoji, category_key, resource_slug, source_key, sex, review_status, sort_order) VALUES
  ('in_animal_food_today', '{"en":"Give an egg, fish or meat today","bn":"আজ ডিম, মাছ বা মাংস দিন"}'::jsonb, '{"en":"Add one animal food to at least one meal: egg, fish, chicken, meat or liver.","bn":"অন্তত এক বেলার খাবারে একটি প্রাণিজ খাবার যোগ করুন: ডিম, মাছ, মুরগি, মাংস বা কলিজা।"}'::jsonb, '{"en":"WHO advises an animal food every day from 6 months for iron, zinc and protein that rice and lentils alone cannot give.","bn":"শুধু ভাত-ডাল থেকে যে আয়রন, জিংক ও আমিষ মেলে না, তার জন্য বিশ্ব স্বাস্থ্য সংস্থা ৬ মাস থেকে প্রতিদিন একটি প্রাণিজ খাবার দিতে বলে।"}'::jsonb, '{"en":"Stronger growth and less risk of anaemia.","bn":"ভালো বৃদ্ধি, রক্তস্বল্পতার ঝুঁকি কম।"}'::jsonb, '[{"en":"Cook it fully; no runny egg.","bn":"পুরোপুরি সেদ্ধ করুন; তরল কুসুম নয়।"},{"en":"Remove every fish bone.","bn":"মাছের প্রতিটি কাঁটা বেছে ফেলুন।"},{"en":"Mash or chop to suit your child''s age.","bn":"শিশুর বয়স মতো চটকে বা কুচি করে দিন।"}]'::jsonb, '{"en":"Stop and see a doctor if lips or face swell after a new food.","bn":"নতুন খাবারের পর ঠোঁট বা মুখ ফুলে গেলে বন্ধ করে ডাক্তার দেখান।"}'::jsonb, 'recommended', 'daily', 'shared', 'child', 183, 730, 10, 5, '🥚', 'complementary_feeding', 'in-food-variety-iron-egg', 'who_iycf', 'any', 'in_review'::lp_review_status, 4001),
  ('in_wash_hands_feeding', '{"en":"Wash hands with soap before every feed","bn":"প্রতিবার খাওয়ানোর আগে সাবান দিয়ে হাত ধুন"}'::jsonb, '{}'::jsonb, '{"en":"Germs on hands are a main cause of diarrhoea in young children. Soap and water before cooking and feeding prevents much of it.","bn":"হাতের জীবাণু ছোট শিশুর ডায়রিয়ার একটি প্রধান কারণ। রান্না ও খাওয়ানোর আগে সাবান-পানিতে হাত ধুলে এর অনেকটাই ঠেকানো যায়।"}'::jsonb, '{"en":"Fewer tummy infections and more healthy days.","bn":"পেটের অসুখ কম, সুস্থ দিন বেশি।"}'::jsonb, '[{"en":"Wash your hands and your child''s hands with soap.","bn":"নিজের ও শিশুর হাত সাবান দিয়ে ধুয়ে নিন।"},{"en":"Use a clean bowl, cup and spoon.","bn":"পরিষ্কার বাটি, কাপ ও চামচ ব্যবহার করুন।"},{"en":"Also wash after the toilet and nappy changes.","bn":"টয়লেট ও ন্যাপি বদলানোর পরেও ধুয়ে নিন।"}]'::jsonb, '{}'::jsonb, 'must_do', 'daily', 'any', 'child', 183, 730, 2, 5, '🧼', 'food_safety', 'in-food-hygiene-choking', 'who_diarrhoea', 'any', 'in_review'::lp_review_status, 4002),
  ('in_water_safety_check', '{"en":"Water safety round: cover containers, check the pond path","bn":"পানির নিরাপত্তা টহল: পাত্র ঢাকুন, পুকুরের পথ দেখুন"}'::jsonb, '{"en":"Walk around the home and yard once a week, ideally together as parents.","bn":"সপ্তাহে একবার ঘর ও উঠান ঘুরে দেখুন, সম্ভব হলে মা-বাবা একসাথে।"}'::jsonb, '{"en":"Drowning is a leading cause of death for young children in Bangladesh, and most happen close to home. Barriers save lives.","bn":"বাংলাদেশে ছোট শিশুদের মৃত্যুর একটি প্রধান কারণ পানিতে ডোবা, আর বেশিরভাগই ঘটে বাড়ির কাছে। বাধা জীবন বাঁচায়।"}'::jsonb, '{"en":"A safer home every week, as your child learns to move.","bn":"শিশু চলতে শেখার সাথে সাথে প্রতি সপ্তাহে আরও নিরাপদ ঘর।"}'::jsonb, '[{"en":"Cover or empty buckets, drums and tanks; turn basins over.","bn":"বালতি, ড্রাম ও ট্যাংক ঢাকুন বা খালি করুন; গামলা উল্টে রাখুন।"},{"en":"Check the fence or gate on the path to the pond or ditch.","bn":"পুকুর বা ডোবার পথের বেড়া বা গেট ঠিক আছে কিনা দেখুন।"},{"en":"Agree who watches the child during cooking and washing times.","bn":"রান্না ও ধোয়ামোছার সময় কে শিশুকে দেখবেন, ঠিক করে নিন।"}]'::jsonb, '{}'::jsonb, 'must_do', 'weekly', 'shared', 'family', 183, 730, 10, 15, '🌊', 'safety', 'in-water-safety', 'who_drowning', 'any', 'in_review'::lp_review_status, 4003),
  ('in_name_things_walk', '{"en":"Take a short walk and name what you see","bn":"একটু হেঁটে আসুন, যা দেখছেন তার নাম বলুন"}'::jsonb, '{}'::jsonb, '{"en":"Naming real things your child points at builds words faster than any screen, and fresh air and movement help sleep.","bn":"শিশু যেদিকে আঙুল তোলে, সেই সত্যিকারের জিনিসের নাম বললে যেকোনো স্ক্রিনের চেয়ে দ্রুত শব্দ শেখে; খোলা বাতাস আর হাঁটাচলায় ঘুমও ভালো হয়।"}'::jsonb, '{"en":"New words and a calmer child.","bn":"নতুন শব্দ আর শান্ত শিশু।"}'::jsonb, '[{"en":"Carry your child or walk hand in hand, away from roads and water.","bn":"শিশুকে কোলে নিয়ে বা হাত ধরে হাঁটুন, রাস্তা আর পানি থেকে দূরে।"},{"en":"Name what they look at: cow, crow, tree, rickshaw.","bn":"যা দেখছে তার নাম বলুন: গরু, কাক, গাছ, রিকশা।"},{"en":"Wait for them to point or babble, then answer.","bn":"আঙুল তোলা বা আধো বুলির জন্য অপেক্ষা করুন, তারপর উত্তর দিন।"}]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'any', 'child', 274, 730, 10, 5, '🚶', 'language', 'in-first-words', 'who_nurturing_care', 'any', 'in_review'::lp_review_status, 4004),
  ('in_vitamin_a_campaign', '{"en":"Check for the next vitamin A campaign day","bn":"পরের ভিটামিন এ ক্যাম্পেইনের দিন জেনে নিন"}'::jsonb, '{"en":"Ask your health worker or community clinic when the next national vitamin A campaign is, and whether deworming is due for your child''s age.","bn":"পরের জাতীয় ভিটামিন এ ক্যাম্পেইন কবে, আর শিশুর বয়সে কৃমিনাশক দেওয়ার সময় হয়েছে কিনা, স্বাস্থ্যকর্মী বা কমিউনিটি ক্লিনিকে জিজ্ঞেস করুন।"}'::jsonb, '{"en":"Vitamin A capsules from the national campaign help protect young children from serious infections. They are free and quick.","bn":"জাতীয় ক্যাম্পেইনের ভিটামিন এ ক্যাপসুল ছোট শিশুকে গুরুতর সংক্রমণ থেকে রক্ষায় সাহায্য করে। বিনামূল্যে, আর সময়ও লাগে অল্প।"}'::jsonb, '{"en":"Your child does not miss a free protective dose.","bn":"শিশু বিনামূল্যের সুরক্ষা ডোজ থেকে বাদ পড়ে না।"}'::jsonb, '[]'::jsonb, '{"en":"Only the health worker gives the capsule; never give vitamin A capsules at home on your own.","bn":"ক্যাপসুল শুধু স্বাস্থ্যকর্মী খাওয়াবেন; নিজে বাড়িতে কখনো ভিটামিন এ ক্যাপসুল খাওয়াবেন না।"}'::jsonb, 'must_do', 'quarterly', 'shared', 'child', 183, 730, 30, 15, '💊', 'medical_care', 'in-vitamin-a-deworming', 'who_imci', 'any', 'in_review'::lp_review_status, 4005),
  ('in_family_meal', '{"en":"Eat one meal together as a family, no screens","bn":"পরিবারের সবাই মিলে এক বেলা খান, স্ক্রিন ছাড়া"}'::jsonb, '{}'::jsonb, '{"en":"From 12 months children can eat family food. Eating together shows them how to eat, builds language and makes meals calmer.","bn":"১২ মাস থেকে শিশু পরিবারের খাবার খেতে পারে। একসাথে খেলে শিশু দেখে দেখে খেতে শেখে, ভাষা বাড়ে, খাওয়ার সময়ও শান্ত হয়।"}'::jsonb, '{"en":"A child who enjoys family food and family time.","bn":"পরিবারের খাবার আর পরিবারের সময় উপভোগ করা শিশু।"}'::jsonb, '[{"en":"Take out your child''s portion before adding chilli and extra salt.","bn":"মরিচ ও বাড়তি লবণ দেওয়ার আগে শিশুর অংশ তুলে রাখুন।"},{"en":"Seat your child with the family, upright and safe.","bn":"শিশুকে সোজা ও নিরাপদে পরিবারের সাথে বসান।"},{"en":"Phones and TV off for everyone.","bn":"সবার ফোন ও টিভি বন্ধ।"}]'::jsonb, '{}'::jsonb, 'family', 'daily', 'shared', 'family', 365, 730, 25, 10, '🍛', 'complementary_feeding', 'in-responsive-feeding', 'who_iycf', 'any', 'in_review'::lp_review_status, 4006),
  ('in_offer_cup', '{"en":"Offer water from an open cup","bn":"খোলা কাপে পানি দিন"}'::jsonb, '{}'::jsonb, '{"en":"Cups are easier to keep clean than feeding bottles and help your child learn to drink by themselves.","bn":"ফিডারের চেয়ে কাপ পরিষ্কার রাখা সহজ, আর কাপে শিশু নিজে নিজে পান করতে শেখে।"}'::jsonb, '{"en":"Fewer germs, and a new skill by about 18 months.","bn":"জীবাণু কম, আর প্রায় ১৮ মাসে নতুন একটা দক্ষতা।"}'::jsonb, '[{"en":"Use a small, clean cup with a little safe water.","bn":"ছোট পরিষ্কার কাপে অল্প নিরাপদ পানি নিন।"},{"en":"Hold it to your baby''s lips and let them sip; do not pour.","bn":"শিশুর ঠোঁটে ধরে চুমুক দিতে দিন; ঢেলে দেবেন না।"},{"en":"Let older babies hold it with both hands; spills are fine.","bn":"একটু বড় শিশুকে দুই হাতে ধরতে দিন; পড়ে গেলেও সমস্যা নেই।"}]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'any', 'child', 183, 730, 5, 5, '🥛', 'complementary_feeding', 'in-food-hygiene-choking', 'who_iycf', 'any', 'in_review'::lp_review_status, 4007),
  ('in_finger_food', '{"en":"Let your child feed themselves a soft finger food","bn":"নরম টুকরো খাবার শিশুকে নিজে তুলে খেতে দিন"}'::jsonb, '{}'::jsonb, '{"en":"By about 8 months most babies can pick up and eat soft pieces. Self-feeding builds hand skills and a healthy interest in food.","bn":"প্রায় ৮ মাসে বেশিরভাগ শিশু নরম টুকরো তুলে খেতে পারে। নিজে খেলে হাতের দক্ষতা বাড়ে, খাবারে আগ্রহও জন্মায়।"}'::jsonb, '{"en":"A more independent eater and calmer meals.","bn":"নিজে খেতে শেখা শিশু আর শান্ত খাওয়ার সময়।"}'::jsonb, '[{"en":"Offer soft pieces: banana, boiled potato, omelette strips, soft roti.","bn":"নরম টুকরো দিন: কলা, সেদ্ধ আলু, ডিমভাজির ফালি, নরম রুটি।"},{"en":"Sit your child upright and stay with them.","bn":"শিশুকে সোজা করে বসান, পাশে থাকুন।"},{"en":"Let them make a mess; it is part of learning.","bn":"নোংরা করতে দিন; এটাও শেখার অংশ।"}]'::jsonb, '{"en":"No whole nuts, whole litchi, grapes or hard raw pieces.","bn":"আস্ত বাদাম, আস্ত লিচু, আঙুর বা শক্ত কাঁচা টুকরো নয়।"}'::jsonb, 'recommended', 'daily', 'any', 'child', 243, 730, 10, 5, '🍌', 'complementary_feeding', 'in-recipe-egg', 'who_iycf', 'any', 'in_review'::lp_review_status, 4008)
